CREATE TABLE "assistant_definitions" (
    id                                   TEXT PRIMARY KEY NOT NULL,
    user_id                              TEXT REFERENCES users(id),
    assistant_id                         TEXT NOT NULL,
    source                               TEXT NOT NULL
                                             CHECK (source IN ('builtin', 'user', 'generated')),
    owner_type                           TEXT NOT NULL
                                             CHECK (owner_type IN ('system', 'user')),
    source_ref                           TEXT,
    name                                 TEXT NOT NULL,
    name_i18n                            TEXT NOT NULL DEFAULT '{}',
    description                          TEXT,
    description_i18n                     TEXT NOT NULL DEFAULT '{}',
    avatar_type                          TEXT NOT NULL DEFAULT 'none'
                                             CHECK (avatar_type IN ('none', 'emoji', 'builtin_asset', 'user_asset')),
    avatar_value                         TEXT,
    agent_id                             TEXT NOT NULL,
    rule_resource_type                   TEXT NOT NULL
                                             CHECK (rule_resource_type IN ('none', 'builtin_asset', 'user_file', 'extension')),
    rule_resource_ref                    TEXT,
    recommended_prompts                  TEXT NOT NULL DEFAULT '[]',
    recommended_prompts_i18n             TEXT NOT NULL DEFAULT '{}',
    default_model_mode                   TEXT NOT NULL
                                             CHECK (default_model_mode IN ('auto', 'fixed')),
    default_model_value                  TEXT,
    default_permission_mode              TEXT NOT NULL
                                             CHECK (default_permission_mode IN ('auto', 'fixed')),
    default_permission_value             TEXT,
    default_thought_level_mode           TEXT NOT NULL DEFAULT 'auto'
                                             CHECK (default_thought_level_mode IN ('auto', 'fixed')),
    default_thought_level_value          TEXT,
    default_skills_mode                  TEXT NOT NULL
                                             CHECK (default_skills_mode IN ('auto', 'fixed')),
    default_skill_ids                    TEXT NOT NULL DEFAULT '[]',
    custom_skill_names                   TEXT NOT NULL DEFAULT '[]',
    default_disabled_builtin_skill_ids   TEXT NOT NULL DEFAULT '[]',
    default_mcps_mode                    TEXT NOT NULL
                                             CHECK (default_mcps_mode IN ('auto', 'fixed')),
    default_mcp_ids                      TEXT NOT NULL DEFAULT '[]',
    created_at                           INTEGER NOT NULL,
    updated_at                           INTEGER NOT NULL,
    deleted_at                           INTEGER
);
CREATE TABLE "assistant_overlays" (
    user_id                 TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    assistant_definition_id TEXT NOT NULL,
    enabled                 INTEGER NOT NULL DEFAULT 1,
    sort_order              INTEGER NOT NULL DEFAULT 0,
    agent_id_override       TEXT,
    last_used_at            INTEGER,
    created_at              INTEGER NOT NULL,
    updated_at              INTEGER NOT NULL,
    PRIMARY KEY (user_id, assistant_definition_id),
    FOREIGN KEY (assistant_definition_id) REFERENCES assistant_definitions(id) ON DELETE CASCADE
);
CREATE TABLE "assistant_overrides" (
    user_id           TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    assistant_id      TEXT NOT NULL,
    enabled           INTEGER NOT NULL DEFAULT 1,
    sort_order        INTEGER NOT NULL DEFAULT 0,
    last_used_at      INTEGER,
    updated_at        INTEGER NOT NULL,
    PRIMARY KEY (user_id, assistant_id)
);
CREATE TABLE "assistant_pairing_codes" (
    code             TEXT NOT NULL,
    owner_user_id    TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    platform_user_id TEXT NOT NULL,
    platform_type    TEXT NOT NULL,
    display_name     TEXT,
    requested_at     INTEGER NOT NULL,
    expires_at       INTEGER NOT NULL,
    status           TEXT NOT NULL DEFAULT 'pending'
                             CHECK (status IN ('pending', 'approved', 'rejected', 'expired')),
    PRIMARY KEY (owner_user_id, code)
);
CREATE TABLE "assistant_plugins" (
    id             TEXT    NOT NULL,
    owner_user_id  TEXT    NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    type           TEXT    NOT NULL,
    name           TEXT    NOT NULL,
    enabled        INTEGER NOT NULL DEFAULT 0,
    config         TEXT    NOT NULL,
    status         TEXT,
    last_connected INTEGER,
    created_at     INTEGER NOT NULL,
    updated_at     INTEGER NOT NULL,
    PRIMARY KEY (owner_user_id, id)
);
CREATE TABLE "assistant_preferences" (
    user_id                              TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    assistant_definition_id              TEXT NOT NULL,
    last_model_id                        TEXT,
    last_permission_value                TEXT,
    last_skill_ids                       TEXT    NOT NULL DEFAULT '[]',
    last_disabled_builtin_skill_ids      TEXT    NOT NULL DEFAULT '[]',
    last_mcp_ids                         TEXT    NOT NULL DEFAULT '[]',
    created_at                           INTEGER NOT NULL,
    updated_at                           INTEGER NOT NULL,
    last_thought_level_value             TEXT,
    PRIMARY KEY (user_id, assistant_definition_id),
    FOREIGN KEY (assistant_definition_id) REFERENCES assistant_definitions(id) ON DELETE CASCADE
);
CREATE TABLE "assistant_sessions" (
    id              TEXT PRIMARY KEY NOT NULL,
    user_id         TEXT    NOT NULL,
    agent_type      TEXT    NOT NULL,
    conversation_id TEXT,
    workspace       TEXT,
    chat_id         TEXT,
    created_at      INTEGER NOT NULL,
    last_activity   INTEGER NOT NULL,
    FOREIGN KEY (user_id) REFERENCES assistant_users(id) ON DELETE CASCADE,
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE SET NULL
);
CREATE TABLE "assistant_users" (
    id               TEXT PRIMARY KEY NOT NULL,
    owner_user_id    TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    platform_user_id TEXT NOT NULL,
    platform_type    TEXT NOT NULL,
    display_name     TEXT,
    authorized_at    INTEGER NOT NULL,
    last_active      INTEGER,
    session_id       TEXT,
    UNIQUE (owner_user_id, platform_user_id, platform_type)
);
CREATE TABLE "assistants" (
    id                      TEXT PRIMARY KEY,
    name                    TEXT NOT NULL,
    description             TEXT,
    avatar                  TEXT,
    enabled_skills          TEXT,
    custom_skill_names      TEXT,
    disabled_builtin_skills TEXT,
    prompts                 TEXT,
    models                  TEXT,
    name_i18n               TEXT,
    description_i18n        TEXT,
    prompts_i18n            TEXT,
    created_at              INTEGER NOT NULL,
    updated_at              INTEGER NOT NULL
, user_id TEXT REFERENCES users(id));
CREATE TABLE "client_preferences" (
    user_id    TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    key        TEXT NOT NULL,
    value      TEXT NOT NULL,
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (user_id, key)
);
CREATE TABLE conversation_artifacts (
    id              TEXT PRIMARY KEY NOT NULL,
    conversation_id TEXT    NOT NULL,
    cron_job_id     TEXT,
    kind            TEXT    NOT NULL
                            CHECK(kind IN ('cron_trigger', 'skill_suggest')),
    status          TEXT    NOT NULL DEFAULT 'active'
                            CHECK(status IN ('active', 'pending', 'dismissed', 'saved')),
    payload         TEXT    NOT NULL DEFAULT '{}',
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL,
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);
CREATE TABLE conversation_assistant_snapshots (
    conversation_id                        TEXT PRIMARY KEY,
    assistant_definition_id                TEXT    NOT NULL,
    assistant_id                          TEXT    NOT NULL,
    assistant_source                       TEXT    NOT NULL,
    agent_id                          TEXT    NOT NULL,
    rules_content                          TEXT    NOT NULL DEFAULT '',
    default_model_mode                     TEXT    NOT NULL
                                                   CHECK (default_model_mode IN ('auto', 'fixed')),
    resolved_model_id                      TEXT,
    default_permission_mode                TEXT    NOT NULL
                                                   CHECK (default_permission_mode IN ('auto', 'fixed')),
    resolved_permission_value              TEXT,
    default_skills_mode                    TEXT    NOT NULL
                                                   CHECK (default_skills_mode IN ('auto', 'fixed')),
    resolved_skill_ids                     TEXT    NOT NULL DEFAULT '[]',
    resolved_disabled_builtin_skill_ids    TEXT    NOT NULL DEFAULT '[]',
    default_mcps_mode                      TEXT    NOT NULL
                                                   CHECK (default_mcps_mode IN ('auto', 'fixed')),
    resolved_mcp_ids                       TEXT    NOT NULL DEFAULT '[]',
    created_at                             INTEGER NOT NULL,
    updated_at                             INTEGER NOT NULL, default_thought_level_mode TEXT NOT NULL DEFAULT 'auto'
        CHECK (default_thought_level_mode IN ('auto', 'fixed')), resolved_thought_level_value TEXT,
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
    FOREIGN KEY (assistant_definition_id) REFERENCES assistant_definitions(id) ON DELETE CASCADE
);
CREATE TABLE "conversations" (
    id              TEXT    PRIMARY KEY NOT NULL,
    user_id         TEXT    NOT NULL,
    name            TEXT    NOT NULL,
    type            TEXT    NOT NULL,
    extra           TEXT    NOT NULL DEFAULT '{}',
    model           TEXT,
    status          TEXT    NOT NULL DEFAULT 'pending'
                            CHECK(status IN ('pending', 'running', 'finished')),
    source          TEXT,
    channel_chat_id TEXT,
    pinned          INTEGER NOT NULL DEFAULT 0,
    pinned_at       INTEGER,
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL, project_id TEXT, folder_id TEXT, name_source TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE cron_job_runs (
    id              TEXT NOT NULL PRIMARY KEY,
    job_id          TEXT NOT NULL,
    scheduled_at    INTEGER NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('running', 'retrying', 'ok', 'error', 'skipped')),
    owner_id        TEXT,
    lease_until     INTEGER,
    conversation_id TEXT,
    error           TEXT,
    started_at      INTEGER,
    finished_at     INTEGER,
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL,
    UNIQUE(job_id, scheduled_at),
    FOREIGN KEY (job_id) REFERENCES cron_jobs(id) ON DELETE CASCADE
);
CREATE TABLE "cron_jobs" (
    id                   TEXT    PRIMARY KEY NOT NULL,
    name                 TEXT    NOT NULL,
    enabled              INTEGER NOT NULL DEFAULT 1,
    schedule_kind        TEXT    NOT NULL CHECK(schedule_kind IN ('at', 'every', 'cron')),
    schedule_value       TEXT    NOT NULL,
    schedule_tz          TEXT,
    schedule_description TEXT,
    payload_message      TEXT    NOT NULL,
    execution_mode       TEXT    NOT NULL DEFAULT 'existing'
                                 CHECK(execution_mode IN ('existing', 'new_conversation')),
    agent_config         TEXT,
    conversation_id      TEXT    NOT NULL,
    conversation_title   TEXT,
    created_by           TEXT    NOT NULL CHECK(created_by IN ('user', 'agent')),
    skill_content        TEXT,
    description          TEXT,
    created_at           INTEGER NOT NULL,
    updated_at           INTEGER NOT NULL,
    next_run_at          INTEGER,
    last_run_at          INTEGER,
    last_status          TEXT    CHECK(last_status IN ('ok', 'error', 'skipped', 'missed')),
    last_error           TEXT,
    run_count            INTEGER NOT NULL DEFAULT 0,
    retry_count          INTEGER NOT NULL DEFAULT 0,
    max_retries          INTEGER NOT NULL DEFAULT 3
, queue_enabled INTEGER NOT NULL DEFAULT 0, user_id TEXT NOT NULL DEFAULT 'system_default_user');
CREATE TABLE folders (
    id                 INTEGER PRIMARY KEY AUTOINCREMENT, -- internal surrogate, not a business identity
    folder_id          TEXT    NOT NULL,                  -- stable identity, UUID v7
    resource_uri       TEXT    NOT NULL,                  -- raw input provider URI
    resource_canonical TEXT    NOT NULL,                  -- lexical canonical resource URI
    created_at         INTEGER NOT NULL,                  -- epoch ms
    updated_at         INTEGER NOT NULL                   -- epoch ms
);
CREATE TABLE "mailbox" (
    id            TEXT    PRIMARY KEY NOT NULL,
    team_id       TEXT    NOT NULL,
    to_agent_id   TEXT    NOT NULL,
    from_agent_id TEXT    NOT NULL,
    type          TEXT    NOT NULL CHECK (type IN ('message', 'idle_notification', 'shutdown_request')),
    content       TEXT    NOT NULL,
    summary       TEXT,
    files         TEXT,
    read          INTEGER NOT NULL DEFAULT 0,
    created_at    INTEGER NOT NULL
);
CREATE TABLE "mcp_servers" (
    id               TEXT PRIMARY KEY NOT NULL,
    user_id          TEXT    NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    name             TEXT    NOT NULL,
    description      TEXT,
    enabled          INTEGER NOT NULL DEFAULT 0,
    transport_type   TEXT    NOT NULL,
    transport_config TEXT    NOT NULL,
    tools            TEXT,
    last_test_status TEXT    NOT NULL DEFAULT 'disconnected',
    last_connected   INTEGER,
    original_json    TEXT,
    builtin          INTEGER NOT NULL DEFAULT 0,
    deleted_at       INTEGER,
    created_at       INTEGER NOT NULL,
    updated_at       INTEGER NOT NULL,
    UNIQUE (user_id, name)
);
CREATE TABLE "messages" (
    id              TEXT    PRIMARY KEY NOT NULL,
    conversation_id TEXT    NOT NULL,
    msg_id          TEXT,
    type            TEXT    NOT NULL,
    content         TEXT    NOT NULL DEFAULT '{}',
    position        TEXT    CHECK(position IN ('left', 'right', 'center', 'pop')),
    status          TEXT    CHECK(status IN ('finish', 'pending', 'error', 'work')),
    hidden          INTEGER NOT NULL DEFAULT 0,
    created_at      INTEGER NOT NULL, backend_turn_id TEXT,
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);
CREATE TABLE "oauth_tokens" (
    user_id       TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    server_url    TEXT NOT NULL,
    access_token  TEXT NOT NULL,
    refresh_token TEXT,
    token_type    TEXT NOT NULL DEFAULT 'bearer',
    expires_at    INTEGER,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL,
    PRIMARY KEY (user_id, server_url)
);
CREATE TABLE "project_explorer" (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    pe_id         TEXT    NOT NULL,
    project_id    TEXT    NOT NULL,
    owner_user_id TEXT    NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    folder_id     TEXT    NOT NULL,
    role          TEXT    NOT NULL,
    display_name  TEXT,
    order_index   INTEGER NOT NULL DEFAULT 0,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL
);
CREATE TABLE "projects" (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT    NOT NULL,
    user_id    TEXT    NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),
    name       TEXT    NOT NULL,
    kind       TEXT    NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE TABLE providers (
    id                TEXT PRIMARY KEY NOT NULL,
    platform          TEXT    NOT NULL,
    name              TEXT    NOT NULL,
    base_url          TEXT    NOT NULL,
    api_key_encrypted TEXT    NOT NULL,
    models            TEXT    NOT NULL DEFAULT '[]',
    enabled           INTEGER NOT NULL DEFAULT 1,
    capabilities      TEXT    NOT NULL DEFAULT '[]',
    context_limit     INTEGER,
    model_protocols   TEXT,
    model_enabled     TEXT,
    model_health      TEXT,
    bedrock_config    TEXT,
    created_at        INTEGER NOT NULL,
    updated_at        INTEGER NOT NULL
, is_full_url INTEGER NOT NULL DEFAULT 0, model_settings TEXT NOT NULL DEFAULT '{}'
CHECK (json_valid(model_settings)), user_id TEXT NOT NULL DEFAULT 'system_default_user');
CREATE TABLE "remote_agents" (
    id                 TEXT PRIMARY KEY NOT NULL,
    name               TEXT    NOT NULL,
    protocol           TEXT    NOT NULL,
    url                TEXT    NOT NULL,
    auth_type          TEXT    NOT NULL,
    auth_token         TEXT,
    allow_insecure     INTEGER NOT NULL DEFAULT 0,
    avatar             TEXT,
    description        TEXT,
    device_id          TEXT,
    device_public_key  TEXT,
    device_private_key TEXT,
    device_token       TEXT,
    status             TEXT    NOT NULL DEFAULT 'unknown',
    last_connected_at  INTEGER,
    created_at         INTEGER NOT NULL,
    updated_at         INTEGER NOT NULL
, user_id TEXT NOT NULL DEFAULT 'system_default_user');
CREATE TABLE skill_import_records (
    id           TEXT    PRIMARY KEY NOT NULL,
    operation_id TEXT    NOT NULL,

    source_label TEXT    NOT NULL,
    source_path  TEXT,
    source_name  TEXT    NOT NULL,

    skill_id     TEXT,
    skill_name   TEXT,

    status       TEXT    NOT NULL
                          CHECK (status IN ('imported', 'failed', 'overwritten')),
    error_code   TEXT,

    error_path   TEXT,
    actual_bytes INTEGER,
    limit_bytes  INTEGER,
    line         INTEGER,
    column       INTEGER,

    created_at   INTEGER NOT NULL, user_id TEXT NOT NULL DEFAULT 'system_default_user' REFERENCES users(id),

    FOREIGN KEY (skill_id) REFERENCES skills(id)
);
CREATE TABLE "skills" (
    id          TEXT    PRIMARY KEY NOT NULL,
    user_id     TEXT    REFERENCES users(id),
    name        TEXT    NOT NULL,
    description TEXT,
    path        TEXT    NOT NULL,
    source      TEXT    NOT NULL DEFAULT 'user'
                            CHECK (source IN ('user', 'builtin', 'extension', 'cron')),
    enabled     INTEGER NOT NULL DEFAULT 1,
    deleted_at  INTEGER,
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL
);
