CREATE TABLE "system_settings" (
    user_id                   TEXT PRIMARY KEY NOT NULL REFERENCES users(id),
    language                  TEXT    NOT NULL DEFAULT 'en-US',
    notification_enabled      INTEGER NOT NULL DEFAULT 1,
    cron_notification_enabled INTEGER NOT NULL DEFAULT 0,
    command_queue_enabled     INTEGER NOT NULL DEFAULT 0,
    save_upload_to_workspace  INTEGER NOT NULL DEFAULT 0,
    updated_at                INTEGER NOT NULL
);
CREATE TABLE "team_tasks" (
    id          TEXT    PRIMARY KEY NOT NULL,
    team_id     TEXT    NOT NULL,
    subject     TEXT    NOT NULL,
    description TEXT,
    status      TEXT    NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'in_progress', 'completed', 'deleted')),
    owner       TEXT,
    blocked_by  TEXT    NOT NULL DEFAULT '[]',
    blocks      TEXT    NOT NULL DEFAULT '[]',
    metadata    TEXT,
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL
);
CREATE TABLE "teams" (
    id             TEXT PRIMARY KEY NOT NULL,
    user_id        TEXT    NOT NULL DEFAULT 'system_default_user',
    name           TEXT    NOT NULL,
    workspace      TEXT    NOT NULL DEFAULT '',
    workspace_mode TEXT    NOT NULL DEFAULT 'shared',
    agents         TEXT    NOT NULL DEFAULT '[]',
    lead_agent_id  TEXT,
    session_mode   TEXT,
    agents_version TEXT    NOT NULL DEFAULT '1.0.0',
    created_at     INTEGER NOT NULL,
    updated_at     INTEGER NOT NULL
, project_id TEXT, folder_id TEXT);
CREATE TABLE "users" (
    id                 TEXT PRIMARY KEY NOT NULL,
    user_type          TEXT NOT NULL DEFAULT 'local'
                           CHECK(user_type IN ('local', 'aionpro')),
    external_user_id   TEXT,
    username           TEXT,
    email              TEXT,
    password_hash      TEXT,
    avatar_path        TEXT,
    jwt_secret         TEXT,
    status             TEXT NOT NULL DEFAULT 'active'
                           CHECK(status IN ('active', 'disabled')),
    session_generation INTEGER NOT NULL DEFAULT 0,
    created_at         INTEGER NOT NULL,
    updated_at         INTEGER NOT NULL,
    last_login         INTEGER, adopted_by TEXT, adopted_at INTEGER,
    CHECK (
        (user_type = 'local' AND password_hash IS NOT NULL)
        OR
        (user_type = 'aionpro')
    ),
    CHECK (
        (external_user_id IS NULL)
        OR
        (length(external_user_id) > 0)
    )
);
CREATE INDEX idx_providers_platform ON providers(platform);
CREATE INDEX idx_conversation_artifacts_conversation_id ON conversation_artifacts(conversation_id);
CREATE INDEX idx_conversation_artifacts_created_at ON conversation_artifacts(created_at);
CREATE INDEX idx_conversation_artifacts_conversation_created ON conversation_artifacts(conversation_id, created_at);
CREATE INDEX idx_conversation_artifacts_cron_job ON conversation_artifacts(cron_job_id);
CREATE INDEX idx_conversation_artifacts_kind_status ON conversation_artifacts(kind, status);
CREATE INDEX idx_messages_conversation_id ON messages(conversation_id);
CREATE INDEX idx_messages_created_at ON messages(created_at);
CREATE INDEX idx_messages_type ON messages(type);
CREATE INDEX idx_messages_msg_id ON messages(msg_id);
CREATE INDEX idx_messages_conv_created ON messages(conversation_id, created_at);
CREATE INDEX idx_messages_conv_created_desc ON messages(conversation_id, created_at DESC);
CREATE INDEX idx_messages_type_created ON messages(type, created_at DESC);
CREATE INDEX idx_assistant_sessions_user_id ON assistant_sessions(user_id);
CREATE INDEX idx_assistant_sessions_user_chat ON assistant_sessions(user_id, chat_id);
CREATE INDEX idx_conversations_user_id ON conversations(user_id);
CREATE INDEX idx_conversations_updated_at ON conversations(updated_at);
CREATE INDEX idx_conversations_type ON conversations(type);
CREATE INDEX idx_conversations_user_updated ON conversations(user_id, updated_at DESC);
CREATE INDEX idx_conversations_source ON conversations(source);
CREATE INDEX idx_conversations_source_updated ON conversations(source, updated_at DESC);
CREATE INDEX idx_conversations_source_chat ON conversations(source, channel_chat_id, updated_at DESC);
CREATE INDEX idx_conversations_cron_job_id ON conversations(json_extract(extra, '$.cronJobId'));
CREATE INDEX idx_teams_user_id ON teams(user_id);
CREATE INDEX idx_teams_updated_at ON teams(updated_at);
CREATE INDEX idx_mailbox_team_to_read ON mailbox(team_id, to_agent_id, read);
CREATE INDEX idx_mailbox_team_id ON mailbox(team_id);
CREATE INDEX idx_team_tasks_team_id ON team_tasks(team_id);
CREATE INDEX idx_remote_agents_status ON remote_agents(status);
CREATE INDEX idx_conversation_assistant_snapshots_assistant_definition_id
    ON conversation_assistant_snapshots(assistant_definition_id);
CREATE INDEX idx_conversation_assistant_snapshots_agent_id
    ON conversation_assistant_snapshots(agent_id);
CREATE INDEX idx_acp_session_status ON acp_session(session_status);
CREATE INDEX idx_acp_session_suspended ON acp_session(session_status, suspended_at) WHERE session_status = 'suspended';
CREATE INDEX idx_acp_session_agent_id ON acp_session(agent_id);
CREATE INDEX idx_assistants_updated_at ON assistants(updated_at DESC);
CREATE INDEX idx_cron_jobs_conversation ON cron_jobs(conversation_id);
CREATE INDEX idx_cron_jobs_next_run ON cron_jobs(next_run_at) WHERE enabled = 1;
CREATE INDEX idx_skill_import_records_operation_id ON skill_import_records(operation_id);
CREATE INDEX idx_skill_import_records_created_at ON skill_import_records(created_at DESC);
