INSERT INTO "agent_metadata" VALUES('a9f3c21e','a9f3c21e',NULL,'/api/assets/logos/ai-major/antigravity.svg','Antigravity',NULL,'Google Antigravity via the agy CLI',NULL,'antigravity','antigravity','builtin','{"binary_name":"agy"}',1,'agy','[]','[]','[".agents/skills"]','{"supports_side_question":false}','yolo',NULL,NULL,NULL,'{"available_modes":[{"id":"default","name":"Default"},{"id":"accept-edits","name":"Accept Edits"},{"id":"plan","name":"Plan"},{"id":"yolo","name":"Full Auto"}],"current_mode_id":"default"}',NULL,NULL,3140,'online','manual','version_drift_newer','agy 1.2.9 / verified 1.1.10','agy 1.2.9 is newer than the 1.1.10 this integration was verified against. It should still work; report anything that behaves oddly.',392,1790224716774,1790224716774,NULL,NULL,NULL,1790212080258,1790224717167);
INSERT INTO "agent_metadata" VALUES('2d23ff1c','2d23ff1c',NULL,'/api/assets/logos/ai-major/claude.svg','Claude Code',NULL,'Anthropic Claude Code via the claude CLI',NULL,'claude','acp','builtin','{"binary_name":"claude"}',1,'claude','[]','[]','[".claude/skills"]','{"supports_side_question":true,"self_identity_sticky":true,"session_load_via_meta_field":true,"supports_team":true}','bypassPermissions',NULL,NULL,'[{"id":"mode","category":"mode","type":"select","currentValue":"default","options":[{"value":"default","name":"Default","description":"Standard behavior, prompts for dangerous operations"},{"value":"acceptEdits","name":"Accept Edits","description":"Auto-accept file edit operations"},{"value":"plan","name":"Plan Mode","description":"Planning mode, no actual tool execution"},{"value":"dontAsk","name":"Don''t Ask","description":"Don''t prompt for permissions, deny if not pre-approved"},{"value":"bypassPermissions","name":"Bypass Permissions","description":"Bypass all permission checks"}]},{"id":"model","category":"model","type":"select","currentValue":null,"options":[{"value":"default","name":"Default (recommended)","description":"Opus 5.5 · Best for everyday, complex tasks"},{"value":"opus","name":"Opus","description":"Opus 5.5 · Best for everyday, complex tasks · ~2× usage vs Sonnet"},{"value":"claude-fable-5-1[1m]","name":"Fable","description":"Fable 5.1 · Most capable for your hardest and longest-running tasks · Requires usage credits"},{"value":"sonnet","name":"Sonnet","description":"Sonnet 5 · Efficient for routine tasks"},{"value":"haiku","name":"Haiku","description":"Haiku 4.5 · Fastest for quick answers"}]},{"id":"reasoning_effort","category":"thought_level","type":"select","currentValue":null,"options":[{"value":"low","name":"low"},{"value":"medium","name":"medium"},{"value":"high","name":"high"},{"value":"xhigh","name":"xhigh"},{"value":"max","name":"max"},{"value":"ultracode","name":"ultracode"}]}]','{"available_modes":[{"id":"default","name":"Default","description":"Standard behavior, prompts for dangerous operations"},{"id":"acceptEdits","name":"Accept Edits","description":"Auto-accept file edit operations"},{"id":"plan","name":"Plan Mode","description":"Planning mode, no actual tool execution"},{"id":"dontAsk","name":"Don''t Ask","description":"Don''t prompt for permissions, deny if not pre-approved"},{"id":"bypassPermissions","name":"Bypass Permissions","description":"Bypass all permission checks"}],"current_mode_id":"default"}','{"available_models":[{"id":"default","label":"Default (recommended)","reasoning_efforts":["low","medium","high","xhigh","max","ultracode"]},{"id":"opus","label":"Opus","reasoning_efforts":["low","medium","high","xhigh","max","ultracode"]},{"id":"claude-fable-5-1[1m]","label":"Fable","reasoning_efforts":["low","medium","high","xhigh","max","ultracode"]},{"id":"sonnet","label":"Sonnet","reasoning_efforts":["low","medium","high","xhigh","max","ultracode"]},{"id":"haiku","label":"Haiku"}],"current_model_id":null}','[{"name":"aionui-config","description":"Configure AionUi itself through the bundled aioncore config CLI: create and edit assistants, update assistant rules, inspect and import skills, manage MCP servers, configure model providers, update settings, manage agents, configure scheduled tasks, and manage app configuration from an agent conversation. Use when the user wants you to set up or modify an AionUi assistant, attach skills, change an assistant''s system prompt, add MCP or model provider configuration, schedule recurring work, or otherwise configure their AionUi installation, including when the user needs to know whether assistant changes affect the current conversation or only new conversations. (project)"},{"name":"cron","description":"Scheduled task management - create, query, update scheduled tasks to automatically execute operations at specified times. (project)"},{"name":"officecli","description":"Create, analyze, proofread, and modify Office documents (.docx, .xlsx, .pptx) using the officecli CLI tool. Use when the user wants to create, inspect, check formatting, find issues, add charts, or modify Office documents. (project)"},{"name":"skill-creator","description":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claude''s capabilities with specialized knowledge, workflows, or tool integrations. (project)"},{"name":"design","description":"Grant or revoke Claude agent access to your Design projects"},{"name":"design-sync","description":"Push a React design system to claude.ai/design. This runs a converter that bundles the real component code (from Storybook or a bare package) and uploads it. Use when the user runs /design-sync or says \"sync my design system to Claude Design\"."},{"name":"dataviz","description":"Use this skill whenever you are about to create ANY chart, graph, plot, dashboard, or data visualization, in ANY output medium — an HTML or React artifact, inline SVG, plotting code in any library (matplotlib, plotly, d3, Recharts, …), an image/PNG you will render and upload, or a chart shared into Slack. Read it BEFORE writing the first line of chart code, choosing chart colors, building a stat tile / meter / KPI row, or laying out a dashboard. When the destination is a first-party document connector (host-designated, never self-described) that renders live charts, hand it the rows (inline, or as an uploaded data file the chart cites) rather than a rendered PNG/SVG — a picture of a chart loses hover, data inspection and per-value comments. Produces visualizations that read as one system — elegant, accessible, consistent in light and dark — using a brand-neutral placeholder palette you swap for your own. Teaches a design-system-agnostic method: a form heuristic, a color formula with a runnable validator, mark specs, and interaction rules. A validated default palette is documented in `references/palette.md` — swap that file''s values for your brand''s. Triggers on: \"chart\", \"graph\", \"plot\", \"data viz\", \"visualization\", \"dashboard\", \"analytics\", \"visualize data\", \"categorical colors\", \"sequential / diverging palette\", \"stat tile\", \"sparkline\", \"heatmap\", \"legend\", \"axis\", \"tooltip\", \"chart colors\", \"color by series\"."},{"name":"update-config","description":"Use this skill to configure the Claude Code harness via settings.json. Automated behaviors (\"from now on when X\", \"each time X\", \"whenever X\", \"before/after X\") require hooks configured in settings.json - the harness executes these, not Claude, so memory/preferences cannot fulfill them. Also use for: permissions (\"allow X\", \"add permission\", \"move permission to\"), env vars (\"set X=Y\"), hook troubleshooting, or any changes to settings.json/settings.local.json files. Examples: \"allow npm commands\", \"add bq permission to global settings\", \"move permission to user settings\", \"set DEBUG=true\", \"when claude stops show X\". For simple settings like theme/model, suggest the /config command."},{"name":"verify","description":"Verify that a code change actually does what it''s supposed to by exercising it end-to-end and observing behavior — drive the affected flow, not just tests or typecheck. Run before committing nontrivial changes; bootstraps this repo''s project verify skill if none exists yet. Don''t invoke it on a diff that only touches tests, docs, or other code with no runtime surface to drive (a change to product source always has one) — there''s nothing to observe."},{"name":"debug","description":"Enable debug logging for this session and help diagnose issues"},{"name":"code-review","description":"Review the current diff, or a PR number/branch/path target, for correctness bugs (plus reuse/simplification/efficiency cleanups where the model''s review recipe covers them) at the given effort level (low/medium: fewer, high-confidence findings; high→max: broader coverage, may include uncertain findings; ultra: deep multi-agent review in the cloud); with no level given, it reuses the level you typed last. Pass --comment to post findings as inline PR comments, or --fix to apply the findings to the working tree after the review. For ultra on a GitHub.com PR target, --post asks to post the finished review’s findings to the PR as a single comment from the user’s GitHub account (not a review; the launch dialog still confirms in interactive sessions, while non-interactive mode posts on the flag alone) and --no-post hides that option."},{"name":"simplify","description":"Review the changed code for reuse, simplification, efficiency, and altitude cleanups, then apply the fixes. Quality only — it does not hunt for bugs; use /code-review for that."},{"name":"batch","description":"Research and plan a large-scale change, then execute it in parallel across 5–30 isolated worktree agents that each open a PR."},{"name":"fewer-permission-prompts","description":"Scan your transcripts for common read-only Bash and MCP tool calls, then add a prioritized allowlist to project .claude/settings.json to reduce permission prompts."},{"name":"doctor","description":"Health-check the user''s Claude Code setup and fix issues: diagnose installation health — what the `claude doctor` terminal diagnostics cover — from local data (duplicate or leftover installs, PATH, unparseable settings files, broken or colliding agent definitions, skills whose frontmatter fails to parse); find unused skills, MCP servers, and plugins versus their context cost and disable dead weight; deduplicate local CLAUDE.md files against checked-in ones; trim checked-in CLAUDE.md files by cutting content a session could derive from the codebase (directory layouts, tech-stack lists, architecture overviews) while keeping gotchas, rationale, and non-standard conventions; migrate always-loaded CLAUDE.md guidance into lazy skills and nested CLAUDE.md files; flag slow hooks and context-heavy extensions; check the installed version is current; make auto mode the default permission mode; and pre-approve frequently denied read-only commands. Use when the user asks for a doctor run, checkup, audit, tune-up, or cleanup of their Claude Code setup or configuration."},{"name":"loop","description":"Run a prompt or slash command on a recurring interval (e.g. /loop 5m /foo). Omit the interval to let the model self-pace."},{"name":"schedule","description":"Create, update, list, or run scheduled cloud agents (routines) that execute on a cron schedule."},{"name":"claude-api","description":"Reference for the Claude API / Anthropic SDK — model ids, pricing, params, streaming, tool use, MCP, agents, caching, token counting, model migration.\nTRIGGER — read BEFORE opening the target file; don''t skip because it \"looks like a one-liner\" — whenever: the prompt names Claude/Anthropic in any form (Claude, Anthropic, Fable, Opus, Sonnet, Haiku, `anthropic`, `@anthropic-ai`, `claude-*`, `us.anthropic.*`, `[1m]`); the user asks about an LLM (pricing/model choice/limits/caching) — never answer from memory; OR the task is LLM-shaped with provider unstated (agent/MCP/tool-definition/multi-agent/RAG/LLM-judge/computer-use; generate/summarize/extract/classify/rewrite/converse over NL; debugging refusals/cutoffs/streaming/tool-calls/tokens).\nSKIP only when another provider is being worked on (overrides all triggers): OpenAI/GPT/Gemini/Llama/Mistral/Cohere/Ollama named in the query; OR `grep -rE ''openai|langchain_openai|google.generativeai|genai|mistralai|cohere|ollama''` over the project hits (run this grep FIRST if no provider named — don''t Read the file)."},{"name":"run","description":"Launch and drive this project''s app to see a change working. Use when asked to run, start, or screenshot the app, or to confirm a change works in the real app (not just tests). First looks for a project skill that already covers launching the app; otherwise falls back to built-in patterns per project type (CLI, server, TUI, Electron, browser-driven, library)."},{"name":"run-skill-generator","description":"Author or improve the run-<unit> skill - a per-project skill that tells agents how to build, launch, and drive this project''s app. Use when the user asks to set up the project, get it running, write run instructions, or verify build/run steps work from a clean environment."},{"name":"advisor","description":"Let Claude consult a stronger model at key moments"},{"name":"agents","description":"(removed) Ask Claude to create/manage subagents, or edit .claude/agents/"},{"name":"auto-mode-setup","description":"Teach auto mode about your environment, plus optional rule tweaks"},{"name":"autocompact","description":"Configure the auto-compact window size"},{"name":"clear","description":"Start a new session with empty context; previous session stays on disk (resumable with /resume)"},{"name":"color","description":"Set the prompt bar color for this session"},{"name":"compact","description":"Free up context by summarizing the conversation so far"},{"name":"config","description":"Set a setting by key"},{"name":"output-style","description":"List output styles or switch to one"},{"name":"context","description":"Show current context usage"},{"name":"effort","description":"Set effort level for model usage"},{"name":"fast","description":"Toggle fast mode (Opus 5.5)"},{"name":"heapdump","description":"Dump the JS heap to the Desktop; on Linux with no Desktop folder, the home directory"},{"name":"init","description":"Initialize a new CLAUDE.md file with codebase documentation"},{"name":"mcp","description":"Manage MCP servers"},{"name":"import","description":"Import config from another AI coding agent"},{"name":"model","description":"Set the AI model for Claude Code"},{"name":"__remote-workflow","description":"Run the workflow script delivered in this session environment (server-launched sessions only)"},{"name":"workflow-launch-exec","description":"Execute a server-launched workflow handoff (workflow_launch event sessions only)"},{"name":"reload-plugins","description":"Activate pending plugin changes in the current session"},{"name":"reload-skills","description":"Pick up skills added or changed on disk during this session"},{"name":"rename","description":"Rename the current conversation"},{"name":"ultrareview","description":"Start a cloud agent that finds and verifies bugs in your branch (~5-10 min, $5-$25 USD) · Runs in a cloud session. See https://code.claude.com/docs/en/claude-code-on-the-web"},{"name":"security-review","description":"Complete a security review of the pending changes on the current branch"},{"name":"usage-credits","description":"Configure usage credits or request them from your admin when you hit a limit"},{"name":"extra-usage","description":"Renamed to /usage-credits"},{"name":"usage","description":"Show session cost, plan usage, and what''s contributing to your limits"},{"name":"insights","description":"Generate a report analyzing your Claude Code sessions"},{"name":"recap","description":"Generate a one-line session recap now"},{"name":"skill-doctor","description":"Show which loaded skills are unused and costing context"},{"name":"goal","description":"Set a goal — keep working until the condition is met"},{"name":"design-consent","description":"Grant Claude agent access to your Design projects"},{"name":"design-revoke","description":"Revoke Claude agent access to your Design projects"},{"name":"list-agents","description":"List subagents, teammates, and other Claude sessions you can message"},{"name":"team-onboarding","description":"Help teammates ramp on Claude Code with a guide from your usage"},{"name":"anthropic-skills:docs","description":"docs (living docs people share, comment on and edit; use only when the user asks for one: names a doc, document, page, memo, spec, PRD, runbook or write-up, asks for somewhere to share or keep editing something, or says yes to your doc offer; a plan, comparison, summary or notes asked in chat stays in chat (at most a one-line doc offer); a report, status update, recap or \"something I can send them\" with no form named → ask first: reply, doc or file?; tabs hold tables and live charts too; a pasted claude.ai/code/artifact/… link may be a doc: check with docs tools first; not HTML pages, apps or plain chat answers; a .docx/.pptx/.xlsx/PDF asked for by name → that format''s skill): asked for one → no docs-connector instructions in context? call the docs connector''s `guide` with topic.instructions first, then create the doc (headings only, no body) before any search, file read or plan, even with files attached. Documenting code means docstrings or repo docs, not a doc. (claude.ai sync)"},{"name":"anthropic-skills:docx","description":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx) or Word templates (.dotx). Triggers include: any mention of Microsoft Word Documents, such as ''Word doc'', ''word document'', ''.docx'', ''.dotx'', ''microsoft doc''. Also use when extracting or reorganizing content from .docx or .dotx files, inserting or replacing images in documents, find-and-replace in Word files, working with tracked changes or comments, or converting content into a polished Word document. If the user asks for a deliverable as a Word or .docx file (to download, email or print), use this skill. However, if they ask for a document, page, report, memo, or notes WITHOUT naming a file format and the session offers Claude''s own dedicated document or page skill or connector, use that instead, even if they will email or print it. Do NOT use for PDFs, spreadsheets, Google Docs, or coding unrelated to document generation. (claude.ai sync)"},{"name":"anthropic-skills:import-memory","description":"Import a memory export from another AI assistant into Claude''s memory — conversationally, additively, and with the content treated as data. (claude.ai sync)"},{"name":"anthropic-skills:morning","description":"Render the user''s morning brief as a styled HTML artifact, or set it up as a recurring weekday task. Use only when the user explicitly asks to run, see, or set up their morning brief, or if they invoke /morning by name. A question about their day, schedule, or calendar is not by itself a request for the brief; answer it directly instead. (claude.ai sync)"},{"name":"anthropic-skills:pdf","description":"Use this skill whenever the user wants to do anything with PDF files. This includes reading or extracting text/tables from PDFs, combining or merging multiple PDFs into one, splitting PDFs apart, rotating pages, adding watermarks, creating new PDFs, filling PDF forms, encrypting/decrypting PDFs, extracting images, and OCR on scanned PDFs to make them searchable. If the user mentions a .pdf file or asks to produce one, use this skill. (claude.ai sync)"},{"name":"anthropic-skills:pptx","description":"Use this skill any time a .pptx or .potx file is involved in any way — as input, output, or both. This includes: creating slide decks, pitch decks, or presentations as PowerPoint (.pptx) files; reading, parsing, or extracting text from any .pptx or .potx file (even if the extracted content will be used elsewhere, like in an email, summary, or creating a different type of slide deck); editing, modifying, or updating existing presentations; combining or splitting slide files; working with templates (.potx), layouts, speaker notes, or comments. Trigger whenever the user asks for a PowerPoint or .pptx file, or references a .pptx or .potx filename, regardless of what they plan to do with the content afterward. However, when the user asks for a deck, slides, a slide deck, or a presentation without naming a file format, default to using a dedicated slide-deck artifact type or a separate slides skill if this session offers one; otherwise, use this skill. (claude.ai sync)"},{"name":"anthropic-skills:skill-creator","description":"Create new skills, modify and improve existing skills, and measure skill performance. Use when users want to create a skill from scratch, edit, or optimize an existing skill, run evals to test a skill, benchmark skill performance with variance analysis, or optimize a skill''s description for better triggering accuracy. (claude.ai sync)"},{"name":"anthropic-skills:xlsx","description":"Use this skill any time a spreadsheet file is the primary input or output. This means any task where the user wants to: open, read, edit, or fix an existing .xlsx, .xlsm, .xltx, .csv, or .tsv file (e.g., adding columns, computing formulas, formatting, charting, cleaning messy data); create a new spreadsheet from scratch or from other data sources; or convert between tabular file formats. Trigger especially when the user references a spreadsheet file by name or path — even casually (like \"the xlsx in my downloads\") — and wants something done to it or produced from it. Also trigger for cleaning or restructuring messy tabular data files (malformed rows, misplaced headers, junk data) into proper spreadsheets. The deliverable must be a spreadsheet file. Do NOT trigger when the primary deliverable is a Word document, HTML report, standalone Python script, database pipeline, or Google Sheets API integration, even if tabular data is involved. (claude.ai sync)"}]',3100,'online','manual',NULL,'claude 2.1.280',NULL,0,1790248649256,1790248649256,NULL,NULL,NULL,1790247723999,1790248686197);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a17-7142-9c97-55afb8f63dc3',NULL,'dashboard-creator','builtin','system','dashboard-creator','Dashboard Creator','{"zh-CN":"数据仪表盘","ru-RU":"Создатель дашбордов","uk-UA":"Створювач дашбордів","en-US":"Dashboard Creator"}','Turn CSV or tabular data into polished Excel dashboards with KPI cards, charts linked to live data, sparklines, and conditional formatting. Automatically scales complexity to dataset size — from quick summaries to full analytics panels.','{"en-US":"Turn CSV or tabular data into polished Excel dashboards with KPI cards, charts linked to live data, sparklines, and conditional formatting. Automatically scales complexity to dataset size — from quick summaries to full analytics panels.","uk-UA":"Перетворюйте CSV або табличні дані на професійні дашборди Excel: KPI-картки, графіки з прив''язкою до даних, спарклайни та умовне форматування. Автоматично масштабує складність під обсяг даних.","zh-CN":"将 CSV 或表格数据转化为精美的 Excel 仪表盘，包含 KPI 卡片、关联实时数据的图表、迷你图和条件格式。根据数据量自动缩放复杂度——从简洁汇总到完整分析面板。","ru-RU":"Преобразует CSV и табличные данные в аккуратные Excel-дашборды: KPI-карточки, графики с привязкой к данным, спарклайны и условное форматирование. Масштабирует сложность под объём данных - от краткой сводки до полноценной аналитической панели."}','builtin_asset','avatars/dashboard-creator.jpg','632f31d2','builtin_asset','dashboard-creator','["Create a SaaS MRR dashboard with 12 months of sample data — show MRR trend, month-over-month growth, and churn breakdown for a board meeting","Build an e-commerce regional sales dashboard with sample data across 5 regions: revenue by region, weekly trends, and category split","Make a budget-vs-actuals dashboard for 8 departments showing variance indicators and over/under-budget status"]','{"ru-RU":["Создай дашборд MRR для SaaS с примерными данными за 12 месяцев — покажи тренд MRR, помесячный рост и разбивку оттока для совета директоров","Собери дашборд региональных продаж электронной коммерции с данными по 5 регионам: выручка по регионам, недельные тренды и разбивка по категориям","Сделай дашборд «план/факт» для 8 отделов с индикаторами отклонений и статусом превышения/недоиспользования бюджета"],"en-US":["Create a SaaS MRR dashboard with 12 months of sample data — show MRR trend, month-over-month growth, and churn breakdown for a board meeting","Build an e-commerce regional sales dashboard with sample data across 5 regions: revenue by region, weekly trends, and category split","Make a budget-vs-actuals dashboard for 8 departments showing variance indicators and over/under-budget status"],"zh-CN":["做一个 SaaS MRR 仪表盘，用 12 个月的示例数据，展示 MRR 趋势、环比增长和流失分析，适合董事会汇报","做一个电商区域销售仪表盘，生成 5 个区域的示例数据，展示按区域收入、周趋势和品类占比","做一个 8 个部门的预算 vs 实际仪表盘，展示偏差指标和超支/节余状态"],"uk-UA":["Створити дашборд SaaS MRR на основі даних за 12 місяців — показати тренд MRR, щомісячне зростання та аналіз відтоку","Побудувати регіональний дашборд продажів для e-commerce з даними по 5 регіонах: дохід за регіоном, тижневі тренди","Зробити дашборд \"бюджет проти факту\" для 8 відділів з індикаторами розбіжностей"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-data-dashboard"]','[]','[]','auto','[]',1790212086298,1790248654945,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a21-70b1-83fd-68d194b3e414',NULL,'social-job-publisher','builtin','system','social-job-publisher','Social Job Publisher','{"uk-UA":"Публікатор вакансій","en-US":"Social Job Publisher","zh-CN":"社交招聘发布助手","ru-RU":"Публикатор вакансий в соцсетях"}','Expand hiring requests into a full JD, images, and publish to social platforms via connectors.','{"ru-RU":"Разворачивает запрос на найм в полноценное описание вакансии и изображения, а затем публикует это в соцсетях через коннекторы.","en-US":"Expand hiring requests into a full JD, images, and publish to social platforms via connectors.","uk-UA":"Розгортає запит на найм у повноцінний опис вакансії та зображення, а потім публікує це в соцмережах через конектори.","zh-CN":"扩写招聘需求为完整 JD 与图片，并通过 connector 发布到社交平台。"}','builtin_asset','avatars/social-job-publisher.jpg','632f31d2','builtin_asset','social-job-publisher','["Create a comprehensive job post for Senior Full-Stack Engineer","Draft an engaging hiring tweet for social media","Create a multi-platform job posting (LinkedIn, X, Redbook)"]','{"en-US":["Create a comprehensive job post for Senior Full-Stack Engineer","Draft an engaging hiring tweet for social media","Create a multi-platform job posting (LinkedIn, X, Redbook)"],"zh-CN":["创建一份高级全栈工程师的完整招聘启事","起草一条适合社交媒体的招聘推文","创建多平台职位发布（LinkedIn、X、小红书）"],"uk-UA":["Створити повний опис вакансії Senior Full-Stack інженера","Написати цікавий пост про найм для соцмереж","Створити пост про вакансію для кількох платформ (LinkedIn, X)"],"ru-RU":["Создай развёрнутую вакансию на позицию Senior Full-Stack Engineer","Составь привлекательный твит о найме для соцсетей","Создай публикацию вакансии для нескольких платформ (LinkedIn, X, Xiaohongshu)"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["xiaohongshu-recruiter","x-recruiter"]','[]','[]','auto','[]',1790212086305,1790248654969,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a25-7c50-bed4-6b25655267ae',NULL,'aionui-assistant','builtin','system','aionui-assistant','AionUi Butler','{"zh-CN":"AionUi管家","en-US":"AionUi Butler","ru-RU":"Дворецкий AionUi","uk-UA":"Дворецький AionUi"}','Your all-in-one AionUi butler: set up assistants, skills, MCP servers and LLM providers; set up remote access so you can reach AionUi from your phone or share a link; and diagnose problems like stuck conversations, failing models, or a scheduled task that didn''t run.','{"uk-UA":"Ваш універсальний дворецький AionUi: налаштування асистентів, навичок, серверів MCP і провайдерів LLM; налаштування віддаленого доступу, щоб відкривати AionUi з телефона або ділитися посиланням; і діагностика проблем — зависань розмов, збоїв моделей або чому не виконалося заплановане завдання.","en-US":"Your all-in-one AionUi butler: set up assistants, skills, MCP servers and LLM providers; set up remote access so you can reach AionUi from your phone or share a link; and diagnose problems like stuck conversations, failing models, or a scheduled task that didn''t run.","zh-CN":"你的 AionUi 全能管家：配置助手、技能、MCP 服务器与 LLM 模型；设置远程访问，让你在手机或外网也能打开 AionUi、生成分享链接；还能诊断卡住的会话、失败的模型调用，或定时任务为何没执行。","ru-RU":"Ваш универсальный дворецкий AionUi: настройка ассистентов, навыков, серверов MCP и провайдеров LLM; настройка удалённого доступа, чтобы открывать AionUi с телефона или делиться ссылкой; и диагностика проблем — зависших разговоров, сбоев моделей или почему не выполнилась запланированная задача."}','builtin_asset','avatars/aionui-assistant.jpg','632f31d2','builtin_asset','aionui-assistant','["Add a new LLM provider and API key, then set it as the default model","Set up remote access for me, so I can open AionUi from my phone when I''m out","A conversation is stuck — please diagnose what''s wrong","Create a new assistant and attach a skill to it"]','{"zh-CN":["添加一个新的 LLM 模型和 API Key，并设为默认模型","帮我配置远程访问，让我在外面用手机也能打开 AionUi","有个会话卡住了，帮我诊断哪里出了问题","创建一个新助手，并给它绑定一个技能"],"en-US":["Add a new LLM provider and API key, then set it as the default model","Set up remote access for me, so I can open AionUi from my phone when I''m out","A conversation is stuck — please diagnose what''s wrong","Create a new assistant and attach a skill to it"],"uk-UA":["Додай нового провайдера LLM та API-ключ, потім зроби його моделлю за замовчуванням","Налаштуй віддалений доступ, щоб я міг відкривати AionUi з телефона, коли мене немає","Розмова зависла — будь ласка, діагностуй, що не так","Створи нового асистента й підключи до нього навичку"],"ru-RU":["Добавь нового провайдера LLM и API-ключ, затем сделай его моделью по умолчанию","Настрой удалённый доступ, чтобы я мог открывать AionUi с телефона, когда меня нет","Разговор завис — пожалуйста, диагностируй, что не так","Создай нового ассистента и подключи к нему навык"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["aionui-config","aionui-troubleshooting","aionui-webui-public"]','[]','[]','auto','[]',1790212086309,1790248654949,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a29-7741-82a9-0a1b2df3444a',NULL,'ui-ux-pro-max','builtin','system','ui-ux-pro-max','UI/UX Pro Max','{"zh-CN":"UI/UX 专业设计师","en-US":"UI/UX Pro Max","ru-RU":"UI/UX Pro Max","uk-UA":"UI/UX Pro Max"}','Professional UI/UX design intelligence with 57 styles, 95 color palettes, 56 font pairings, and stack-specific best practices.','{"ru-RU":"Профессиональный UI/UX-помощник с 57 стилями, 95 цветовыми палитрами, 56 сочетаниями шрифтов и лучшими практиками для разных стеков.","zh-CN":"专业 UI/UX 设计智能助手，包含 57 种风格、95 个配色方案、56 个字体配对及技术栈最佳实践。","uk-UA":"Професійний UI/UX-помічник з 57 стилями, 95 кольоровими палітрами, 56 поєднаннями шрифтів та найкращими практиками для різних технологій.","en-US":"Professional UI/UX design intelligence with 57 styles, 95 color palettes, 56 font pairings, and stack-specific best practices."}','builtin_asset','avatars/ui-ux-pro-max.jpg','632f31d2','builtin_asset','ui-ux-pro-max','["Design a modern login page for a fintech mobile app","Create a color palette for a nature-themed website","Design a dashboard interface for a SaaS product"]','{"en-US":["Design a modern login page for a fintech mobile app","Create a color palette for a nature-themed website","Design a dashboard interface for a SaaS product"],"ru-RU":["Разработай современную страницу входа для мобильного финтех-приложения","Создай цветовую палитру для сайта в природной тематике","Спроектируй интерфейс дашборда для SaaS-продукта"],"zh-CN":["为金融科技移动应用设计现代登录页","创建自然主题网站的配色方案","为 SaaS 产品设计仪表板界面"],"uk-UA":["Спроектувати сучасну сторінку входу для мобільного фінтех-додатку","Створити кольорову палітру для сайту на природну тематику","Розробити інтерфейс дашборду для SaaS-продукту"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','[]','[]','[]','auto','[]',1790212086314,1790248654992,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a2d-7a50-969d-c22c8b26d561',NULL,'academic-paper','builtin','system','academic-paper','Academic Paper','{"ru-RU":"Помощник по академическим работам","uk-UA":"Академічний помічник","en-US":"Academic Paper","zh-CN":"学术论文助手"}','Create formally structured academic papers, research papers, and white papers with native Word TOC, LaTeX-to-OMML equations, scholarly bibliography (APA/Physics/Chicago), footnotes, multi-column layouts, and paper-type-specific styling.','{"en-US":"Create formally structured academic papers, research papers, and white papers with native Word TOC, LaTeX-to-OMML equations, scholarly bibliography (APA/Physics/Chicago), footnotes, multi-column layouts, and paper-type-specific styling.","zh-CN":"创建正式结构的学术论文、研究论文和白皮书，支持原生 Word 目录、LaTeX 转 OMML 公式、学术参考文献（APA/物理/芝加哥格式）、脚注、多栏排版和论文类型专属样式。","uk-UA":"Створюйте структуровані академічні статті, наукові роботи та White Papers: зміст Word, формули LaTeX в OMML, бібліографія (APA/Physics/Chicago), виноски та багатоколонкова верстка.","ru-RU":"Создаёт академические статьи, научные работы и white paper со строгой структурой: нативное оглавление Word, формулы LaTeX в OMML, библиография в форматах APA/Physics/Chicago, сноски, многоколоночная вёрстка и стили под тип работы."}','builtin_asset','avatars/academic-paper.jpg','632f31d2','builtin_asset','academic-paper','["Create a white paper on rural EV charging infrastructure with executive summary, data tables, footnotes, CONFIDENTIAL watermark, and professional headers","Write a physics paper on topological insulators with display equations, multi-column abstract, theorem/definition blocks, and landscape figures","Create an APA-style research paper on organizational culture with 3 data tables, endnotes, 15 references with hanging indent, and double spacing"]','{"ru-RU":["Создай white paper о зарядной инфраструктуре для электромобилей в сельской местности с резюме, таблицами данных, сносками, водяным знаком CONFIDENTIAL и профессиональными колонтитулами","Напиши статью по физике о топологических изоляторах с выключенными формулами, многоколоночным аннотацией, блоками теорем/определений и альбомными иллюстрациями","Создай исследовательскую работу об организационной культуре в формате APA с 3 таблицами данных, концевыми сносками, 15 источниками с выступающим отступом и двойным интервалом"],"en-US":["Create a white paper on rural EV charging infrastructure with executive summary, data tables, footnotes, CONFIDENTIAL watermark, and professional headers","Write a physics paper on topological insulators with display equations, multi-column abstract, theorem/definition blocks, and landscape figures","Create an APA-style research paper on organizational culture with 3 data tables, endnotes, 15 references with hanging indent, and double spacing"],"zh-CN":["创建一份农村电动汽车充电基础设施白皮书，包含执行摘要、数据表格、脚注、CONFIDENTIAL 水印和专业页头","写一篇拓扑绝缘体物理论文，包含展示式公式、多栏摘要、定理/定义模块和横向图表","创建一份 APA 格式的组织文化研究论文，包含 3 个数据表格、尾注、15 条挂缩进参考文献和双倍行距"],"uk-UA":["Створити White Paper про інфраструктуру зарядки електромобілів у сільській місцевості з таблицями даних та виносками","Написати статтю з фізики про топологічні ізолятори з формулами, анотацією та блоками теорем","Створити наукову роботу в стилі APA про організаційну культуру з 3 таблицями даних та 15 джерелами"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-academic-paper"]','[]','[]','auto','[]',1790212086318,1790248654979,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a32-76d2-b794-0a9f31c735b7',NULL,'planning-with-files','builtin','system','planning-with-files','Planning with Files','{"en-US":"Planning with Files","ru-RU":"Планирование с файлами","zh-CN":"文件规划助手","uk-UA":"Планування з файлами"}','Manus-style file-based planning for complex tasks. Uses task_plan.md, findings.md, and progress.md to maintain persistent context.','{"uk-UA":"Файлове планування в стилі Manus для складних завдань. Використовує task_plan.md, findings.md та progress.md для збереження контексту.","ru-RU":"Файловое планирование в стиле Manus для сложных задач. Использует task_plan.md, findings.md и progress.md для сохранения устойчивого контекста.","en-US":"Manus-style file-based planning for complex tasks. Uses task_plan.md, findings.md, and progress.md to maintain persistent context.","zh-CN":"Manus 风格的文件规划，用于复杂任务。使用 task_plan.md、findings.md 和 progress.md 维护持久化上下文。"}','builtin_asset','avatars/planning-with-files.jpg','632f31d2','builtin_asset','planning-with-files','["Plan a comprehensive refactoring task with milestones","Break down the feature implementation into actionable steps","Create a project plan for migrating to a new framework"]','{"uk-UA":["Спланувати повний рефакториринг з контрольними точками","Розбити реалізацію функції на конкретні кроки","Створити план міграції на новий фреймворк"],"en-US":["Plan a comprehensive refactoring task with milestones","Break down the feature implementation into actionable steps","Create a project plan for migrating to a new framework"],"ru-RU":["Спланируй комплексную задачу рефакторинга с вехами","Разбей реализацию функции на конкретные шаги","Создай план проекта по миграции на новый фреймворк"],"zh-CN":["规划一个包含里程碑的全面重构任务","将功能实现拆分为可执行的步骤","创建迁移到新框架的项目计划"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','[]','[]','[]','auto','[]',1790212086322,1790248654959,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a36-7a10-a1b4-3a61f9ce288f',NULL,'story-roleplay','builtin','system','story-roleplay','Story Roleplay','{"ru-RU":"Ролевые истории","uk-UA":"Рольові історії","en-US":"Story Roleplay","zh-CN":"故事角色扮演"}','Immersive story roleplay. Start by: 1) Natural language to create characters, 2) Paste PNG images, or 3) Open folder with character cards (PNG/JSON) and world info.','{"uk-UA":"Іммерсивний сюжетний рольовий режим. Можна почати трьома способами: описати персонажів словами, вставити PNG-зображення або відкрити папку з картками персонажів та лором світу.","en-US":"Immersive story roleplay. Start by: 1) Natural language to create characters, 2) Paste PNG images, or 3) Open folder with character cards (PNG/JSON) and world info.","ru-RU":"Иммерсивный сюжетный ролевой режим. Можно начать тремя способами: описать персонажей словами, вставить PNG-изображения или открыть папку с карточками персонажей и лором мира.","zh-CN":"沉浸式故事角色扮演。三种开始方式：1) 自然语言直接对话创建角色，2) 直接粘贴PNG图片，3) 打开包含角色卡（PNG/JSON）和世界书的文件夹。"}','builtin_asset','avatars/story-roleplay.jpg','632f31d2','builtin_asset','story-roleplay','["Start an epic fantasy adventure with a brave warrior","Create a detailed character with backstory and personality","Begin an interactive story in a sci-fi setting"]','{"en-US":["Start an epic fantasy adventure with a brave warrior","Create a detailed character with backstory and personality","Begin an interactive story in a sci-fi setting"],"zh-CN":["开始一个勇敢战士的史诗奇幻冒险","创建一个有背景故事和个性的详细角色","在科幻设定中开始一个互动故事"],"uk-UA":["Почати епічну фентезі-пригоду з хоробрим воїном","Створити детального персонажа з історією та характером","Почати інтерактивну історію в науково-фантастичному сетингу"],"ru-RU":["Начни эпическое фэнтези-приключение с отважным воином","Создай детального персонажа с предысторией и характером","Начни интерактивную историю в научно-фантастическом сеттинге"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["story-roleplay"]','[]','[]','auto','[]',1790212086327,1790248654963,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a3a-7593-b34f-76efb8579b21',NULL,'word-form-creator','builtin','system','word-form-creator','Word Form Creator','{"uk-UA":"Створювач форм Word","en-US":"Word Form Creator","zh-CN":"可填表单助手","ru-RU":"Создатель форм Word"}','Build fillable Word forms (.docx) with real content controls, checkbox fields, MERGEFIELD mail-merge placeholders, and document protection — only designated fields are editable, the rest stays locked. HR intakes, surveys, contract / SOW templates, compliance checklists, medical intake.','{"en-US":"Build fillable Word forms (.docx) with real content controls, checkbox fields, MERGEFIELD mail-merge placeholders, and document protection — only designated fields are editable, the rest stays locked. HR intakes, surveys, contract / SOW templates, compliance checklists, medical intake.","zh-CN":"制作可填 Word 表单（.docx），支持真正的内容控件、复选框、邮件合并占位符和文档保护——只有指定字段可编辑，其他部分保持锁定。适用于 HR 入职表、问卷、合同 / SOW 模板、合规 checklist、医疗问诊表。","ru-RU":"Создаёт заполняемые формы Word (.docx) с реальными элементами управления содержимым, флажками, полями MERGEFIELD и защитой документа — редактируются только заданные поля, остальное заблокировано. HR-анкеты, опросы, шаблоны контрактов / SOW, комплаенс-чеклисты, медицинские опросники.","uk-UA":"Створюйте заповнювані форми Word (.docx) зі справжніми елементами керування вмістом, полями-прапорцями, MERGEFIELD для злиття пошти та захистом документа — редагуються лише задані поля, решта залишається заблокованою. HR-анкети, опитування, шаблони контрактів / SOW, комплаєнс-чеклисти, медичні анкети."}','emoji','📋','632f31d2','builtin_asset','word-form-creator','["Build a new-hire onboarding .docx form with fields for full name, start date, department, manager, role-based training checklist, and equipment request checkboxes; only the fields are editable.","Create a SOW contract template .docx with mail-merge placeholders for client name, effective date, scope bullets, total fee, and signature blocks; protect everything except the signature area.","Make a medical intake questionnaire .docx with dropdown for reason of visit, text fields for allergies / current medication, checkbox grid for past conditions, and signature line at the bottom."]','{"ru-RU":["Сделай .docx-форму приёма нового сотрудника с полями ФИО, дата начала, отдел, руководитель, чеклистом обучения по должности и флажками заявки на оборудование; редактируются только поля.","Создай шаблон контракта SOW .docx с MERGEFIELD-плейсхолдерами для имени клиента, даты вступления в силу, пунктов объёма работ, общей суммы и блока подписей; защитить всё, кроме области подписи.","Сделай .docx-анкету для медицинского приёма с выпадающим списком причины визита, текстовыми полями для аллергий / принимаемых лекарств, сеткой флажков по перенесённым заболеваниям и строкой подписи внизу."],"en-US":["Build a new-hire onboarding .docx form with fields for full name, start date, department, manager, role-based training checklist, and equipment request checkboxes; only the fields are editable.","Create a SOW contract template .docx with mail-merge placeholders for client name, effective date, scope bullets, total fee, and signature blocks; protect everything except the signature area.","Make a medical intake questionnaire .docx with dropdown for reason of visit, text fields for allergies / current medication, checkbox grid for past conditions, and signature line at the bottom."],"zh-CN":["做一份新员工入职登记 .docx 表单，包含姓名、入职日期、部门、直属上级、岗位培训 checklist 和设备申请复选框；其他排版保护，只字段可填。","做一份 SOW 合同模板 .docx，邮件合并占位客户名、生效日期、工作范围 bullets、总费用、签署栏；签名区以外全部保护。","做一份医疗问诊表 .docx，就诊原因下拉、过敏史 / 正在服用药物文本字段、既往病史复选矩阵、末尾签名行。"],"uk-UA":["Зроби .docx-форму прийому нового співробітника з полями ПІБ, дата початку, відділ, керівник, чек-листом навчання за посадою та прапорцями запиту обладнання; редагуються лише поля.","Створи шаблон контракту SOW .docx з MERGEFIELD-плейсхолдерами для імені клієнта, дати набрання чинності, обсягу робіт, загальної суми та блоку підписів; захисти все, крім області підпису.","Зроби .docx-анкету медичного прийому з випадаючим списком причини візиту, текстовими полями для алергій / прийнятих ліків, сіткою прапорців за минулими станами та рядком підпису внизу."]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-word-form"]','[]','[]','auto','[]',1790212086331,1790248654956,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a3f-7b12-8d5f-0627eeb59262',NULL,'morph-ppt-3d','builtin','system','morph-ppt-3d','3D Morph PPT','{"zh-CN":"3D Morph PPT","en-US":"3D Morph PPT"}','Turn a GLB 3D model into a cinematic Morph presentation. The model is the visual hero — close-up for details, bird''s eye for structure, low angle for drama, with smooth Morph transitions between every shot. Note: 3D models and Morph transitions require Microsoft PowerPoint to display correctly.','{"en-US":"Turn a GLB 3D model into a cinematic Morph presentation. The model is the visual hero — close-up for details, bird''s eye for structure, low angle for drama, with smooth Morph transitions between every shot. Note: 3D models and Morph transitions require Microsoft PowerPoint to display correctly.","zh-CN":"把 GLB 3D 模型变成电影感 Morph 演示文稿。模型是视觉主角——特写看细节、俯视看结构、仰拍看气势，每页之间用 Morph 转场做流畅的镜头运动。注意：3D 模型和 Morph 转场效果需要在微软 PowerPoint 中打开才能正常显示。"}','builtin_asset','avatars/morph-ppt-3d.jpg','632f31d2','builtin_asset','morph-ppt-3d','["Use this GLB model to create a product showcase. Content should revolve around the model — what it is, its features, its story. Each slide shows a different angle that matches the topic: close-up for details, bird''s eye for structure, dramatic low angle for the climax.","Here is my GLB model. Study it carefully, then create a cinematic presentation where the model is the hero of every frame. I want varied camera work: push in for detail shots, pull back for overview, bleed the model off the edge for dramatic transitions.","Build a presentation around this 3D model that feels like a movie trailer. Big dramatic moments, intimate close-ups, sweeping overview shots. The story should match what the model actually is — don''t just add generic text."]','{"en-US":["Use this GLB model to create a product showcase. Content should revolve around the model — what it is, its features, its story. Each slide shows a different angle that matches the topic: close-up for details, bird''s eye for structure, dramatic low angle for the climax.","Here is my GLB model. Study it carefully, then create a cinematic presentation where the model is the hero of every frame. I want varied camera work: push in for detail shots, pull back for overview, bleed the model off the edge for dramatic transitions.","Build a presentation around this 3D model that feels like a movie trailer. Big dramatic moments, intimate close-ups, sweeping overview shots. The story should match what the model actually is — don''t just add generic text."],"zh-CN":["用这个 GLB 模型做一份产品展示 PPT。内容要围绕模型展开——它是什么、有什么特点、背后的故事。每页用不同视角配合主题：讲细节就特写、讲结构就俯视、讲气势就仰拍，画面要丰富有层次。","这是我的 GLB 模型，仔细观察它，然后做一份电影感演示，模型是每一帧的主角。镜头要多变：推近看细节、拉远看全貌、模型出血到画面边缘做冲击转场。内容必须贴合模型本身。","围绕这个 3D 模型做一份像电影预告片一样的演示。要有大气的高潮时刻、细腻的特写镜头、开阔的全景俯瞰。故事要契合模型本身的特征——不要用跟模型无关的通用文案。"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["morph-ppt-3d","morph-ppt"]','[]','[]','auto','[]',1790212086336,1790248654939,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a44-72d3-a837-58a4e8010ca5',NULL,'moltbook','builtin','system','moltbook','moltbook','{"ru-RU":"moltbook","en-US":"moltbook","zh-CN":"moltbook","uk-UA":"moltbook"}','The social network for AI agents. Post, comment, upvote, and create communities.','{"en-US":"The social network for AI agents. Post, comment, upvote, and create communities.","ru-RU":"Социальная сеть для AI-агентов: публикации, комментарии, голосования и создание сообществ.","zh-CN":"AI 代理的社交网络。发帖、评论、投票、创建社区。","uk-UA":"Соціальна мережа для AI-агентів. Публікації, коментарі, голосування та створення спільнот."}','builtin_asset','avatars/moltbook.jpg','632f31d2','builtin_asset','moltbook','["Check my moltbook feed for latest updates","Post an interesting update to moltbook","Check for new direct messages"]','{"en-US":["Check my moltbook feed for latest updates","Post an interesting update to moltbook","Check for new direct messages"],"uk-UA":["Перевірити стрічку moltbook на наявність оновлень","Опублікувати цікавий пост у moltbook","Перевірити нові особисті повідомлення"],"ru-RU":["Проверь мою ленту moltbook на наличие новых обновлений","Опубликуй интересное обновление в moltbook","Проверь новые личные сообщения"],"zh-CN":["查看我的 moltbook 最新动态","在 moltbook 发布一条有趣的动态","检查是否有新私信"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["moltbook"]','[]','[]','auto','[]',1790212086340,1790248654942,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a48-7bb3-8f93-fe50fd4640bc',NULL,'game-3d','builtin','system','game-3d','3D Game','{"zh-CN":"3D 游戏生成","uk-UA":"Генератор 3D-ігор","en-US":"3D Game","ru-RU":"Генератор 3D-игр"}','Generate a complete 3D platform collection game in one HTML file.','{"uk-UA":"Генеруйте повноцінну 3D-гру-платформер зі збором предметів в одному HTML-файлі.","en-US":"Generate a complete 3D platform collection game in one HTML file.","ru-RU":"Генерирует полноценную 3D-игру-платформер со сбором предметов в одном HTML-файле.","zh-CN":"用单个 HTML 文件生成完整的 3D 平台收集游戏。"}','builtin_asset','avatars/game-3d.jpg','632f31d2','builtin_asset','game-3d','["Create a 3D platformer game with jumping mechanics","Make a coin collection game with obstacles","Build a 3D maze exploration game"]','{"uk-UA":["Створити 3D-платформер з механікою стрибків","Зробити гру зі збором монет та перешкодами","Побудувати 3D-гру з дослідженням лабіринту"],"zh-CN":["创建一个带跳跃机制的 3D 平台游戏","制作一个带障碍物的金币收集游戏","构建一个 3D 迷宫探索游戏"],"en-US":["Create a 3D platformer game with jumping mechanics","Make a coin collection game with obstacles","Build a 3D maze exploration game"],"ru-RU":["Создай 3D-платформер с механикой прыжков","Сделай игру со сбором монет и препятствиями","Построй 3D-игру с исследованием лабиринта"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','[]','[]','[]','auto','[]',1790212086345,1790248654983,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a4d-75d3-b1dc-321df6e6e5aa',NULL,'beautiful-mermaid','builtin','system','beautiful-mermaid','Beautiful Mermaid','{"zh-CN":"Beautiful Mermaid","uk-UA":"Beautiful Mermaid","ru-RU":"Beautiful Mermaid","en-US":"Beautiful Mermaid"}','Create flowcharts, sequence diagrams, state diagrams, class diagrams, and ER diagrams with beautiful themes.','{"zh-CN":"创建流程图、时序图、状态图、类图和 ER 图，支持多种精美主题。","uk-UA":"Створюйте блок-схеми, діаграми послідовності, станів, класів та ER-діаграми з красивими темами оформлення.","en-US":"Create flowcharts, sequence diagrams, state diagrams, class diagrams, and ER diagrams with beautiful themes.","ru-RU":"Создаёт блок-схемы, sequence-, state-, class- и ER-диаграммы с красивыми темами оформления."}','builtin_asset','avatars/beautiful-mermaid.jpg','632f31d2','builtin_asset','beautiful-mermaid','["Draw a detailed user login authentication flowchart","Create an API sequence diagram for payment processing","Create a system architecture diagram"]','{"ru-RU":["Нарисуй подробную блок-схему аутентификации при входе пользователя","Создай sequence-диаграмму API для обработки платежей","Создай диаграмму системной архитектуры"],"uk-UA":["Намалювати детальну блок-схему автентифікації користувача","Створити діаграму послідовності API для обробки платежів","Створити діаграму архітектури системи"],"en-US":["Draw a detailed user login authentication flowchart","Create an API sequence diagram for payment processing","Create a system architecture diagram"],"zh-CN":["绘制详细的用户登录认证流程图","创建支付处理的 API 时序图","创建系统架构图"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["mermaid"]','[]','[]','auto','[]',1790212086349,1790248654989,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a51-7e33-9e48-3b7cdbdb061b',NULL,'ppt-creator','builtin','system','ppt-creator','PPT Creator','{"ru-RU":"Помощник PPT","zh-CN":"PPT 演示助手","en-US":"PPT Creator","uk-UA":"Помічник PPT"}','Create, edit, and analyze professional PowerPoint presentations with officecli. Bold designs, varied layouts, and visual impact.','{"zh-CN":"使用 officecli 创建、编辑和分析专业 PPT 演示文稿。大胆设计、丰富版式、视觉冲击。","uk-UA":"Створюйте, редагуйте та аналізуйте професійні презентації PowerPoint за допомогою officecli: виразний дизайн, різноманітні макети та візуальний вплив.","en-US":"Create, edit, and analyze professional PowerPoint presentations with officecli. Bold designs, varied layouts, and visual impact.","ru-RU":"Создаёт, редактирует и анализирует профессиональные презентации PowerPoint с помощью officecli: выразительный дизайн, разнообразные макеты и сильная визуальная подача."}','builtin_asset','avatars/ppt-creator.jpg','632f31d2','builtin_asset','ppt-creator','["Create a 10-slide Kubernetes migration proposal with architecture comparison, cost analysis, and migration timeline","Create a 10-slide SaaS analytics dashboard for a project management tool with user growth charts, conversion funnel, and competitive landscape","Create a 10-slide fintech product roadmap for a digital payment platform with user growth trajectory and investment analysis"]','{"en-US":["Create a 10-slide Kubernetes migration proposal with architecture comparison, cost analysis, and migration timeline","Create a 10-slide SaaS analytics dashboard for a project management tool with user growth charts, conversion funnel, and competitive landscape","Create a 10-slide fintech product roadmap for a digital payment platform with user growth trajectory and investment analysis"],"uk-UA":["Створити презентацію на 10 слайдів щодо міграції на Kubernetes з порівнянням архітектур, аналізом витрат та графіком міграції","Створити 10 слайдів дашборду аналітики SaaS для інструменту управління проектами з графіками росту користувачів та аналізом конкурентів","Створити дорожню карту фінтех-продукту на 10 слайдів для платформи цифрових платежів з аналізом інвестицій"],"ru-RU":["Создай презентацию на 10 слайдов о миграции в Kubernetes со сравнением архитектур, анализом затрат и графиком миграции","Создай презентацию на 10 слайдов с аналитическим дашбордом для SaaS-инструмента управления проектами: графики роста пользователей, воронка конверсий и конкурентный ландшафт","Создай презентацию на 10 слайдов с дорожной картой финтех-продукта для платформы цифровых платежей: траектория роста пользователей и инвестиционный анализ"],"zh-CN":["做一份 10 页的 Kubernetes 迁移方案 PPT，包含架构对比、成本分析和迁移时间线","做一份 10 页的 SaaS 产品数据看板 PPT，包含用户增长图表、转化漏斗和竞品分析","做一份 10 页的金融科技产品路线图 PPT，包含用户增长趋势和投资分析"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-pptx"]','[]','[]','auto','[]',1790212086354,1790248654966,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a56-7793-9d22-c2e4e1d2545d',NULL,'financial-model-creator','builtin','system','financial-model-creator','Financial Model Creator','{"en-US":"Financial Model Creator","zh-CN":"财务建模助手","ru-RU":"Создатель финансовых моделей","uk-UA":"Фінансовий моделіст"}','Build formula-driven financial models from text prompts: 3-statement models, DCF valuations, cap tables, scenario analyses, sensitivity tables, and debt schedules. All values flow from assumptions through interconnected formula chains.','{"ru-RU":"Строит финансовые модели на основе текстового запроса: три финансовые формы, DCF-оценка, cap table, сценарный анализ, таблицы чувствительности и долговые графики. Все значения выводятся через связные формульные цепочки от исходных предположений.","en-US":"Build formula-driven financial models from text prompts: 3-statement models, DCF valuations, cap tables, scenario analyses, sensitivity tables, and debt schedules. All values flow from assumptions through interconnected formula chains.","zh-CN":"根据文本描述构建公式驱动的财务模型：三表联动、DCF 估值、股权表、情景分析、敏感性分析和债务计划。所有数值通过公式链从假设条件层层推导。","uk-UA":"Будуйте фінансові моделі на основі формул за текстовим запитом: три фінансові форми, DCF-оцінка, Cap Tables, сценарний аналіз та графіки боргів."}','builtin_asset','avatars/financial-model-creator.jpg','632f31d2','builtin_asset','financial-model-creator','["Build a 3-year SaaS financial model with income statement, balance sheet, cash flow, and dashboard charts","Create a DCF valuation for a manufacturing company with WACC calculation and sensitivity table","Build a cap table with seed and Series A rounds, liquidation preferences, and exit waterfall analysis"]','{"zh-CN":["搭建一个 3 年期 SaaS 财务模型，包含利润表、资产负债表、现金流量表和看板图表","为制造业公司创建 DCF 估值模型，包含 WACC 计算和敏感性分析表","搭建股权表，包含种子轮和 A 轮融资、清算优先权和退出瀑布分析"],"ru-RU":["Построй трёхлетнюю финансовую модель для SaaS с отчётом о прибылях и убытках, балансом, отчётом о движении денежных средств и графиками дашборда","Создай DCF-оценку для производственной компании с расчётом WACC и таблицей чувствительности","Построй cap table с раундами seed и Series A, ликвидационными преференциями и каскадным анализом выхода"],"uk-UA":["Побудувати 3-річну фінансову модель SaaS зі звітом про прибутки, балансом та графіками","Створити оцінку DCF для виробничої компанії з розрахунком WACC та таблицею чутливості","Побудувати Cap Table з раундами Seed та раундом A, преференціями ліквідації"],"en-US":["Build a 3-year SaaS financial model with income statement, balance sheet, cash flow, and dashboard charts","Create a DCF valuation for a manufacturing company with WACC calculation and sensitivity table","Build a cap table with seed and Series A rounds, liquidation preferences, and exit waterfall analysis"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-financial-model"]','[]','[]','auto','[]',1790212086358,1790248654985,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a59-72b2-95f0-8a0cdfa5c9af',NULL,'pitch-deck-creator','builtin','system','pitch-deck-creator','Pitch Deck Creator','{"uk-UA":"Створювач пітч-деків","en-US":"Pitch Deck Creator","zh-CN":"路演 PPT 助手","ru-RU":"Создатель питч-деков"}','Build investor pitch decks, product launch presentations, and enterprise sales decks with gradient designs, data charts, competitive tables, team slides, and speaker notes. Supports seed to Series A+ decks.','{"ru-RU":"Создаёт инвесторские питч-деки, презентации запусков и корпоративные продажи: градиентный дизайн, графики, таблицы конкурентов, слайды команды и заметки спикера. Подходит для стадий от seed до Series A и выше.","uk-UA":"Створюйте інвесторські пітч-деки, презентації продуктів та корпоративні продажі: градієнтний дизайн, графіки, таблиці конкурентів, слайди команди та нотатки доповідача. Підходить для стадій від Seed до Series A+.","en-US":"Build investor pitch decks, product launch presentations, and enterprise sales decks with gradient designs, data charts, competitive tables, team slides, and speaker notes. Supports seed to Series A+ decks.","zh-CN":"制作投资路演、产品发布和企业销售演示文稿，包含渐变设计、数据图表、竞品表格、团队页和演讲者备注。支持从种子轮到 A 轮及以上的路演。"}','builtin_asset','avatars/pitch-deck-creator.jpg','632f31d2','builtin_asset','pitch-deck-creator','["Create a 12-slide Series A investor deck for a B2B SaaS data pipeline startup with ARR charts, competitive comparison table, team avatars, and financial projections","Create an 8-slide product launch deck for an AI code review tool with 5 feature icons, before/after comparison, customer satisfaction doughnut chart, and 3-tier pricing table","Create a 10-slide enterprise sales deck for a cybersecurity platform with ROI analysis, radar chart vs competitors, financial impact table, and implementation timeline"]','{"ru-RU":["Создай инвесторский питч-дек на 12 слайдов для B2B SaaS-стартапа по построению дата-пайплайнов: графики ARR, таблица сравнения с конкурентами, аватары команды и финансовые прогнозы","Создай презентацию запуска продукта на 8 слайдов для инструмента AI-ревью кода: 5 иконок функций, сравнение «до/после», кольцевая диаграмма удовлетворённости клиентов и трёхуровневая таблица тарифов","Создай корпоративный продающий дек на 10 слайдов для платформы кибербезопасности: анализ ROI, радарная диаграмма сравнения с конкурентами, таблица финансового влияния и график внедрения"],"zh-CN":["为一个 B2B SaaS 数据管道创业公司制作 12 页 A 轮投资路演，包含 ARR 图表、竞品对比表、团队头像和财务预测","为一个 AI 代码审查工具制作 8 页产品发布演示，包含 5 个功能图标、前后对比、客户满意度环形图和 3 档定价表","为一个网络安全平台制作 10 页企业销售演示，包含 ROI 分析、雷达图竞品对比、财务影响表和实施时间线"],"uk-UA":["Створити інвесторський дек на 12 слайдів раунду A для стартапу B2B SaaS з графіками ARR, таблицею конкурентів та фінансовими прогнозами","Створити 8 слайдів для запуску продукту AI code review з іконками функцій, порівнянням \"до/після\" та таблицею цін","Створити 10 слайдів корпоративної презентації для платформи кібербезпеки з аналізом ROI та графіком впровадження"],"en-US":["Create a 12-slide Series A investor deck for a B2B SaaS data pipeline startup with ARR charts, competitive comparison table, team avatars, and financial projections","Create an 8-slide product launch deck for an AI code review tool with 5 feature icons, before/after comparison, customer satisfaction doughnut chart, and 3-tier pricing table","Create a 10-slide enterprise sales deck for a cybersecurity platform with ROI analysis, radar chart vs competitors, financial impact table, and implementation timeline"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-pitch-deck"]','[]','[]','auto','[]',1790212086362,1790248654935,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a5d-7ee1-8e71-6fad21e43ceb',NULL,'morph-ppt','builtin','system','morph-ppt','Morph PPT','{"zh-CN":"Morph PPT","ru-RU":"Morph PPT","en-US":"Morph PPT","uk-UA":"Morph PPT"}','Create professional Morph-animated presentations with officecli. Supports multiple visual styles and end-to-end workflow from topic to polished slides.','{"zh-CN":"使用 officecli 创建专业的 Morph 动画演示文稿。支持多种视觉风格，从主题到精美幻灯片的端到端工作流。","ru-RU":"Создаёт профессиональные презентации с анимацией Morph через officecli. Поддерживает разные визуальные стили и полный цикл от идеи до готовых слайдов.","en-US":"Create professional Morph-animated presentations with officecli. Supports multiple visual styles and end-to-end workflow from topic to polished slides.","uk-UA":"Створюйте професійні презентації з анімацією Morph за допомогою officecli. Підтримує різні візуальні стилі та повний робочий процес від ідеї до готових слайдів."}','builtin_asset','avatars/morph-ppt.jpg','632f31d2','builtin_asset','morph-ppt','["Pick a fun topic yourself and create a complete PPT","Create the most beautiful PPT you can imagine, topic is up to you","Create a coffee brand introduction PPT with a minimalist premium feel"]','{"en-US":["Pick a fun topic yourself and create a complete PPT","Create the most beautiful PPT you can imagine, topic is up to you","Create a coffee brand introduction PPT with a minimalist premium feel"],"ru-RU":["Выбери интересную тему на своё усмотрение и создай полноценную презентацию","Создай самую красивую презентацию, которую только можешь представить — тему выбери сам","Создай презентацию о кофейном бренде в минималистичном премиальном стиле"],"zh-CN":["自己想一个有趣的主题，帮我做一份PPT","做一个你认为最好看的 PPT，主题你定","做一份咖啡品牌介绍PPT，要极简高级感"],"uk-UA":["Вибери цікаву тему самостійно та створи повноцінну презентацію","Створи найкрасивішу презентацію, яку тільки можеш уявити, тема на твій вибір","Створи презентацію про кавовий бренд у стилі мінімалістичного преміуму"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["morph-ppt"]','[]','[]','auto','[]',1790212086366,1790248654976,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a61-7680-b7f8-5afb9b59a2ee',NULL,'openclaw-setup','builtin','system','openclaw-setup','OpenClaw Setup Expert','{"en-US":"OpenClaw Setup Expert","zh-CN":"OpenClaw 部署专家","uk-UA":"Експерт з налаштування OpenClaw","ru-RU":"Эксперт по настройке OpenClaw"}','Expert guide for installing, deploying, configuring, and troubleshooting OpenClaw. Proactively helps with setup, diagnoses issues, and provides security best practices.','{"en-US":"Expert guide for installing, deploying, configuring, and troubleshooting OpenClaw. Proactively helps with setup, diagnoses issues, and provides security best practices.","zh-CN":"OpenClaw 安装、部署、配置和故障排查专家。主动协助设置、诊断问题并提供安全最佳实践。","ru-RU":"Эксперт по установке, развёртыванию, настройке и устранению неполадок OpenClaw. Помогает пройти настройку, диагностирует проблемы и подсказывает безопасные практики.","uk-UA":"Експертний посібник зі встановлення, розгортання, налаштування та усунення несправностей OpenClaw. Допомагає з налаштуванням та безпекою."}','builtin_asset','avatars/openclaw-setup.jpg','632f31d2','builtin_asset','openclaw-setup','["Help me install OpenClaw step by step","My OpenClaw isn''t working, please diagnose the issue","Configure Telegram channel for OpenClaw integration"]','{"en-US":["Help me install OpenClaw step by step","My OpenClaw isn''t working, please diagnose the issue","Configure Telegram channel for OpenClaw integration"],"ru-RU":["Помоги мне установить OpenClaw пошагово","Мой OpenClaw не работает, пожалуйста, диагностируй проблему","Настрой Telegram-канал для интеграции с OpenClaw"],"uk-UA":["Допоможи мені встановити OpenClaw крок за кроком","Мій OpenClaw не працює, будь ласка, діагностуй проблему","Налаштувати канал Telegram для інтеграції з OpenClaw"],"zh-CN":["帮我一步步安装 OpenClaw","我的 OpenClaw 出问题了，请帮我诊断","为 OpenClaw 配置 Telegram 渠道"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["openclaw-setup","aionui-webui-setup"]','[]','[]','auto','[]',1790212086369,1790248654998,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a65-7121-841e-eb6d8360a290',NULL,'cowork','builtin','system','cowork','Cowork','{"ru-RU":"Cowork","uk-UA":"Cowork","en-US":"Cowork","zh-CN":"Cowork"}','Autonomous task execution with file operations, document processing, and multi-step workflow planning.','{"ru-RU":"Автономный помощник для выполнения задач с работой с файлами, обработкой документов и многошаговым планированием.","zh-CN":"具有文件操作、文档处理和多步骤工作流规划的自主任务执行助手。","uk-UA":"Автономне виконання завдань з роботою з файлами, обробкою документів та багатокроковим плануванням робочих процесів.","en-US":"Autonomous task execution with file operations, document processing, and multi-step workflow planning."}','builtin_asset','avatars/cowork.jpg','632f31d2','builtin_asset','cowork','["Analyze the current project structure and suggest improvements","Automate the build and deployment process","Extract and summarize key information from all PDF files"]','{"uk-UA":["Проаналізувати структуру поточного проекту та запропонувати покращення","Автоматизувати процес збірки та розгортання","Витягти та узагальнити ключову інформацію з усіх файлів PDF"],"ru-RU":["Проанализируй структуру текущего проекта и предложи улучшения","Автоматизируй процесс сборки и развёртывания","Извлеки и обобщи ключевую информацию из всех PDF-файлов"],"en-US":["Analyze the current project structure and suggest improvements","Automate the build and deployment process","Extract and summarize key information from all PDF files"],"zh-CN":["分析当前项目结构并建议改进方案","自动化构建和部署流程","提取并总结所有 PDF 文件的关键信息"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["skill-creator","officecli-pptx","officecli-docx","pdf","officecli-xlsx"]','[]','[]','auto','[]',1790212086374,1790248654930,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a69-71d3-841f-71d52fcf79af',NULL,'word-creator','builtin','system','word-creator','Word Creator','{"zh-CN":"Word 文档助手","en-US":"Word Creator","uk-UA":"Помічник Word","ru-RU":"Помощник Word"}','Create, edit, and analyze professional Word documents with officecli. Reports, proposals, letters, memos, and more.','{"zh-CN":"使用 officecli 创建、编辑和分析专业 Word 文档。报告、方案、信函、备忘录等。","ru-RU":"Создаёт, редактирует и анализирует профессиональные документы Word с помощью officecli: отчёты, предложения, письма, служебные записки и другое.","en-US":"Create, edit, and analyze professional Word documents with officecli. Reports, proposals, letters, memos, and more.","uk-UA":"Створюйте, редагуйте та аналізуйте професійні документи Word за допомогою officecli: звіти, пропозиції, листи, нотатки тощо."}','builtin_asset','avatars/word-creator.jpg','632f31d2','builtin_asset','word-creator','["Create a Q1 2026 quarterly report with TOC, financial highlights table, revenue trend chart, and KPI metrics section","Write an academic research paper on machine learning with LaTeX equations, citations, data tables, and bibliography","Create a project status report with DRAFT watermark, color-coded status table, and a Gantt timeline in landscape section"]','{"ru-RU":["Создай отчёт за Q1 2026 с оглавлением, таблицей финансовых показателей, графиком трендов выручки и разделом KPI","Напиши академическую статью по машинному обучению с формулами LaTeX, цитатами, таблицами данных и библиографией","Создай отчёт о статусе проекта с водяным знаком DRAFT, цветовой таблицей статусов и диаграммой Ганта в альбомной секции"],"uk-UA":["Створити квартальний звіт за 1 квартал 2026 року зі змістом, таблицею фінансових показників, графіком трендів доходів та розділом KPI","Написати наукову статтю про машинне навчання з формулами LaTeX, цитатами, таблицями даних та бібліографією","Створити звіт про статус проекту з водяним знаком DRAFT, кольоровою таблицею статусів та діаграмою Ганта"],"zh-CN":["创建一份 2026 年 Q1 季度报告，包含目录、财务亮点表格、营收趋势图和 KPI 指标","写一篇关于机器学习的学术论文，包含 LaTeX 公式、引用、数据表格和参考文献","创建一份项目状态报告，带 DRAFT 水印、彩色状态表格和横向甘特图时间线"],"en-US":["Create a Q1 2026 quarterly report with TOC, financial highlights table, revenue trend chart, and KPI metrics section","Write an academic research paper on machine learning with LaTeX equations, citations, data tables, and bibliography","Create a project status report with DRAFT watermark, color-coded status table, and a Gantt timeline in landscape section"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-docx"]','[]','[]','auto','[]',1790212086377,1790248654972,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a6d-7420-b3f1-5ff3011b0ded',NULL,'human-3-coach','builtin','system','human-3-coach','HUMAN 3.0 Coach','{"ru-RU":"Коуч HUMAN 3.0","uk-UA":"Коуч HUMAN 3.0","en-US":"HUMAN 3.0 Coach","zh-CN":"HUMAN 3.0 教练"}','Personal development coach based on HUMAN 3.0 framework: 4 Quadrants (Mind/Body/Spirit/Vocation), 3 Levels, 3 Growth Phases.','{"ru-RU":"Коуч по личному развитию на основе фреймворка HUMAN 3.0: 4 квадранта (ум, тело, дух, призвание), 3 уровня и 3 фазы роста.","zh-CN":"基于 HUMAN 3.0 框架的个人发展教练：4 象限（思维/身体/精神/职业）、3 层次、3 成长阶段。","en-US":"Personal development coach based on HUMAN 3.0 framework: 4 Quadrants (Mind/Body/Spirit/Vocation), 3 Levels, 3 Growth Phases.","uk-UA":"Коуч з особистого розвитку на основі фреймворка HUMAN 3.0: 4 квадранти (Розум/Тіло/Дух/Призвання), 3 рівні та 3 фази росту."}','builtin_asset','avatars/human-3-coach.jpg','632f31d2','builtin_asset','human-3-coach','["Help me set quarterly goals across all life quadrants","Reflect on my career progress and plan next steps","Create a personal development plan for the next 3 months"]','{"zh-CN":["帮我设定涵盖所有生活象限的季度目标","反思我的职业发展进度并规划下一步","为未来 3 个月创建个人发展计划"],"ru-RU":["Помоги мне поставить квартальные цели по всем сферам жизни","Проанализируй мой карьерный прогресс и спланируй следующие шаги","Создай план личного развития на ближайшие 3 месяца"],"en-US":["Help me set quarterly goals across all life quadrants","Reflect on my career progress and plan next steps","Create a personal development plan for the next 3 months"],"uk-UA":["Допоможи мені встановити квартальні цілі в усіх сферах життя","Проаналізувати мій кар''єрний шлях та спланувати наступні кроки","Створити план особистого розвитку на наступні 3 місяці"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','[]','[]','[]','auto','[]',1790212086381,1790248654995,NULL);
INSERT INTO "assistant_definitions" VALUES('asstdef_01a0d0f4-9a71-7d03-9dc4-fb55a9424989',NULL,'excel-creator','builtin','system','excel-creator','Excel Creator','{"en-US":"Excel Creator","zh-CN":"Excel 表格助手","ru-RU":"Помощник Excel","uk-UA":"Помічник Excel"}','Create, edit, and analyze professional Excel spreadsheets with officecli. Financial models, dashboards, trackers, and data analysis.','{"zh-CN":"使用 officecli 创建、编辑和分析专业 Excel 表格。财务模型、数据看板、追踪表和数据分析。","ru-RU":"Создаёт, редактирует и анализирует профессиональные таблицы Excel с помощью officecli: финансовые модели, дашборды, трекеры и анализ данных.","uk-UA":"Створюйте, редагуйте та аналізуйте професійні таблиці Excel за допомогою officecli: фінансові моделі, дашборди, трекери та аналіз даних.","en-US":"Create, edit, and analyze professional Excel spreadsheets with officecli. Financial models, dashboards, trackers, and data analysis."}','builtin_asset','avatars/excel-creator.jpg','632f31d2','builtin_asset','excel-creator','["Build a 3-sheet financial dashboard with income statement, revenue breakdown chart, and conditional formatting for variances","Create a sales pipeline tracker with deal stages, weighted pipeline formulas, funnel chart, and rep performance scorecards","Create a budget tracker with cross-sheet variance formulas, budget vs actuals bar chart, and color-coded over-budget highlights"]','{"en-US":["Build a 3-sheet financial dashboard with income statement, revenue breakdown chart, and conditional formatting for variances","Create a sales pipeline tracker with deal stages, weighted pipeline formulas, funnel chart, and rep performance scorecards","Create a budget tracker with cross-sheet variance formulas, budget vs actuals bar chart, and color-coded over-budget highlights"],"ru-RU":["Собери финансовый дашборд на 3 листах: отчёт о прибылях и убытках, диаграмма структуры выручки и условное форматирование для отклонений","Создай трекер воронки продаж с этапами сделок, формулами взвешенного пайплайна, воронкообразной диаграммой и карточками эффективности менеджеров","Создай трекер бюджета с межлистовыми формулами отклонений, столбчатой диаграммой «план/факт» и цветовой подсветкой превышения бюджета"],"uk-UA":["Побудувати фінансовий дашборд на 3 аркуші зі звітом про прибутки, діаграмою доходів та умовним форматуванням","Створити трекер продажів зі стадіями угод, формулами зваженого пайплайну та картками показників менеджерів","Створити бюджетний трекер із формулами розбіжностей між аркушами та гістограмою \"бюджет проти факту\""],"zh-CN":["创建一个 3 页的财务看板，包含利润表、营收分布图和差异条件格式","创建一个销售管道追踪表，包含阶段统计、加权管道公式、漏斗图和销售代表业绩看板","创建一个预算追踪表，包含跨表差异公式、预算对比柱状图和超支红色高亮"]}','auto',NULL,'auto',NULL,'auto',NULL,'fixed','["officecli-xlsx"]','[]','[]','auto','[]',1790212086385,1790248654952,NULL);
