INSERT INTO "messages" VALUES('47799d9d','96eb91fc','47799d9d','text','{"content":"Я — **Antigravity**, интеллектуальный ИИ-ассистент, разработанный командой Google Deepmind для решения сложных задач и помощи в программировании. \n\nВ основе моей работы лежат технологии семейства Gemini от Google. Согласно текущим системным настройкам, я работаю на базе модели **gemini-farm** — специальной версии архитектуры, которая отлично справляется с использованием инструментов, написанием кода и автономным выполнением многошаговых задач на вашем компьютере."}','left','finish',0,1790216890400,NULL);
