INSERT INTO "messages" VALUES('aionrs-call_19952','96eb91fc','aionrs-call_19952','tool_call','{"call_id":"aionrs-call_19952","name":"ExecCommand","args":{"cmd":"sed -n ''406,440p'' \"/mnt/d/My files/herdrControlGui/claude_oauth_manager.py\" | tr -d ''\\r''"},"status":"completed","input":{"cmd":"sed -n ''406,440p'' \"/mnt/d/My files/herdrControlGui/claude_oauth_manager.py\" | tr -d ''\\r''"},"output":"Exit code: 0\nSTDOUT:\ndef launch_login_terminal(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Открывает терминал WSL с `claude auth login` для нового профиля через Claude Proxy.\"\"\"\n    profile_name = (profile_name or \"\").strip()\n    if not is_valid_profile_name(profile_name):\n        return False, f\"Некорректное имя профиля: ''{profile_name}''. Допустимы латиница, цифры и символы @._+-\"\n    if (PROFILES_DIR / profile_name / CREDENTIALS_NAME).exists():\n        return False, f\"Профиль ''{profile_name}'' уже существует.\"\n\n    px = get_claude_oauth_proxy()\n    if not is_claude_proxy_online():\n        return False, (\n            f\"Anthropic Claude Proxy {px[''host'']}:{px[''port'']} недоступен.\\n\"\n            f\"Вход заблокирован, чтобы не раскрыть реальный IP. Запустите прокси на странице Routes.\"\n        )\n\n    try:\n        (PROFILES_DIR / profile_name).mkdir(parents=True, exist_ok=True)\n        _write_json(PROFILES_DIR / profile_name / PROFILE_META_NAME, {\n            \"profile_name\": profile_name,\n            \"created_at\": time.strftime(\"%Y-%m-%d %H:%M:%S\"),\n            \"source\": \"login\",\n            \"proxy_port\": px[\"port\"],\n        })\n    except Exception:\n        pass\n\n    bash_cmd = build_login_bash_command(profile_name, px)\n    try:\n        subprocess.Popen(\n            [\"wt.exe\", \"-w\", \"0\", \"nt\", \"wsl.exe\", \"-d\", WSL_DISTRO, \"-u\", WSL_USER, \"bash\", \"-lc\", bash_cmd],\n            creationflags=0,\n        )\n        return True, f\"Терминал входа открыт. Прокси: {px[''host'']}:{px[''port'']} (HTTP :{px[''http_port'']})\"\n    except Exception:\n        pass\n\nSTDERR:"}','left','finish',0,1790225839162,NULL);
INSERT INTO "messages" VALUES('aionrs-call_184214','96eb91fc','aionrs-call_184214','tool_call','{"call_id":"aionrs-call_184214","name":"ExecCommand","args":{"cmd":"sed -n ''924,960p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\" | tr -d ''\\r''"},"status":"completed","input":{"cmd":"sed -n ''924,960p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\" | tr -d ''\\r''"},"output":"Exit code: 0\nSTDOUT:\ndef launch_add_account_terminal(profile_name: str | None = None) -> bool:\n    \"\"\"Запускает окно терминала с процедурой добавления нового аккаунта Google.\"\"\"\n    cmd_name = profile_name or f\"account-{len(list_profiles()) + 1}\"\n    bash_cmd = f\"gemini-oauth add {cmd_name}\"\n\n    try:\n        subprocess.Popen(\n            [\"wt.exe\", \"-w\", \"0\", \"nt\", \"wsl.exe\", \"-d\", WSL_DISTRO, \"-u\", WSL_USER, \"bash\", \"-lic\", bash_cmd],\n            creationflags=0,\n        )\n        return True\n    except Exception:\n        pass\n\n    try:\n        win_cmd = f''cmd.exe /c start \"Herdr — Вход в Google Gemini OAuth\" wsl.exe -d {WSL_DISTRO} -u {WSL_USER} bash -lic \"{bash_cmd}\"''\n        subprocess.Popen(win_cmd, shell=True)\n        return True\n    except Exception:\n        return False\n\ndef delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    try:\n        is_active = False\n        t_path = target / \"antigravity-oauth-token\"\n        if t_path.exists() and ACTIVE_TOKEN_FILE.exists():\n            active_info = get_token_info(ACTIVE_TOKEN_FILE)\n            target_info = get_token_info(t_path)\n            if active_info.get(\"email\") and active_info.get(\"email\") == target_info.get(\"email\"):\n                is_active = True\n\nSTDERR:"}','left','finish',0,1790225844403,NULL);
