INSERT INTO "messages" VALUES('aionrs-call_201582','96eb91fc','aionrs-call_201582','tool_call','{"call_id":"aionrs-call_201582","name":"ExecCommand","args":{"cmd":"sed -n ''924,960p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"status":"completed","input":{"cmd":"sed -n ''924,960p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"output":"Exit code: 0\nSTDOUT:\ndef launch_add_account_terminal(profile_name: str | None = None) -> bool:\n    \"\"\"Запускает окно терминала с процедурой добавления нового аккаунта Google.\"\"\"\n    cmd_name = profile_name or f\"account-{len(list_profiles()) + 1}\"\n    bash_cmd = f\"gemini-oauth add {cmd_name}\"\n\n    try:\n        subprocess.Popen(\n            [\"wt.exe\", \"-w\", \"0\", \"nt\", \"wsl.exe\", \"-d\", WSL_DISTRO, \"-u\", WSL_USER, \"bash\", \"-lic\", bash_cmd],\n            creationflags=0,\n        )\n        return True\n    except Exception:\n        pass\n\n    try:\n        win_cmd = f''cmd.exe /c start \"Herdr — Вход в Google Gemini OAuth\" wsl.exe -d {WSL_DISTRO} -u {WSL_USER} bash -lic \"{bash_cmd}\"''\n        subprocess.Popen(win_cmd, shell=True)\n        return True\n    except Exception:\n        return False\n\ndef delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    try:\n        is_active = False\n        t_path = target / \"antigravity-oauth-token\"\n        if t_path.exists() and ACTIVE_TOKEN_FILE.exists():\n            active_info = get_token_info(ACTIVE_TOKEN_FILE)\n            target_info = get_token_info(t_path)\n            if active_info.get(\"email\") and active_info.get(\"email\") == target_info.get(\"email\"):\n                is_active = True\n\nSTDERR:"}','left','finish',0,1790225906542,NULL);
