INSERT INTO "messages" VALUES('aionrs-call_271043','96eb91fc','aionrs-call_271043','tool_call','{"call_id":"aionrs-call_271043","name":"Read","args":{"file_path":"/mnt/d/My files/herdrControlGui/aionui_claude_bridge.py"},"status":"completed","input":{"file_path":"/mnt/d/My files/herdrControlGui/aionui_claude_bridge.py"},"output":"     1\t\"\"\"Модуль-мост между HerdrControlCenter, Anthropic Claude Code и AionUi.\n     2\n     3\tОбеспечивает автоматизацию всех шагов интеграции:\n     4\t1. Валидацию и импорт OAuth2-токенов Claude Pro/Team (.credentials.json) в Windows и WSL2.\n     5\t2. Проверку срока действия токенов (accessToken, refreshToken) и подписки.\n     6\t3. Синхронизацию прокси (SOCKS5 :1015 / HTTP CONNECT :11015) и защиту Killswitch в settings.json.\n     7\t4. Автоматическое обновление встроенных ресурсов AionUi (manifest.json, binary version 2.1.280+).\n     8\t5. Регистрацию исполняемого файла claude в базе данных AionUi (agent_metadata).\n     9\t6. Комплексную проверку здоровья и статуса подключения.\n    10\n    11\tМожет использоваться как библиотека внутри HerdrControlCenter, так и автономно через CLI:\n    12\t    python aionui_claude_bridge.py --status\n    13\t    python aionui_claude_bridge.py --import-oauth <path_to_json>\n    14\t    python aionui_claude_bridge.py --sync-all [path_to_json]\n    15\t    python aionui_claude_bridge.py --patch-aionui\n    16\t\"\"\"\n    17\n    18\tfrom __future__ import annotations\n    19\n    20\timport argparse\n    21\timport datetime\n    22\timport json\n    23\timport os\n    24\timport shutil\n    25\timport subprocess\n    26\timport sys\n    27\timport time\n    28\tfrom pathlib import Path\n    29\tfrom typing import Any\n    30\n    31\n    32\tWSL_DISTRO = os.environ.get(\"WSL_DISTRO\", \"Ubuntu\")\n    33\tWSL_USER = (os.environ.get(\"WSL_USER\") or os.environ.get(\"USERNAME\") or \"f\").strip()\n    34\n    35\n    36\tdef run_wsl_python(python_code: str, timeout: int = 15) -> tuple[int, str, str]:\n    37\t    \"\"\"Выполняет Python-код внутри WSL2 через передачу в stdin, избегая проблем с экранированием кавычек.\"\"\"\n    38\t    try:\n    39\t        res = subprocess.run(\n    40\t            [\"wsl\", \"-d\", WSL_DISTRO, \"python3\", \"-\"],\n    41\t            input=python_code,\n    42\t            capture_output=True,\n    43\t            text=True,\n    44\t            timeout=timeout,\n    45\t        )\n    46\t        return res.returncode, res.stdout, res.stderr\n    47\t    except Exception as e:\n    48\t        return -1, \"\", str(e)\n    49\n    50\n    51\tdef get_wsl_rootfs_path() -> Path | None:\n    52\t    \"\"\"Возвращает путь к WSL2 rootfs через UNC путь \\\\wsl$\\\\<distro> или \\\\wsl.localhost\\\\<distro>.\"\"\"\n    53\t    for prefix in [rf\"\\\\wsl$\\{WSL_DISTRO}\", rf\"\\\\wsl.localhost\\{WSL_DISTRO}\"]:\n    54\t        p = Path(prefix)\n    55\t        if p.exists():\n    56\t            return p\n    57\t    return None\n    58\n    59\n    60\tdef get_claude_credentials_files() -> list[Path]:\n    61\t    \"\"\"Возвращает пути к файлам .credentials.json в Windows и WSL2.\"\"\"\n    62\t    files: list[Path] = []\n    63\n    64\t    # 1. Windows: %USERPROFILE%\\.claude\\.credentials.json\n    65\t    try:\n    66\t        win_file = Path.home() / \".claude\" / \".credentials.json\"\n    67\t        files.append(win_file)\n    68\t    except Exception:\n    69\t        pass\n    70\n    71\t    # 2. WSL2: \\\\wsl$\\Ubuntu\\home\\<user>\\.claude\\.credentials.json\n    72\t    wsl_root = get_wsl_rootfs_path()\n    73\t    if wsl_root:\n    74\t        wsl_file = wsl_root / f\"home/{WSL_USER}/.claude/.credentials.json\"\n    75\t        files.append(wsl_file)\n    76\n    77\t    return files\n    78\n    79\n    80\tdef get_claude_settings_files() -> list[Path]:\n    81\t    \"\"\"Возвращает пути к файлам settings.json в Windows и WSL2.\"\"\"\n    82\t    files: list[Path] = []\n    83\t    try:\n    84\t        files.append(Path.home() / \".claude\" / \"settings.json\")\n    85\t    except Exception:\n    86\t        pass\n    87\n    88\t    wsl_root = get_wsl_rootfs_path()\n    89\t    if wsl_root:\n    90\t        files.append(wsl_root / f\"home/{WSL_USER}/.claude/settings.json\")\n    91\n    92\t    return files\n    93\n    94\n    95\tdef validate_oauth_data(raw_data: dict[str, Any]) -> tuple[bool, str, dict[str, Any]]:\n    96\t    \"\"\"Валидирует и нормализует структуру OAuth-данных Claude Code.\"\"\"\n    97\t    if not isinstance(raw_data, dict):\n    98\t        return False, \"Data must be a JSON object\", {}\n    99\n   100\t    oauth_section = raw_data.get(\"claudeAiOauth\")\n   101\t    if oauth_section and isinstance(oauth_section, dict):\n   102\t        data = oauth_section\n   103\t    else:\n   104\t        data = raw_data\n   105\n   106\t    access_token = data.get(\"accessToken\")\n   107\t    refresh_token = data.get(\"refreshToken\")\n   108\n   109\t    if not access_token or not isinstance(access_token, str):\n   110\t        return False, \"Missing or invalid ''accessToken'' field\", {}\n   111\n   112\t    if not refresh_token or not isinstance(refresh_token, str):\n   113\t        return False, \"Missing or invalid ''refreshToken'' field\", {}\n   114\n   115\t    normalized = {\n   116\t        \"claudeAiOauth\": {\n   117\t            \"accessToken\": access_token.strip(),\n   118\t            \"refreshToken\": refresh_token.strip(),\n   119\t            \"expiresAt\": data.get(\"expiresAt\", int((time.time() + 3600) * 1000)),\n   120\t            \"refreshTokenExpiresAt\": data.get(\"refreshTokenExpiresAt\", int((time.time() + 30 * 86400) * 1000)),\n   121\t            \"scopes\": data.get(\"scopes\", [\"user:read\", \"user:write\"]),\n   122\t            \"subscriptionType\": data.get(\"subscriptionType\", \"pro\"),\n   123\t            \"rateLimitTier\": data.get(\"rateLimitTier\", \"default_claude_ai\"),\n   124\t        }\n   125\t    }\n   126\n   127\t    return True, \"Valid OAuth credentials\", normalized\n   128\n   129\n   130\tdef import_oauth_file(source_path: Path | str, target_files: list[Path] | None = None) -> dict[str, Any]:\n   131\t    \"\"\"Импортирует OAuth credentials из файла в Windows и WSL2 с резервным копированием.\"\"\"\n   132\t    src = Path(source_path).resolve()\n   133\t    if not src.exists():\n   134\t        return {\"success\": False, \"error\": f\"Source file ''{src}'' does not exist\", \"synced\": []}\n   135\n   136\t    try:\n   137\t        with open(src, \"r\", encoding=\"utf-8\") as f:\n   138\t            raw_data = json.load(f)\n   139\t    except Exception as e:\n   140\t        return {\"success\": False, \"error\": f\"Failed to read JSON: {e}\", \"synced\": []}\n   141\n   142\t    is_valid, msg, normalized_data = validate_oauth_data(raw_data)\n   143\t    if not is_valid:\n   144\t        return {\"success\": False, \"error\": msg, \"synced\": []}\n   145\n   146\t    if target_files is None:\n   147\t        target_files = get_claude_credentials_files()\n   148\n   149\t    synced_paths: list[str] = []\n   150\t    ts = datetime.datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n   151\n   152\t    for target in target_files:\n   153\t        try:\n   154\t            target.parent.mkdir(parents=True, exist_ok=True)\n   155\t            if target.exists():\n   156\t                backup_path = target.with_suffix(f\".json.bak_{ts}\")\n   157\t                shutil.copy2(target, backup_path)\n   158\n   159\t            with open(target, \"w\", encoding=\"utf-8\") as f:\n   160\t                json.dump(normalized_data, f, indent=2, ensure_ascii=False)\n   161\n   162\t            synced_paths.append(str(target))\n   163\t        except Exception as e:\n   164\t            return {\"success\": False, \"error\": f\"Failed writing to {target}: {e}\", \"synced\": synced_paths}\n   165\n   166\t    # В WSL выставляем безопасные права доступа chmod 600\n   167\t    chmod_script = f\"\"\"\n   168\timport os\n   169\tp = ''/home/{WSL_USER}/.claude/.credentials.json''\n   170\tif os.path.exists(p):\n   171\t    os.chmod(p, 0o600)\n   172\t\"\"\"\n   173\t    run_wsl_python(chmod_script)\n   174\n   175\t    return {\n   176\t        \"success\": True,\n   177\t        \"message\": \"OAuth credentials successfully imported\",\n   178\t        \"synced\": synced_paths,\n   179\t        \"subscription_type\": normalized_data[\"claudeAiOauth\"].get(\"subscriptionType\"),\n   180\t    }\n   181\n   182\n   183\tdef get_oauth_status() -> dict[str, Any]:\n   184\t    \"\"\"Возвращает детальный статус текущей авторизации Claude.\"\"\"\n   185\t    cred_files = get_claude_credentials_files()\n   186\t    found_data = None\n   187\t    active_path = None\n   188\n   189\t    for f in cred_files:\n   190\t        if f.exists():\n   191\t            try:\n   192\t                with open(f, \"r\", encoding=\"utf-8\") as fp:\n   193\t                    d = json.load(fp)\n   194\t                    if \"claudeAiOauth\" in d:\n   195\t                        found_data = d[\"claudeAiOauth\"]\n   196\t                        active_path = f\n   197\t                        break\n   198\t            except Exception:\n   199\t                pass\n   200\n   201\t    if not found_data:\n   202\t        return {\n   203\t            \"authorized\": False,\n   204\t            \"message\": \"No .credentials.json found with valid claudeAiOauth\",\n   205\t            \"checked_paths\": [str(p) for p in cred_files],\n   206\t        }\n   207\n   208\t    now = time.time()\n   209\t    exp_ts = found_data.get(\"expiresAt\", 0) / 1000\n   210\t    r_exp_ts = found_data.get(\"refreshTokenExpiresAt\", 0) / 1000\n   211\n   212\t    access_valid = exp_ts > now\n   213\t    refresh_valid = r_exp_ts > now\n   214\n   215\t    return {\n   216\t        \"authorized\": refresh_valid or access_valid,\n   217\t        \"active_file\": str(active_path),\n   218\t        \"subscription_type\": found_data.get(\"subscriptionType\", \"unknown\"),\n   219\t        \"rate_limit_tier\": found_data.get(\"rateLimitTier\", \"unknown\"),\n   220\t        \"access_token_valid\": access_valid,\n   221\t        \"access_token_expires\": datetime.datetime.fromtimestamp(exp_ts).isoformat() if exp_ts else None,\n   222\t        \"refresh_token_valid\": refresh_valid,\n   223\t        \"refresh_token_expires\": datetime.datetime.fromtimestamp(r_exp_ts).isoformat() if r_exp_ts else None,\n   224\t        \"days_left\": round((r_exp_ts - now) / 86400, 1) if r_exp_ts else 0,\n   225\t    }\n   226\n   227\n   228\tdef ensure_claude_proxy_settings(\n   229\t    host: str = \"127.0.0.1\",\n   230\t    port: int = 1015,\n   231\t    killswitch: bool = True,\n   232\t) -> dict[str, Any]:\n   233\t    \"\"\"Синхронизирует сетевые переменные и защиту Killswitch в settings.json.\"\"\"\n   234\t    http_port = 10000 + int(port)\n   235\t    settings_files = get_claude_settings_files()\n   236\t    updated: list[str] = []\n   237\n   238\t    for filepath in settings_files:\n   239\t        try:\n   240\t            filepath.parent.mkdir(parents=True, exist_ok=True)\n   241\t            data: dict[str, Any] = {}\n   242\t            if filepath.exists():\n   243\t                try:\n   244\t                    with open(filepath, \"r\", encoding=\"utf-8\") as f:\n   245\t                        data = json.load(f)\n   246\t                        if not isinstance(data, dict):\n   247\t                            data = {}\n   248\t                except Exception:\n   249\t                    data = {}\n   250\n   251\t            if not isinstance(data.get(\"env\"), dict):\n   252\t                data[\"env\"] = {}\n   253\n   254\t            data[\"env\"][\"HTTPS_PROXY\"] = f\"http://{host}:{http_port}\"\n   255\t            data[\"env\"][\"HTTP_PROXY\"] = f\"http://{host}:{http_port}\"\n   256\t            data[\"env\"][\"ALL_PROXY\"] = f\"socks5h://{host}:{port}\"\n   257\t            data[\"env\"][\"DISABLE_AUTOUPDATER\"] = \"1\"\n   258\n   259\t            with open(filepath, \"w\", encoding=\"utf-8\") as f:\n   260\t                json.dump(data, f, indent=2, ensure_ascii=False)\n   261\n   262\t            updated.append(str(filepath))\n   263\t        except Exception as e:\n   264\t            return {\"success\": False, \"error\": f\"Failed writing to {filepath}: {e}\", \"updated\": updated}\n   265\n   266\t    return {\"success\": True, \"updated\": updated, \"proxy\": f\"{host}:{port}\", \"killswitch\": killswitch}\n   267\n   268\n   269\tdef patch_aionui_managed_resources(target_version: str = \"2.1.280\") -> dict[str, Any]:\n   270\t    \"\"\"Обновляет каталог встроенных ресурсов AionUi и manifest.json до версии 2.1.280+ через WSL Python.\"\"\"\n   271\t    script = f\"\"\"\n   272\timport json, os, shutil\n   273\n   274\tuser_home = ''/home/{WSL_USER}''\n   275\tres_dir = os.path.join(user_home, ''.local/share/aionui-web/aionui-web/bundled-aioncore/linux-x64/managed-resources'')\n   276\tmanifest_path = os.path.join(res_dir, ''manifest.json'')\n   277\n   278\tif not os.path.isfile(manifest_path):\n   279\t    print(\"ERROR:NO_MANIFEST\")\n   280\t    exit(1)\n   281\n   282\tsrc_bin = os.path.join(user_home, f''.local/share/claude/versions/{target_version}'')\n   283\tif not os.path.isfile(src_bin):\n   284\t    src_bin = os.path.join(user_home, ''.local/bin/claude'')\n   285\n   286\tif not os.path.isfile(src_bin):\n   287\t    print(\"ERROR:NO_SOURCE_BINARY\")\n   288\t    exit(2)\n   289\n   290\ttarget_dir = os.path.join(res_dir, f''cli/claude/{target_version}/linux-x64'')\n   291\tos.makedirs(target_dir, exist_ok=True)\n   292\ttarget_file = os.path.join(target_dir, ''claude'')\n   293\tif os.path.exists(target_file):\n   294\t    try:\n   295\t        os.unlink(target_file)\n   296\t    except Exception:\n   297\t        pass\n   298\tshutil.copy2(src_bin, target_file)\n   299\tos.chmod(target_file, 0o755)\n   300\n   301\tlegacy_dir = os.path.join(res_dir, ''cli/claude/2.1.215/linux-x64'')\n   302\tif os.path.isdir(legacy_dir):\n   303\t    legacy_file = os.path.join(legacy_dir, ''claude'')\n   304\t    if os.path.exists(legacy_file):\n   305\t        try:\n   306\t            os.unlink(legacy_file)\n   307\t        except Exception:\n   308\t            pass\n   309\t    shutil.copy2(src_bin, legacy_file)\n   310\t    os.chmod(legacy_file, 0o755)\n   311\n   312\twith open(manifest_path, ''r'', encoding=''utf-8'') as f:\n   313\t    m = json.load(f)\n   314\n   315\tfor cli in m.get(''clis'', []):\n   316\t    if cli.get(''name'') == ''claude'':\n   317\t        cli[''version''] = ''{target_version}''\n   318\t        cli[''root''] = f''cli/claude/{target_version}/linux-x64''\n   319\n   320\twith open(manifest_path, ''w'', encoding=''utf-8'') as f:\n   321\t    json.dump(m, f, indent=2)\n   322\n   323\tprint(\"STATUS:SUCCESS\")\n   324\t\"\"\"\n   325\t    code, stdout, stderr = run_wsl_python(script)\n   326\t    if code != 0 or \"STATUS:SUCCESS\" not in stdout:\n   327\t        err = stderr.strip() or stdout.strip()\n   328\t        return {\"success\": False, \"error\": f\"WSL Python execution failed ({code}): {err}\"}\n   329\n   330\t    return {\n   331\t        \"success\": True,\n   332\t        \"version\": target_version,\n   333\t        \"manifest_updated\": True,\n   334\t        \"message\": f\"AionUi managed-resources patched to {target_version}\",\n   335\t    }\n   336\n   337\n   338\tdef patch_aionui_database() -> dict[str, Any]:\n   339\t    \"\"\"Регистрирует команду ''claude'' для агента Claude Code в базе данных AionUi внутри WSL2.\"\"\"\n   340\t    script = f\"\"\"\n   341\timport sqlite3, os\n   342\n   343\tdb_path = ''/home/{WSL_USER}/.aionui-web/aionui-backend.db''\n   344\tif not os.path.isfile(db_path):\n   345\t    print(\"ERROR:NO_DB\")\n   346\t    exit(1)\n   347\n   348\tconn = sqlite3.connect(db_path, timeout=10)\n   349\tcur = conn.cursor()\n   350\tcur.execute(\"UPDATE agent_metadata SET command=''claude'', enabled=1 WHERE name=''Claude Code''\")\n   351\trows = cur.rowcount\n   352\tconn.commit()\n   353\tconn.close()\n   354\tprint(f\"ROWS:{{rows}}\")\n   355\t\"\"\"\n   356\t    code, stdout, stderr = run_wsl_python(script)\n   357\t    if code != 0:\n   358\t        return {\"success\": False, \"error\": f\"WSL SQLite failed ({code}): {stderr.strip()}\"}\n   359\n   360\t    rows = 0\n   361\t    for line in stdout.splitlines():\n   362\t        if line.startswith(\"ROWS:\"):\n   363\t            try:\n   364\t                rows = int(line.split(\":\")[1])\n   365\t            except Exception:\n   366\t                pass\n   367\n   368\t    return {\n   369\t        \"success\": True,\n   370\t        \"rows_affected\": rows,\n   371\t        \"database\": f\"/home/{WSL_USER}/.aionui-web/aionui-backend.db\",\n   372\t    }\n   373\n   374\n   375\tdef sync_all(oauth_file: Path | str | None = None) -> dict[str, Any]:\n   376\t    \"\"\"Выполняет полный цикл синхронизации: импорт OAuth, прокси, патч ресурсов AionUi и БД.\"\"\"\n   377\t    results: dict[str, Any] = {}\n   378\n   379\t    # 1. Импорт OAuth-файла (если передан)\n   380\t    if oauth_file:\n   381\t        results[\"oauth_import\"] = import_oauth_file(oauth_file)\n   382\t    else:\n   383\t        results[\"oauth_status\"] = get_oauth_status()\n   384\n   385\t    # 2. Сетевые прокси и Killswitch\n   386\t    results[\"proxy_settings\"] = ensure_claude_proxy_settings()\n   387\n   388\t    # 3. Патч ресурсов AionUi (версия 2.1.280)\n   389\t    results[\"resources_patch\"] = patch_aionui_managed_resources()\n   390\n   391\t    # 4. Патч базы данных AionUi\n   392\t    results[\"db_patch\"] = patch_aionui_database()\n   393\n   394\t    # Общий успех\n   395\t    all_ok = all(\n   396\t        v.get(\"success\", True) if isinstance(v, dict) else True\n   397\t        for k, v in results.items()\n   398\t    )\n   399\t    results[\"all_success\"] = all_ok\n   400\t    return results\n   401\n   402\n   403\tdef main() -> int:\n   404\t    \"\"\"Точка входа CLI.\"\"\"\n   405\t    parser = argparse.ArgumentParser(description=\"AionUi Claude Code Integration Bridge\")\n   406\t    parser.add_argument(\"--status\", action=\"store_true\", help=\"Show current OAuth and proxy status\")\n   407\t    parser.add_argument(\"--import-oauth\", type=str, help=\"Path to new OAuth .credentials.json or token file\")\n   408\t    parser.add_argument(\"--patch-aionui\", action=\"store_true\", help=\"Patch AionUi resources and database\")\n   409\t    parser.add_argument(\"--sync-all\", nargs=\"?\", const=\"\", help=\"Run full sync (optionally passing OAuth file)\")\n   410\n   411\t    args = parser.parse_args()\n   412\n   413\t    if args.status:\n   414\t        st = get_oauth_status()\n   415\t        print(\"\\n=== CLAUDE CODE OAUTH STATUS ===\")\n   416\t        print(f\"Authorized:       {''✅ YES'' if st.get(''authorized'') else ''❌ NO''}\")\n   417\t        print(f\"Subscription:     {st.get(''subscription_type'', ''N/A'').upper()}\")\n   418\t        print(f\"Refresh Expires:  {st.get(''refresh_token_expires'', ''N/A'')} ({st.get(''days_left'', 0)} days left)\")\n   419\t        print(f\"Active File:      {st.get(''active_file'', ''N/A'')}\")\n   420\t        return 0\n   421\n   422\t    if args.import_oauth:\n   423\t        res = import_oauth_file(args.import_oauth)\n   424\t        print(\"\\n=== OAUTH IMPORT RESULT ===\")\n   425\t        print(json.dumps(res, indent=2, ensure_ascii=False))\n   426\t        return 0 if res.get(\"success\") else 1\n   427\n   428\t    if args.patch_aionui:\n   429\t        res_p = patch_aionui_managed_resources()\n   430\t        db_p = patch_aionui_database()\n   431\t        print(\"\\n=== AIONUI PATCH RESULT ===\")\n   432\t        print(\"Resources:\", json.dumps(res_p, indent=2))\n   433\t        print(\"Database: \", json.dumps(db_p, indent=2))\n   434\t        return 0 if (res_p.get(\"success\") and db_p.get(\"success\")) else 1\n   435\n   436\t    if args.sync_all is not None:\n   437\t        oauth_f = args.sync_all if args.sync_all else None\n   438\t        res = sync_all(oauth_f)\n   439\t        print(\"\\n=== FULL AIONUI CLAUDE SYNC RESULT ===\")\n   440\t        print(json.dumps(res, indent=2, ensure_ascii=False))\n   441\t        return 0 if res.get(\"all_success\") else 1\n   442\n   443\t    parser.print_help()\n   444\t    return 0\n   445\n   446\n   447\tif __name__ == \"__main__\":\n   448\t    sys.exit(main())"}','left','finish',0,1790226209219,NULL);
