INSERT INTO "messages" VALUES('aionrs-call_191962','96eb91fc','aionrs-call_191962','tool_call','{"call_id":"aionrs-call_191962","name":"ExecCommand","args":{"cmd":"gemini-oauth --help"},"status":"completed","input":{"cmd":"gemini-oauth --help"},"output":"Exit code: 0\nSTDOUT:\nusage: gemini-oauth [-h]\n                    {list,next,failover-proxy,switch,add,rename,guard} ...\n\nGoogle Gemini OAuth Profile Manager\n\npositional arguments:\n  {list,next,failover-proxy,switch,add,rename,guard}\n    list                Список всех OAuth профилей и портов\n    next                Переключить на следующий аккаунт по кругу (Round-\n                        Robin)\n    failover-proxy      Автоподбор резервного SOCKS5-прокси (приоритет той же\n                        страны)\n    switch              Переключить активный аккаунт\n    add                 Добавить новый Google аккаунт\n    rename              Переименовать Google аккаунт\n    guard               Управление службой автосмены при лимитах\n                        (start/stop/status)\n\noptions:\n  -h, --help            show this help message and exit\n\nSTDERR:"}','left','finish',0,1790227181878,NULL);
