INSERT INTO "messages" VALUES('aionrs-call_289731','96eb91fc','aionrs-call_289731','tool_call','{"call_id":"aionrs-call_289731","name":"Read","args":{"file_path":"/mnt/d/My files/herdrControlGui/config_app.py","limit":5000,"offset":1500},"status":"completed","input":{"file_path":"/mnt/d/My files/herdrControlGui/config_app.py","limit":5000,"offset":1500},"output":"  1501\t            # Правая колонка: Кнопки\n  1502\t            right = tk.Frame(c_in, bg=C[\"card\"])\n  1503\t            right.pack(side=\"right\")\n  1504\n  1505\t            # Кнопка ручного выбора SOCKS5 прокси для данного аккаунта\n  1506\t            proxy_choices = proxy_manager.get_proxy_choices()\n  1507\t            proxy_menu_btn = tk.Menubutton(\n  1508\t                right, text=f\"🛡️ Proxy {proxy_num} ▾\", font=FONT_MAIN,\n  1509\t                bg=C[\"card_inner\"], fg=C[\"accent_blue\"], activebackground=C[\"border\"],\n  1510\t                bd=0, padx=8, pady=4, cursor=\"hand2\", relief=\"flat\"\n  1511\t            )\n  1512\t            p_menu = tk.Menu(\n  1513\t                proxy_menu_btn, tearoff=0,\n  1514\t                bg=C[\"card_inner\"], fg=C[\"fg\"],\n  1515\t                activebackground=C[\"accent_blue\"], activeforeground=\"#11111b\"\n  1516\t            )\n  1517\t            for choice in proxy_choices:\n  1518\t                c_port = choice[\"port\"]\n  1519\t                c_label = choice[\"display\"]\n  1520\t                p_menu.add_command(\n  1521\t                    label=c_label,\n  1522\t                    command=lambda name=p_name, pt=c_port: self.on_select_account_proxy(name, pt)\n  1523\t                )\n  1524\t            proxy_menu_btn.config(menu=p_menu)\n  1525\t            proxy_menu_btn.pack(side=\"left\", padx=(0, 6))\n  1526\n  1527\t            if not is_active:\n  1528\t                btn_sw = tk.Button(\n  1529\t                    right, text=\"⚡ Активировать\", font=FONT_BOLD,\n  1530\t                    bg=C[\"accent_blue\"], fg=\"#11111b\", activebackground=\"#b4befe\",\n  1531\t                    bd=0, padx=10, pady=4, cursor=\"hand2\",\n  1532\t                    command=lambda name=p_name: self.on_switch_gemini_profile(name)\n  1533\t                )\n  1534\t                btn_sw.pack(side=\"left\", padx=(0, 6))\n  1535\n  1536\t            btn_test = tk.Button(\n  1537\t                right, text=\"🔍 Проверить\", font=FONT_MAIN,\n  1538\t                bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  1539\t                bd=0, padx=8, pady=4, cursor=\"hand2\",\n  1540\t                command=lambda name=p_name: self.on_test_gemini_token(name)\n  1541\t            )\n  1542\t            btn_test.pack(side=\"left\", padx=(0, 6))\n  1543\n  1544\t            btn_rename = tk.Button(\n  1545\t                right, text=\"✏️\", font=FONT_MAIN,\n  1546\t                bg=C[\"card_inner\"], fg=C[\"accent_blue\"], activebackground=C[\"border\"],\n  1547\t                bd=0, padx=6, pady=4, cursor=\"hand2\",\n  1548\t                command=lambda name=p_name: self.on_rename_gemini_profile(name)\n  1549\t            )\n  1550\t            btn_rename.pack(side=\"left\", padx=(0, 6 if not is_active and len(self.gemini_profiles) > 1 else 0))\n  1551\n  1552\t            if not is_active and len(self.gemini_profiles) > 1:\n  1553\t                btn_del = tk.Button(\n  1554\t                    right, text=\"🗑️\", font=FONT_MAIN,\n  1555\t                    bg=C[\"card_inner\"], fg=C[\"red\"], activebackground=C[\"border\"],\n  1556\t                    bd=0, padx=6, pady=4, cursor=\"hand2\",\n  1557\t                    command=lambda name=p_name: self.on_delete_gemini_profile(name)\n  1558\t                )\n  1559\t                btn_del.pack(side=\"left\")\n  1560\n  1561\t    def on_change_gemini_position(self, profile_name: str, new_position: int | None = None):\n  1562\t        \"\"\"Смена номера профиля: профиль встаёт на новое место и получает порт своего номера.\"\"\"\n  1563\t        total = len(self.gemini_profiles)\n  1564\t        if new_position is None:\n  1565\t            curr = next((p.get(\"position\") for p in self.gemini_profiles if p.get(\"profile_name\") == profile_name), 1)\n  1566\t            new_position = simpledialog.askinteger(\n  1567\t                t(\"dlg_gemini_position_title\"),\n  1568\t                t(\"dlg_gemini_position_prompt\", profile=profile_name, total=total),\n  1569\t                initialvalue=curr, minvalue=1, maxvalue=max(total, 1), parent=self\n  1570\t            )\n  1571\t            if not new_position or new_position == curr:\n  1572\t                return\n  1573\t        ok, msg = gemini_manager.set_profile_position(profile_name, new_position)\n  1574\t        if not ok:\n  1575\t            messagebox.showerror(t(\"error\"), msg)\n  1576\t            return\n  1577\t        self.load_gemini_profiles_data()\n  1578\t        self.render_gemini_page()\n  1579\t        self.refresh_routes_async()\n  1580\n  1581\t    def on_rename_gemini_profile(self, profile_name: str):\n  1582\t        \"\"\"Переименование аккаунта/профиля.\"\"\"\n  1583\t        new_name = simpledialog.askstring(\n  1584\t            \"Переименовать аккаунт\",\n  1585\t            f\"Текущее имя профиля: {profile_name}\\n\\nВведите новое имя профиля:\",\n  1586\t            initialvalue=profile_name,\n  1587\t            parent=self\n  1588\t        )\n  1589\t        if not new_name or new_name.strip() == profile_name:\n  1590\t            return\n  1591\n  1592\t        ok, msg = gemini_manager.rename_profile(profile_name, new_name.strip())\n  1593\t        if ok:\n  1594\t            self.load_gemini_profiles_data()\n  1595\t            self.render_gemini_page()\n  1596\t            self.render_strategy_page()\n  1597\t            self.refresh_routes_async()\n  1598\t            messagebox.showinfo(\"Переименование\", msg)\n  1599\t        else:\n  1600\t            messagebox.showerror(\"Ошибка\", msg)\n  1601\n  1602\t    def on_switch_gemini_profile(self, profile_name: str):\n  1603\t        \"\"\"Быстрое переключение активного профиля в 1 клик.\"\"\"\n  1604\t        ok, msg = gemini_manager.switch_profile(profile_name)\n  1605\t        if ok:\n  1606\t            self.load_gemini_profiles_data()\n  1607\t            self.render_gemini_page()\n  1608\t            # Обновляем также роутер\n  1609\t            self.refresh_routes_async()\n  1610\t            messagebox.showinfo(\"Переключение\", msg)\n  1611\t        else:\n  1612\t            messagebox.showerror(\"Ошибка\", msg)\n  1613\n  1614\t    def on_test_gemini_token(self, profile_name: str):\n  1615\t        \"\"\"Онлайн-проверка токена в Google API через персональный порт.\"\"\"\n  1616\t        def worker():\n  1617\t            res = gemini_manager.check_token_live(profile_name)\n  1618\t            def show_res():\n  1619\t                port = res.get(\"port\", gemini_manager.BASE_SOCKS5_PORT)\n  1620\t                if res.get(\"valid\"):\n  1621\t                    messagebox.showinfo(\n  1622\t                        \"Google OAuth2 Валидация\",\n  1623\t                        f\"✓ Токен активен и полностью валиден в Google API!\\n\\n\"\n  1624\t                        f\"Google ID: {res.get(''email'')}\\n\"\n  1625\t                        f\"Выделенный порт: SOCKS5 127.0.0.1:{port}\\n\"\n  1626\t                        f\"Доступ: Полная квота Google AI Pro / Gemini Advanced\"\n  1627\t                    )\n  1628\t                else:\n  1629\t                    messagebox.showwarning(\n  1630\t                        \"Google OAuth2 Валидация\",\n  1631\t                        f\"Токен недоступен или порт не отвечает:\\n{res.get(''error'')}\\n\\n\"\n  1632\t                        f\"Проверьте, что в Xray запущен inbound на порту {port}.\"\n  1633\t                    )\n  1634\t            self.after(0, show_res)\n  1635\n  1636\t        threading.Thread(target=worker, daemon=True).start()\n  1637\n  1638\t    def on_add_google_account(self):\n  1639\t        \"\"\"Запуск терминала для входа в новый аккаунт Google.\"\"\"\n  1640\t        existing_names = {p.get(\"profile_name\") for p in self.gemini_profiles}\n  1641\t        idx = 1\n  1642\t        while f\"account-{idx}\" in existing_names:\n  1643\t            idx += 1\n  1644\t        suggested_name = f\"account-{idx}\"\n  1645\t        next_port = gemini_manager._calculate_default_sequential_port(suggested_name)\n  1646\t        p_name = simpledialog.askstring(\n  1647\t            \"Новый Google аккаунт\",\n  1648\t            f\"Будет привязан новый порт: SOCKS5 127.0.0.1:{next_port}\\n\\nВведите имя профиля:\",\n  1649\t            initialvalue=suggested_name,\n  1650\t            parent=self\n  1651\t        )\n  1652\t        if not p_name:\n  1653\t            return\n  1654\n  1655\t        p_name = p_name.strip()\n  1656\t        # Пересчитываем порт для фактического имени профиля\n  1657\t        actual_port = gemini_manager._calculate_default_sequential_port(p_name)\n  1658\t        # Резервируем порт заранее, чтобы gemini-oauth в WSL использовал именно его\n  1659\t        gemini_manager.reserve_new_profile_port(p_name, actual_port)\n  1660\n  1661\t        launched = gemini_manager.launch_add_account_terminal(p_name)\n  1662\t        if launched:\n  1663\t            messagebox.showinfo(\n  1664\t                \"Авторизация в браузере\",\n  1665\t                f\"Открыт терминал авторизации для ''{p_name}''.\\nВыделенный порт: SOCKS5 :{actual_port}\\n\\n\"\n  1666\t                f\"1. Перейдите по ссылке в появившемся окне.\\n\"\n  1667\t                f\"2. Войдите в нужный аккаунт Google в браузере.\\n\"\n  1668\t                f\"3. После завершения нажмите ''Обновить профили'' здесь.\"\n  1669\t            )\n  1670\t        else:\n  1671\t            messagebox.showerror(\"Ошибка\", \"Не удалось запустить терминал WSL.\")\n  1672\n  1673\t    def on_delete_gemini_profile(self, profile_name: str):\n  1674\t        \"\"\"Удаление резервного профиля.\"\"\"\n  1675\t        if messagebox.askyesno(\"Удаление профиля\", f\"Удалить сохраненный профиль ''{profile_name}''?\"):\n  1676\t            ok, msg = gemini_manager.delete_profile(profile_name)\n  1677\t            if ok:\n  1678\t                self.load_gemini_profiles_data()\n  1679\t                self.render_gemini_page()\n  1680\t            else:\n  1681\t                messagebox.showerror(\"Ошибка\", msg)\n  1682\n  1683\t    def on_select_account_proxy(self, profile_name: str, port: int):\n  1684\t        \"\"\"Ручной выбор SOCKS5-прокси для конкретного профиля.\"\"\"\n  1685\t        ok, msg = gemini_manager.set_profile_manual_port(profile_name, port)\n  1686\t        if ok:\n  1687\t            self.load_gemini_profiles_data()\n  1688\t            self.render_gemini_page()\n  1689\t            self.refresh_routes_async()\n  1690\t            try:\n  1691\t                email = next((p.get(\"email\") for p in self.gemini_profiles if p.get(\"profile_name\") == profile_name), profile_name)\n  1692\t                curr_proxies = proxy_manager.load_proxies()\n  1693\t                p_obj = next((p for p in curr_proxies if p.get(\"port\") == port), None)\n  1694\t                strategy_manager.log_event(\n  1695\t                    account_email=email,\n  1696\t                    profile_name=profile_name,\n  1697\t                    port=port,\n  1698\t                    ip=p_obj.get(\"ip\", \"-\") if p_obj else \"-\",\n  1699\t                    country=p_obj.get(\"country\", \"undefined\") if p_obj else \"undefined\",\n  1700\t                    event=\"manual_proxy_select\",\n  1701\t                    note=f\"Пользователь вручную назначил SOCKS5 :{port}\"\n  1702\t                )\n  1703\t            except Exception:\n  1704\t                pass\n  1705\t            messagebox.showinfo(t(\"gemini_title\"), msg)\n  1706\t        else:\n  1707\t            messagebox.showerror(t(\"app_name\"), msg)\n  1708\n  1709\t    def on_reset_gemini_proxies_order(self):\n  1710\t        \"\"\"Сброс ручных привязок и автоматическая расстановка прокси строго по порядку.\"\"\"\n  1711\t        ok, msg = gemini_manager.reset_all_profiles_to_sequential()\n  1712\t        if ok:\n  1713\t            self.load_gemini_profiles_data()\n  1714\t            self.render_gemini_page()\n  1715\t            self.refresh_routes_async()\n  1716\t            messagebox.showinfo(t(\"msg_proxies_reset_title\"), msg)\n  1717\t        else:\n  1718\t            messagebox.showerror(t(\"app_name\"), msg)\n  1719\n  1720\t    def on_toggle_guard(self):\n  1721\t        \"\"\"Включение / выключение службы автосмены при лимитах.\"\"\"\n  1722\t        if gemini_manager.is_guard_running():\n  1723\t            ok, msg = gemini_manager.stop_guard()\n  1724\t            if ok:\n  1725\t                self.render_gemini_page()\n  1726\t                messagebox.showinfo(\"Автосмена\", \"Служба автосмены аккаунтов остановлена.\")\n  1727\t        else:\n  1728\t            ok, msg = gemini_manager.start_guard()\n  1729\t            if ok:\n  1730\t                self.render_gemini_page()\n  1731\t                messagebox.showinfo(\n  1732\t                    \"Автосмена\",\n  1733\t                    \"Служба автосмены активна!\\nПри получении ошибки 429 (Resource Exhausted) система автоматически переключит аккаунт и SOCKS5-порт.\"\n  1734\t                )\n  1735\n  1736\t    def on_rotate_next_profile(self):\n  1737\t        \"\"\"Ручная ротация на следующий профиль по кругу (Round-Robin).\"\"\"\n  1738\t        ok, msg = gemini_manager.switch_next_profile()\n  1739\t        if ok:\n  1740\t            self.load_gemini_profiles_data()\n  1741\t            self.render_gemini_page()\n  1742\t            self.refresh_routes_async()\n  1743\t            messagebox.showinfo(\"Ротация\", msg)\n  1744\t        else:\n  1745\t            messagebox.showwarning(\"Ротация\", msg)\n  1746\n  1747\t    def refresh_gemini_profiles_async(self):\n  1748\t        \"\"\"Обновление списка профилей.\"\"\"\n  1749\t        def worker():\n  1750\t            self.load_gemini_profiles_data()\n  1751\t            self.after(0, self.render_gemini_page)\n  1752\n  1753\t        threading.Thread(target=worker, daemon=True).start()\n  1754\n  1755\t    # =========================================================================\n  1756\t    # СТРАНИЦА: CLAUDE OAUTH\n  1757\t    # =========================================================================\n  1758\t    def _build_page_claude_oauth(self, parent: tk.Frame):\n  1759\t        self.claude_profiles = []\n  1760\t        self.claude_active_status = {}\n  1761\n  1762\t        c_top = tk.Frame(parent, bg=C[\"bg\"])\n  1763\t        c_top.pack(fill=\"x\", pady=(0, 10))\n  1764\n  1765\t        title_frame = tk.Frame(c_top, bg=C[\"bg\"])\n  1766\t        title_frame.pack(side=\"left\")\n  1767\n  1768\t        tk.Label(\n  1769\t            title_frame, text=t(\"claude_oauth_title\"), font=FONT_TITLE,\n  1770\t            fg=C[\"accent_peach\"], bg=C[\"bg\"]\n  1771\t        ).pack(anchor=\"w\")\n  1772\n  1773\t        tk.Label(\n  1774\t            title_frame, text=t(\"claude_oauth_desc\"),\n  1775\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"bg\"]\n  1776\t        ).pack(anchor=\"w\")\n  1777\n  1778\t        btn_box = tk.Frame(c_top, bg=C[\"bg\"])\n  1779\t        btn_box.pack(side=\"right\")\n  1780\n  1781\t        tk.Button(\n  1782\t            btn_box, text=t(\"btn_claude_refresh_profiles\"), font=FONT_BOLD,\n  1783\t            bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  1784\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  1785\t            command=self.refresh_claude_profiles_async\n  1786\t        ).pack(side=\"left\", padx=(0, 8))\n  1787\n  1788\t        tk.Button(\n  1789\t            btn_box, text=t(\"btn_claude_add_account\"), font=FONT_BOLD,\n  1790\t            bg=C[\"accent_peach\"], fg=\"#11111b\", activebackground=\"#f5c2e7\",\n  1791\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  1792\t            command=self.on_add_claude_account\n  1793\t        ).pack(side=\"left\")\n  1794\n  1795\t        # Карточка прокси (строго Anthropic Claude Proxy со страницы Routes)\n  1796\t        px_card = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  1797\t        px_card.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  1798\t        px_card.pack(fill=\"x\", pady=(0, 12))\n  1799\t        px_in = tk.Frame(px_card, bg=C[\"card\"])\n  1800\t        px_in.pack(fill=\"both\", expand=True, padx=16, pady=10)\n  1801\t        self.claude_oauth_proxy_lbl = tk.Label(\n  1802\t            px_in, text=\"...\", font=FONT_BOLD, fg=C[\"fg\"], bg=C[\"card\"], justify=\"left\"\n  1803\t        )\n  1804\t        self.claude_oauth_proxy_lbl.pack(anchor=\"w\")\n  1805\t        tk.Label(\n  1806\t            px_in, text=t(\"claude_oauth_proxy_note\"),\n  1807\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"card\"], justify=\"left\"\n  1808\t        ).pack(anchor=\"w\", pady=(2, 0))\n  1809\n  1810\t        # Карточка активного аккаунта\n  1811\t        sp = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  1812\t        sp.configure(highlightbackground=C[\"accent_peach\"], highlightthickness=1)\n  1813\t        sp.pack(fill=\"x\", pady=(0, 12))\n  1814\t        sp_in = tk.Frame(sp, bg=C[\"card\"])\n  1815\t        sp_in.pack(fill=\"both\", expand=True, padx=16, pady=12)\n  1816\n  1817\t        sp_head = tk.Frame(sp_in, bg=C[\"card\"])\n  1818\t        sp_head.pack(fill=\"x\")\n  1819\t        tk.Label(\n  1820\t            sp_head, text=t(\"lbl_active_claude_account\"),\n  1821\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"card\"]\n  1822\t        ).pack(side=\"left\")\n  1823\t        self.claude_save_active_btn = tk.Button(\n  1824\t            sp_head, text=t(\"btn_claude_save_active\"), font=FONT_BOLD,\n  1825\t            bg=C[\"card_inner\"], fg=C[\"accent_peach\"], activebackground=C[\"border\"],\n  1826\t            bd=0, padx=10, pady=2, cursor=\"hand2\",\n  1827\t            command=self.on_save_active_claude_account\n  1828\t        )\n  1829\t        self.claude_spotlight_badge = tk.Label(\n  1830\t            sp_head, text=\"...\", font=FONT_BOLD, bg=C[\"border\"], fg=C[\"fg\"], padx=8, pady=2\n  1831\t        )\n  1832\t        self.claude_spotlight_badge.pack(side=\"right\")\n  1833\n  1834\t        self.claude_spotlight_email_lbl = tk.Label(\n  1835\t            sp_in, text=t(\"claude_loading\"), font=FONT_APP_TITLE, fg=C[\"fg\"], bg=C[\"card\"]\n  1836\t        )\n  1837\t        self.claude_spotlight_email_lbl.pack(anchor=\"w\", pady=(4, 2))\n  1838\t        self.claude_spotlight_info_lbl = tk.Label(\n  1839\t            sp_in, text=\"\", font=FONT_MAIN, fg=C[\"subtext\"], bg=C[\"card\"], justify=\"left\"\n  1840\t        )\n  1841\t        self.claude_spotlight_info_lbl.pack(anchor=\"w\")\n  1842\n  1843\t        tk.Label(\n  1844\t            parent, text=t(\"lbl_claude_saved_profiles\"),\n  1845\t            font=FONT_BOLD, fg=C[\"fg\"], bg=C[\"bg\"]\n  1846\t        ).pack(anchor=\"w\", pady=(4, 6))\n  1847\n  1848\t        self.claude_cards_container = tk.Frame(parent, bg=C[\"bg\"])\n  1849\t        self.claude_cards_container.pack(fill=\"both\", expand=True)\n  1850\n  1851\t    def load_claude_profiles_data(self):\n  1852\t        \"\"\"Загрузка профилей Claude OAuth из WSL2.\"\"\"\n  1853\t        try:\n  1854\t            self.claude_profiles = claude_oauth_manager.list_profiles()\n  1855\t            self.claude_active_status = claude_oauth_manager.get_active_status()\n  1856\t        except Exception as e:\n  1857\t            self.claude_profiles = []\n  1858\t            self.claude_active_status = {\"exists\": False, \"email\": f\"Ошибка: {e}\"}\n  1859\t        try:\n  1860\t            self.claude_proxy_online = claude_oauth_manager.is_claude_proxy_online(timeout=0.5)\n  1861\t        except Exception:\n  1862\t            self.claude_proxy_online = False\n  1863\n  1864\t    def refresh_claude_profiles_async(self):\n  1865\t        def worker():\n  1866\t            self.load_claude_profiles_data()\n  1867\t            self.after(0, self.render_claude_oauth_page)\n  1868\n  1869\t        threading.Thread(target=worker, daemon=True).start()\n  1870\n  1871\t    def render_claude_oauth_page(self):\n  1872\t        \"\"\"Отрисовка вкладки Claude OAuth.\"\"\"\n  1873\t        px = claude_oauth_manager.get_claude_oauth_proxy()\n  1874\t        online = getattr(self, \"claude_proxy_online\", False)\n  1875\t        self.claude_oauth_proxy_lbl.config(\n  1876\t            text=t(\"claude_oauth_proxy_line\", host=px[\"host\"], port=px[\"port\"], http_port=px[\"http_port\"],\n  1877\t                   status=t(\"status_online\") if online else t(\"status_offline\")),\n  1878\t            fg=C[\"green\"] if online else C[\"red\"],\n  1879\t        )\n  1880\n  1881\t        st = self.claude_active_status or {}\n  1882\t        if st.get(\"exists\") and st.get(\"expires_at\"):\n  1883\t            self.claude_spotlight_email_lbl.config(text=f\"🟢 {st.get(''email'')} ({st.get(''name'')})\")\n  1884\t            self.claude_spotlight_info_lbl.config(\n  1885\t                text=t(\"claude_token_line\", expiry=st.get(\"expiry_text\"), refresh=st.get(\"refresh_expiry_text\"),\n  1886\t                       sub=st.get(\"subscription\")),\n  1887\t                fg=C[\"yellow\"] if st.get(\"is_expired\") else C[\"green\"],\n  1888\t            )\n  1889\t            if st.get(\"saved\"):\n  1890\t                self.claude_spotlight_badge.config(text=f\"🟢 {st.get(''profile_name'')}\", bg=C[\"green\"], fg=\"#11111b\")\n  1891\t                self.claude_save_active_btn.pack_forget()\n  1892\t            else:\n  1893\t                self.claude_spotlight_badge.config(text=t(\"badge_claude_not_saved\"), bg=C[\"yellow\"], fg=\"#11111b\")\n  1894\t                self.claude_save_active_btn.pack(side=\"right\", padx=(0, 8))\n  1895\t        else:\n  1896\t            self.claude_spotlight_email_lbl.config(text=t(\"no_active_claude\"))\n  1897\t            self.claude_spotlight_info_lbl.config(text=t(\"click_login_claude\"), fg=C[\"subtext\"])\n  1898\t            self.claude_spotlight_badge.config(text=\"⚪ \" + t(\"not_authorized\"), bg=C[\"border\"], fg=C[\"fg\"])\n  1899\t            self.claude_save_active_btn.pack_forget()\n  1900\n  1901\t        for widget in self.claude_cards_container.winfo_children():\n  1902\t            widget.destroy()\n  1903\n  1904\t        if not self.claude_profiles:\n  1905\t            empty = tk.Frame(self.claude_cards_container, bg=C[\"card\"], bd=1, relief=\"solid\")\n  1906\t            empty.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  1907\t            empty.pack(fill=\"x\", pady=8)\n  1908\t            tk.Label(\n  1909\t                empty, text=t(\"claude_no_profiles\"),\n  1910\t                font=FONT_MAIN, fg=C[\"subtext\"], bg=C[\"card\"], justify=\"center\", pady=24\n  1911\t            ).pack(fill=\"both\")\n  1912\t            return\n  1913\n  1914\t        for prof in self.claude_profiles:\n  1915\t            is_active = prof.get(\"is_active\", False)\n  1916\t            p_name = prof.get(\"profile_name\", \"unknown\")\n  1917\n  1918\t            card = tk.Frame(self.claude_cards_container, bg=C[\"card\"], bd=1, relief=\"solid\")\n  1919\t            card.configure(highlightbackground=C[\"accent_peach\"] if is_active else C[\"border\"], highlightthickness=1)\n  1920\t            card.pack(fill=\"x\", pady=(0, 8))\n  1921\t            c_in = tk.Frame(card, bg=C[\"card\"])\n  1922\t            c_in.pack(fill=\"both\", expand=True, padx=14, pady=10)\n  1923\n  1924\t            left = tk.Frame(c_in, bg=C[\"card\"])\n  1925\t            left.pack(side=\"left\", fill=\"both\", expand=True)\n  1926\n  1927\t            t_line = tk.Frame(left, bg=C[\"card\"])\n  1928\t            t_line.pack(fill=\"x\")\n  1929\t            tk.Label(t_line, text=p_name, font=FONT_TITLE, fg=C[\"fg\"], bg=C[\"card\"]).pack(side=\"left\")\n  1930\t            if is_active:\n  1931\t                tk.Label(t_line, text=f\" {t(''btn_active'')} \", font=FONT_SUB,\n  1932\t                         fg=\"#11111b\", bg=C[\"green\"], padx=6, pady=1).pack(side=\"left\", padx=(8, 0))\n  1933\t            else:\n  1934\t                tk.Label(t_line, text=f\" {t(''badge_standby'')} \", font=FONT_SUB,\n  1935\t                         fg=C[\"subtext\"], bg=C[\"card_inner\"], padx=6, pady=1).pack(side=\"left\", padx=(8, 0))\n  1936\t            tk.Label(t_line, text=f\" Claude Proxy (:{prof.get(''proxy_port'')}) \", font=FONT_SUB,\n  1937\t                     fg=C[\"accent_peach\"], bg=C[\"tag_bg\"], padx=6, pady=1).pack(side=\"left\", padx=(8, 0))\n  1938\t            tk.Label(t_line, text=f\" {prof.get(''subscription'', ''-'')} \", font=FONT_SUB,\n  1939\t                     fg=C[\"accent_mauve\"], bg=C[\"tag_bg\"], padx=6, pady=1).pack(side=\"left\", padx=(8, 0))\n  1940\n  1941\t            tk.Label(\n  1942\t                left, text=f\"Claude ID: {prof.get(''email'')} ({prof.get(''name'')})\",\n  1943\t                font=FONT_MAIN, fg=C[\"subtext\"], bg=C[\"card\"]\n  1944\t            ).pack(anchor=\"w\", pady=(3, 0))\n  1945\n  1946\t            if not prof.get(\"exists\"):\n  1947\t                token_text = t(\"claude_login_pending\")\n  1948\t                token_color = C[\"yellow\"]\n  1949\t            else:\n  1950\t                token_text = t(\"claude_token_line\", expiry=prof.get(\"expiry_text\"),\n  1951\t                               refresh=prof.get(\"refresh_expiry_text\"), sub=prof.get(\"subscription\"))\n  1952\t                token_color = C[\"red\"] if prof.get(\"is_expired\") else C[\"subtext\"]\n  1953\t            tk.Label(left, text=token_text, font=FONT_MAIN, fg=token_color, bg=C[\"card\"]).pack(anchor=\"w\")\n  1954\n  1955\t            right = tk.Frame(c_in, bg=C[\"card\"])\n  1956\t            right.pack(side=\"right\")\n  1957\n  1958\t            if not is_active and prof.get(\"exists\"):\n  1959\t                tk.Button(\n  1960\t                    right, text=t(\"btn_activate\"), font=FONT_BOLD,\n  1961\t                    bg=C[\"accent_peach\"], fg=\"#11111b\", activebackground=\"#f5c2e7\",\n  1962\t                    bd=0, padx=10, pady=4, cursor=\"hand2\",\n  1963\t                    command=lambda name=p_name: self.on_switch_claude_profile(name)\n  1964\t                ).pack(side=\"left\", padx=(0, 6))\n  1965\n  1966\t            if prof.get(\"exists\"):\n  1967\t                tk.Button(\n  1968\t                    right, text=t(\"btn_check\"), font=FONT_MAIN,\n  1969\t                    bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  1970\t                    bd=0, padx=8, pady=4, cursor=\"hand2\",\n  1971\t                    command=lambda name=p_name: self.on_test_claude_token(name)\n  1972\t                ).pack(side=\"left\", padx=(0, 6))\n  1973\n  1974\t            tk.Button(\n  1975\t                right, text=\"✏️\", font=FONT_MAIN,\n  1976\t                bg=C[\"card_inner\"], fg=C[\"accent_blue\"], activebackground=C[\"border\"],\n  1977\t                bd=0, padx=6, pady=4, cursor=\"hand2\",\n  1978\t                command=lambda name=p_name: self.on_rename_claude_profile(name)\n  1979\t            ).pack(side=\"left\", padx=(0, 6))\n  1980\n  1981\t            if not is_active:\n  1982\t                tk.Button(\n  1983\t                    right, text=\"🗑️\", font=FONT_MAIN,\n  1984\t                    bg=C[\"card_inner\"], fg=C[\"red\"], activebackground=C[\"border\"],\n  1985\t                    bd=0, padx=6, pady=4, cursor=\"hand2\",\n  1986\t                    command=lambda name=p_name: self.on_delete_claude_profile(name)\n  1987\t                ).pack(side=\"left\")\n  1988\n  1989\t    def on_add_claude_account(self):\n  1990\t        \"\"\"Вход в новый аккаунт Claude через терминал WSL (строго через Claude Proxy).\"\"\"\n  1991\t        px = claude_oauth_manager.get_claude_oauth_proxy()\n  1992\t        p_name = simpledialog.askstring(\n  1993\t            t(\"dlg_claude_new_account\"),\n  1994\t            t(\"dlg_claude_new_account_prompt\", host=px[\"host\"], port=px[\"port\"], http_port=px[\"http_port\"]),\n  1995\t            initialvalue=claude_oauth_manager.suggest_profile_name(),\n  1996\t            parent=self\n  1997\t        )\n  1998\t        if not p_name:\n  1999\t            return\n  2000\t        ok, msg = claude_oauth_manager.launch_login_terminal(p_name.strip())\n  2001\t        if ok:\n  2002\t            messagebox.showinfo(t(\"dlg_claude_new_account\"), msg + \"\\n\\n\" + t(\"claude_login_steps\"))\n  2003\t            self.refresh_claude_profiles_async()\n  2004\t        else:\n  2005\t            messagebox.showerror(t(\"error\"), msg)\n  2006\n  2007\t    def on_save_active_claude_account(self):\n  2008\t        st = self.claude_active_status or {}\n  2009\t        email = st.get(\"email\") or \"\"\n  2010\t        p_name = simpledialog.askstring(\n  2011\t            t(\"btn_claude_save_active\"), t(\"dlg_profile_name\"),\n  2012\t            initialvalue=email if claude_oauth_manager.is_valid_profile_name(email) else claude_oauth_manager.suggest_profile_name(),\n  2013\t            parent=self\n  2014\t        )\n  2015\t        if not p_name:\n  2016\t            return\n  2017\t        ok, msg = claude_oauth_manager.save_active_as_profile(p_name.strip())\n  2018\t        (messagebox.showinfo if ok else messagebox.showerror)(t(\"tab_claude_oauth\"), msg)\n  2019\t        self.refresh_claude_profiles_async()\n  2020\n  2021\t    def on_switch_claude_profile(self, profile_name: str):\n  2022\t        ok, msg = claude_oauth_manager.switch_profile(profile_name)\n  2023\t        (messagebox.showinfo if ok else messagebox.showerror)(t(\"tab_claude_oauth\"), msg)\n  2024\t        self.refresh_claude_profiles_async()\n  2025\n  2026\t    def on_test_claude_token(self, profile_name: str):\n  2027\t        def worker():\n  2028\t            res = claude_oauth_manager.validate_profile_token(profile_name)\n  2029\n  2030\t            def show():\n  2031\t                if res.get(\"success\"):\n  2032\t                    messagebox.showinfo(t(\"tab_claude_oauth\"), t(\"claude_token_valid\", email=res.get(\"email\"), port=res.get(\"port\")))\n  2033\t                else:\n  2034\t                    messagebox.showerror(t(\"tab_claude_oauth\"), str(res.get(\"error\")))\n  2035\t            self.after(0, show)\n  2036\n  2037\t        threading.Thread(target=worker, daemon=True).start()\n  2038\n  2039\t    def on_rename_claude_profile(self, profile_name: str):\n  2040\t        new_name = simpledialog.askstring(t(\"tab_claude_oauth\"), t(\"dlg_profile_name\"), initialvalue=profile_name, parent=self)\n  2041\t        if not new_name or new_name.strip() == profile_name:\n  2042\t            return\n  2043\t        ok, msg = claude_oauth_manager.rename_profile(profile_name, new_name.strip())\n  2044\t        (messagebox.showinfo if ok else messagebox.showerror)(t(\"tab_claude_oauth\"), msg)\n  2045\t        self.refresh_claude_profiles_async()\n  2046\n  2047\t    def on_delete_claude_profile(self, profile_name: str):\n  2048\t        if not messagebox.askyesno(t(\"tab_claude_oauth\"), t(\"dlg_claude_delete\", profile=profile_name)):\n  2049\t            return\n  2050\t        ok, msg = claude_oauth_manager.delete_profile(profile_name)\n  2051\t        (messagebox.showinfo if ok else messagebox.showerror)(t(\"tab_claude_oauth\"), msg)\n  2052\t        self.refresh_claude_profiles_async()\n  2053\n  2054\t    # =========================================================================\n  2055\t    # СТРАНИЦА 4: STRATEGY & АНАЛИТИКА ПРОКСИ\n  2056\t    # =========================================================================\n  2057\t    def _build_page_strategy(self, parent: tk.Frame):\n  2058\t        s_top = tk.Frame(parent, bg=C[\"bg\"])\n  2059\t        s_top.pack(fill=\"x\", pady=(0, 10))\n  2060\n  2061\t        title_frame = tk.Frame(s_top, bg=C[\"bg\"])\n  2062\t        title_frame.pack(side=\"left\")\n  2063\n  2064\t        tk.Label(\n  2065\t            title_frame, text=\"📊 Гео-стратегия & Тенденции аккаунтов\", font=FONT_TITLE,\n  2066\t            fg=C[\"accent_blue\"], bg=C[\"bg\"]\n  2067\t        ).pack(anchor=\"w\")\n  2068\n  2069\t        tk.Label(\n  2070\t            title_frame,\n  2071\t            text=\"Сводка активности Google-аккаунтов. Сравнение текущего IP с исторической привычкой (ОК / Nice to change).\",\n  2072\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"bg\"]\n  2073\t        ).pack(anchor=\"w\")\n  2074\n  2075\t        btn_box = tk.Frame(s_top, bg=C[\"bg\"])\n  2076\t        btn_box.pack(side=\"right\")\n  2077\n  2078\t        self.btn_ext_log = tk.Button(\n  2079\t            btn_box, text=\"📜 Расширенный лог\", font=FONT_BOLD,\n  2080\t            bg=C[\"card_inner\"], fg=C[\"accent_peach\"], activebackground=C[\"border\"],\n  2081\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2082\t            command=self.show_extended_log_dialog\n  2083\t        )\n  2084\t        self.btn_ext_log.pack(side=\"left\", padx=(0, 8))\n  2085\n  2086\t        self.btn_refresh_strat = tk.Button(\n  2087\t            btn_box, text=t(\"btn_refresh_analytics\"), font=FONT_BOLD,\n  2088\t            bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  2089\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2090\t            command=self.render_strategy_page\n  2091\t        )\n  2092\t        self.btn_refresh_strat.pack(side=\"left\")\n  2093\n  2094\t        # Контейнер для карточек аккаунтов со скроллом\n  2095\t        canvas_card = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  2096\t        canvas_card.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2097\t        canvas_card.pack(fill=\"both\", expand=True)\n  2098\n  2099\t        self.strat_canvas = tk.Canvas(canvas_card, bg=C[\"bg\"], highlightthickness=0)\n  2100\t        self.strat_scrollbar = ttk.Scrollbar(canvas_card, orient=\"vertical\", command=self.strat_canvas.yview)\n  2101\t        self.strat_cards_container = tk.Frame(self.strat_canvas, bg=C[\"bg\"])\n  2102\n  2103\t        self.strat_cards_container.bind(\n  2104\t            \"<Configure>\",\n  2105\t            lambda e: self.strat_canvas.configure(scrollregion=self.strat_canvas.bbox(\"all\"))\n  2106\t        )\n  2107\t        self.strat_window_id = self.strat_canvas.create_window((0, 0), window=self.strat_cards_container, anchor=\"nw\")\n  2108\t        self.strat_canvas.bind(\"<Configure>\", lambda e: self.strat_canvas.itemconfig(self.strat_window_id, width=e.width))\n  2109\n  2110\t        self.strat_canvas.configure(yscrollcommand=self.strat_scrollbar.set)\n  2111\t        self.strat_canvas.pack(side=\"left\", fill=\"both\", expand=True, padx=2, pady=2)\n  2112\t        self.strat_scrollbar.pack(side=\"right\", fill=\"y\")\n  2113\n  2114\t    def render_strategy_page(self):\n  2115\t        for widget in self.strat_cards_container.winfo_children():\n  2116\t            widget.destroy()\n  2117\n  2118\t        tendencies = strategy_manager.get_account_tendencies()\n  2119\t        profiles = self.gemini_profiles\n  2120\t        if not profiles:\n  2121\t            empty_card = tk.Frame(self.strat_cards_container, bg=C[\"card\"], padx=20, pady=30)\n  2122\t            empty_card.pack(fill=\"x\", pady=10)\n  2123\t            tk.Label(\n  2124\t                empty_card, text=t(\"empty_strat\"),\n  2125\t                font=FONT_MAIN, fg=C[\"subtext\"], bg=C[\"card\"]\n  2126\t            ).pack()\n  2127\t            return\n  2128\n  2129\t        for prof in profiles:\n  2130\t            p_name = prof.get(\"profile_name\", \"account\")\n  2131\t            email = prof.get(\"email\", \"Без email\")\n  2132\t            curr_port = prof.get(\"port\", gemini_manager.BASE_SOCKS5_PORT)\n  2133\t            curr_ip = prof.get(\"proxy_ip\", \"-\")\n  2134\t            curr_co = prof.get(\"proxy_country\", \"undefined\")\n  2135\t            is_active = prof.get(\"is_active\", False)\n  2136\n  2137\t            eval_res = strategy_manager.evaluate_account_strategy(email, curr_co, tendencies, profile_name=p_name)\n  2138\t            st = eval_res.get(\"status\", \"neutral\")\n  2139\n  2140\t            card = tk.Frame(self.strat_cards_container, bg=C[\"card\"], bd=1, relief=\"solid\")\n  2141\t            card.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2142\t            card.pack(fill=\"x\", pady=5, padx=2)\n  2143\n  2144\t            c_in = tk.Frame(card, bg=C[\"card\"])\n  2145\t            c_in.pack(fill=\"both\", expand=True, padx=14, pady=10)\n  2146\n  2147\t            # Верхняя строка\n  2148\t            t_row = tk.Frame(c_in, bg=C[\"card\"])\n  2149\t            t_row.pack(fill=\"x\")\n  2150\n  2151\t            act_icon = \"🟢\" if is_active else \"⚪\"\n  2152\t            strat_title = f\"{act_icon} {p_name}\"\n  2153\t            tk.Label(\n  2154\t                t_row, text=strat_title, font=FONT_TITLE,\n  2155\t                fg=C[\"fg\"], bg=C[\"card\"]\n  2156\t            ).pack(side=\"left\")\n  2157\n  2158\t            tk.Label(\n  2159\t                t_row, text=f\" SOCKS5 :{curr_port} \", font=FONT_SUB,\n  2160\t                fg=C[\"accent_mauve\"], bg=C[\"tag_bg\"], padx=6, pady=1\n  2161\t            ).pack(side=\"left\", padx=(6, 0))\n  2162\n  2163\t            # Бейдж соответствия\n  2164\t            if st == \"ok\":\n  2165\t                b_text = t(\"status_optimal\")\n  2166\t                b_bg = C[\"green\"]\n  2167\t                b_fg = \"#11111b\"\n  2168\t            elif st == \"nice_to_change\":\n  2169\t                b_text = t(\"status_nice_to_change\")\n  2170\t                b_bg = C[\"yellow\"]\n  2171\t                b_fg = \"#11111b\"\n  2172\t            else:\n  2173\t                b_text = t(\"status_baseline\")\n  2174\t                b_bg = C[\"card_inner\"]\n  2175\t                b_fg = C[\"subtext\"]\n  2176\n  2177\t            tk.Label(\n  2178\t                t_row, text=f\" {b_text} \", font=FONT_BOLD,\n  2179\t                fg=b_fg, bg=b_bg, padx=8, pady=2\n  2180\t            ).pack(side=\"right\")\n  2181\n  2182\t            # Вторая строка\n  2183\t            d_row = tk.Frame(c_in, bg=C[\"card\"])\n  2184\t            d_row.pack(fill=\"x\", pady=(8, 4))\n  2185\n  2186\t            google_prefix = f\"Google: {email}  •  \" if email and email not in (\"Без email\", \"Не авторизован\", \"\") else \"\"\n  2187\t            tk.Label(\n  2188\t                d_row,\n  2189\t                text=f\"{google_prefix}Текущий туннель: 127.0.0.1:{curr_port}  ➔  {curr_ip} ({curr_co})\",\n  2190\t                font=FONT_MAIN, fg=C[\"fg\"], bg=C[\"card\"]\n  2191\t            ).pack(side=\"left\")\n  2192\n  2193\t            dom_c = eval_res.get(\"dominant_country\", \"undefined\")\n  2194\t            dom_p = eval_res.get(\"dominant_percent\", 0)\n  2195\t            dom_dur = eval_res.get(\"dominant_duration_fmt\", \"\")\n  2196\t            dur_str = f\" • {dom_dur}\" if dom_dur and dom_dur != \"0 сек\" else \"\"\n  2197\n  2198\t            tk.Label(\n  2199\t                d_row,\n  2200\t                text=f\"Привычный регион: {dom_c} ({dom_p}% времени{dur_str})\",\n  2201\t                font=FONT_BOLD, fg=C[\"accent_blue\"], bg=C[\"card\"]\n  2202\t            ).pack(side=\"right\")\n  2203\n  2204\t            # Блок рекомендации\n  2205\t            rec_box = tk.Frame(c_in, bg=C[\"card_inner\"], bd=1, relief=\"solid\")\n  2206\t            rec_box.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2207\t            rec_box.pack(fill=\"x\", pady=(4, 2))\n  2208\n  2209\t            r_in = tk.Frame(rec_box, bg=C[\"card_inner\"])\n  2210\t            r_in.pack(fill=\"x\", padx=10, pady=6)\n  2211\n  2212\t            tk.Label(\n  2213\t                r_in,\n  2214\t                text=eval_res.get(\"recommendation\", \"\"),\n  2215\t                font=FONT_SUB, fg=C[\"accent_peach\"] if st == \"nice_to_change\" else C[\"fg\"],\n  2216\t                bg=C[\"card_inner\"], wraplength=740, justify=\"left\"\n  2217\t            ).pack(side=\"left\")\n  2218\n  2219\t            if st == \"nice_to_change\" and dom_c and dom_c.lower() not in (\"undefined\", \"-\"):\n  2220\t                target_cand = next(\n  2221\t                    (p for p in self.proxies if (p.get(\"country\") or \"\").lower() == dom_c.lower() and p.get(\"port\") != curr_port),\n  2222\t                    None\n  2223\t                )\n  2224\t                if target_cand:\n  2225\t                    btn_opt = tk.Button(\n  2226\t                        r_in,\n  2227\t                        text=f\"⚡ Выбрать :{target_cand[''port'']} ({dom_c})\",\n  2228\t                        font=FONT_BOLD, bg=C[\"accent_peach\"], fg=\"#11111b\",\n  2229\t                        activebackground=\"#fab387\", bd=0, padx=8, pady=3, cursor=\"hand2\",\n  2230\t                        command=lambda p_target=target_cand[''port''], prof_n=p_name: self.on_reassign_account_proxy(prof_n, p_target)\n  2231\t                    )\n  2232\t                    btn_opt.pack(side=\"right\", padx=(8, 0))\n  2233\n  2234\t    def on_reassign_account_proxy(self, profile_name: str, new_port: int):\n  2235\t        gemini_manager.save_profile_port(profile_name, new_port)\n  2236\t        active_prof = next((p for p in self.gemini_profiles if p.get(\"is_active\")), None)\n  2237\t        if active_prof and active_prof.get(\"profile_name\") == profile_name:\n  2238\t            gemini_manager.write_active_proxy_env(new_port, active_prof.get(\"email\", \"\"))\n  2239\t        self.load_gemini_profiles_data()\n  2240\t        self.render_strategy_page()\n  2241\t        self.refresh_routes_async()\n  2242\t        messagebox.showinfo(\"Стратегия\", f\"Профиль ''{profile_name}'' успешно перенаправлен на порт :{new_port}!\")\n  2243\n  2244\t    def show_extended_log_dialog(self):\n  2245\t        dlg = tk.Toplevel(self)\n  2246\t        dlg.title(\"Расширенный журнал сессий, времени соединений и статистика IP\")\n  2247\t        dlg.geometry(\"960x580\")\n  2248\t        dlg.minsize(860, 480)\n  2249\t        dlg.configure(bg=C[\"bg\"])\n  2250\n  2251\t        style = ttk.Style()\n  2252\t        style.theme_use(\"clam\")\n  2253\t        style.configure(\"TNotebook\", background=C[\"bg\"], borderwidth=0)\n  2254\t        style.configure(\"TNotebook.Tab\", background=C[\"card_inner\"], foreground=C[\"fg\"], padding=[12, 6])\n  2255\t        style.map(\"TNotebook.Tab\", background=[(\"selected\", C[\"card\"])], foreground=[(\"selected\", C[\"accent_blue\"])])\n  2256\n  2257\t        nb = ttk.Notebook(dlg)\n  2258\t        nb.pack(fill=\"both\", expand=True, padx=12, pady=12)\n  2259\n  2260\t        tab_history = tk.Frame(nb, bg=C[\"bg\"])\n  2261\t        nb.add(tab_history, text=\"📜 Журнал сессий и времени соединений\")\n  2262\n  2263\t        tab_ips = tk.Frame(nb, bg=C[\"bg\"])\n  2264\t        nb.add(tab_ips, text=\"🌐 Сводка по уникальным IP и длительности\")\n  2265\n  2266\t        # Вкладка 1: История с длительностью соединений\n  2267\t        cols1 = (\"time\", \"duration\", \"account\", \"port\", \"ip\", \"country\", \"event\", \"note\")\n  2268\t        tree1 = ttk.Treeview(tab_history, columns=cols1, show=\"headings\", height=18)\n  2269\t        tree1.heading(\"time\", text=\"Время начала\")\n  2270\t        tree1.heading(\"duration\", text=\"Длительность\")\n  2271\t        tree1.heading(\"account\", text=\"Аккаунт Google\")\n  2272\t        tree1.heading(\"port\", text=\"Порт\")\n  2273\t        tree1.heading(\"ip\", text=\"Внешний IP\")\n  2274\t        tree1.heading(\"country\", text=\"Страна\")\n  2275\t        tree1.heading(\"event\", text=\"Событие\")\n  2276\t        tree1.heading(\"note\", text=\"Примечание\")\n  2277\n  2278\t        tree1.column(\"time\", width=135, anchor=\"w\")\n  2279\t        tree1.column(\"duration\", width=95, anchor=\"center\")\n  2280\t        tree1.column(\"account\", width=170, anchor=\"w\")\n  2281\t        tree1.column(\"port\", width=60, anchor=\"center\")\n  2282\t        tree1.column(\"ip\", width=115, anchor=\"w\")\n  2283\t        tree1.column(\"country\", width=95, anchor=\"w\")\n  2284\t        tree1.column(\"event\", width=85, anchor=\"center\")\n  2285\t        tree1.column(\"note\", width=140, anchor=\"w\")\n  2286\n  2287\t        sc1 = ttk.Scrollbar(tab_history, orient=\"vertical\", command=tree1.yview)\n  2288\t        tree1.configure(yscrollcommand=sc1.set)\n  2289\t        tree1.pack(side=\"left\", fill=\"both\", expand=True)\n  2290\t        sc1.pack(side=\"right\", fill=\"y\")\n  2291\n  2292\t        history = strategy_manager.load_history()\n  2293\t        for e in reversed(history):\n  2294\t            tree1.insert(\n  2295\t                \"\", \"end\",\n  2296\t                values=(\n  2297\t                    e.get(\"start_time\") or e.get(\"timestamp\", \"-\"),\n  2298\t                    e.get(\"duration_fmt\", \"-\"),\n  2299\t                    e.get(\"account_email\", \"-\"),\n  2300\t                    e.get(\"port\", \"-\"),\n  2301\t                    e.get(\"ip\", \"-\"),\n  2302\t                    e.get(\"country\", \"-\"),\n  2303\t                    e.get(\"event\", \"-\"),\n  2304\t                    e.get(\"note\", \"-\"),\n  2305\t                )\n  2306\t            )\n  2307\n  2308\t        # Вкладка 2: Сводка по IP с суммарным временем\n  2309\t        cols2 = (\"ip\", \"country\", \"duration\", \"launches\", \"ports\", \"accounts\", \"last_seen\")\n  2310\t        tree2 = ttk.Treeview(tab_ips, columns=cols2, show=\"headings\", height=18)\n  2311\t        tree2.heading(\"ip\", text=\"Внешний IP\")\n  2312\t        tree2.heading(\"country\", text=\"Страна\")\n  2313\t        tree2.heading(\"duration\", text=\"Общее время\")\n  2314\t        tree2.heading(\"launches\", text=\"Сессий\")\n  2315\t        tree2.heading(\"ports\", text=\"Порты\")\n  2316\t        tree2.heading(\"accounts\", text=\"Аккаунты\")\n  2317\t        tree2.heading(\"last_seen\", text=\"Последняя активность\")\n  2318\n  2319\t        tree2.column(\"ip\", width=125, anchor=\"w\")\n  2320\t        tree2.column(\"country\", width=110, anchor=\"w\")\n  2321\t        tree2.column(\"duration\", width=105, anchor=\"center\")\n  2322\t        tree2.column(\"launches\", width=65, anchor=\"center\")\n  2323\t        tree2.column(\"ports\", width=80, anchor=\"w\")\n  2324\t        tree2.column(\"accounts\", width=160, anchor=\"w\")\n  2325\t        tree2.column(\"last_seen\", width=135, anchor=\"w\")\n  2326\n  2327\t        sc2 = ttk.Scrollbar(tab_ips, orient=\"vertical\", command=tree2.yview)\n  2328\t        tree2.configure(yscrollcommand=sc2.set)\n  2329\t        tree2.pack(side=\"left\", fill=\"both\", expand=True)\n  2330\t        sc2.pack(side=\"right\", fill=\"y\")\n  2331\n  2332\t        ip_stats = strategy_manager.get_extended_ip_stats()\n  2333\t        for s in ip_stats:\n  2334\t            ports_str = \", \".join(str(p) for p in s.get(\"ports\", []))\n  2335\t            accs_str = \", \".join(s.get(\"accounts\", []))\n  2336\t            tree2.insert(\n  2337\t                \"\", \"end\",\n  2338\t                values=(\n  2339\t                    s.get(\"ip\", \"-\"),\n  2340\t                    s.get(\"country\", \"-\"),\n  2341\t                    s.get(\"total_duration_fmt\", \"-\"),\n  2342\t                    s.get(\"total_launches\", 0),\n  2343\t                    ports_str,\n  2344\t                    accs_str,\n  2345\t                    s.get(\"last_seen\", \"-\"),\n  2346\t                )\n  2347\t            )\n  2348\n  2349\t    # =========================================================================\n  2350\t    # СТРАНИЦА 5: BACKUP & ВОССТАНОВЛЕНИЕ\n  2351\t    # =========================================================================\n  2352\t    def _build_page_backup(self, parent: tk.Frame):\n  2353\t        b_top = tk.Frame(parent, bg=C[\"bg\"])\n  2354\t        b_top.pack(fill=\"x\", pady=(0, 10))\n  2355\n  2356\t        title_frame = tk.Frame(b_top, bg=C[\"bg\"])\n  2357\t        title_frame.pack(side=\"left\")\n  2358\n  2359\t        tk.Label(\n  2360\t            title_frame, text=\"💾 Резервное копирование & Восстановление\", font=FONT_TITLE,\n  2361\t            fg=C[\"accent_blue\"], bg=C[\"bg\"]\n  2362\t        ).pack(anchor=\"w\")\n  2363\n  2364\t        tk.Label(\n  2365\t            title_frame,\n  2366\t            text=\"Полный snapshot системы (настройки GUI, прокси, токены и аккаунты WSL2) с шифрованием AES-256-GCM.\",\n  2367\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"bg\"]\n  2368\t        ).pack(anchor=\"w\")\n  2369\n  2370\t        btn_box = tk.Frame(b_top, bg=C[\"bg\"])\n  2371\t        btn_box.pack(side=\"right\")\n  2372\n  2373\t        self.btn_refresh_backup = tk.Button(\n  2374\t            btn_box, text=\"🔄 Обновить список\", font=FONT_BOLD,\n  2375\t            bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  2376\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2377\t            command=self.render_backup_page\n  2378\t        )\n  2379\t        self.btn_refresh_backup.pack(side=\"left\")\n  2380\n  2381\t        # ── 1. Панель пароля шифрования ────────────────────────\n  2382\t        pw_card = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  2383\t        pw_card.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2384\t        pw_card.pack(fill=\"x\", pady=(0, 10))\n  2385\n  2386\t        pw_in = tk.Frame(pw_card, bg=C[\"card\"])\n  2387\t        pw_in.pack(fill=\"both\", expand=True, padx=14, pady=10)\n  2388\n  2389\t        r_pw1 = tk.Frame(pw_in, bg=C[\"card\"])\n  2390\t        r_pw1.pack(fill=\"x\")\n  2391\n  2392\t        tk.Label(\n  2393\t            r_pw1, text=t(\"lbl_master_password\"), font=FONT_BOLD,\n  2394\t            fg=C[\"accent_peach\"], bg=C[\"card\"]\n  2395\t        ).pack(side=\"left\")\n  2396\n  2397\t        self.backup_pw_entry = tk.Entry(\n  2398\t            r_pw1, textvariable=self.backup_password_var, show=\"*\",\n  2399\t            font=FONT_MONO_BOLD, bg=C[\"card_inner\"], fg=C[\"fg\"],\n  2400\t            insertbackground=C[\"fg\"], bd=1, relief=\"solid\", width=28\n  2401\t        )\n  2402\t        self.backup_pw_entry.pack(side=\"left\", padx=(10, 8), ipady=3)\n  2403\n  2404\t        self.btn_eye = tk.Button(\n  2405\t            r_pw1, text=t(\"btn_show_pw\"), font=FONT_SUB,\n  2406\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], activebackground=C[\"border\"],\n  2407\t            bd=0, padx=8, pady=3, cursor=\"hand2\",\n  2408\t            command=self.toggle_backup_pw_visibility\n  2409\t        )\n  2410\t        self.btn_eye.pack(side=\"left\")\n  2411\n  2412\t        # Хэш-отпечаток\n  2413\t        self.backup_fp_lbl = tk.Label(\n  2414\t            r_pw1, text=\"Хэш-отпечаток (SHA-256): [ ---------------- ]\",\n  2415\t            font=FONT_MONO, fg=C[\"accent_blue\"], bg=C[\"card\"]\n  2416\t        )\n  2417\t        self.backup_fp_lbl.pack(side=\"right\")\n  2418\t        self._on_backup_password_changed()\n  2419\n  2420\t        tk.Label(\n  2421\t            pw_in,\n  2422\t            text=\"Пароль хранится в .env и используется для шифрования архивов AES-256-GCM. Без введенного пароля бэкап невозможно создать или расшифровать.\",\n  2423\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"card\"]\n  2424\t        ).pack(anchor=\"w\", pady=(4, 0))\n  2425\n  2426\t        # ── 2. Панель параметров хранения и расписания ─────────\n  2427\t        cfg_card = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  2428\t        cfg_card.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2429\t        cfg_card.pack(fill=\"x\", pady=(0, 10))\n  2430\n  2431\t        c_in = tk.Frame(cfg_card, bg=C[\"card\"])\n  2432\t        c_in.pack(fill=\"both\", expand=True, padx=14, pady=10)\n  2433\n  2434\t        # Папка бэкапов\n  2435\t        r_dir = tk.Frame(c_in, bg=C[\"card\"])\n  2436\t        r_dir.pack(fill=\"x\")\n  2437\n  2438\t        tk.Label(r_dir, text=t(\"lbl_backup_dir\"), font=FONT_BOLD, fg=C[\"fg\"], bg=C[\"card\"]).pack(side=\"left\")\n  2439\n  2440\t        self.backup_dir_entry = tk.Entry(\n  2441\t            r_dir, textvariable=self.backup_dir_var, font=FONT_MAIN,\n  2442\t            bg=C[\"card_inner\"], fg=C[\"fg\"], insertbackground=C[\"fg\"],\n  2443\t            bd=1, relief=\"solid\"\n  2444\t        )\n  2445\t        self.backup_dir_entry.pack(side=\"left\", fill=\"x\", expand=True, padx=(10, 8), ipady=3)\n  2446\n  2447\t        btn_browse = tk.Button(\n  2448\t            r_dir, text=t(\"btn_browse\"), font=FONT_MAIN,\n  2449\t            bg=C[\"card_inner\"], fg=C[\"fg\"], activeback\n\n... [truncated 18475 chars] ...\n\ntate=\"normal\", text=\"📥 Восстановить из файла (Импорт)\")\n  2705\t                if ok:\n  2706\t                    self.load_backup_config_data()\n  2707\t                    self.load_proxies_data()\n  2708\t                    self.load_gemini_profiles_data()\n  2709\t                    self.render_backup_page()\n  2710\t                    if hasattr(self, \"_load_initial_console_logs\"):\n  2711\t                        self._load_initial_console_logs()\n  2712\t                    if hasattr(self, \"on_integrations_status_click\"):\n  2713\t                        self.on_integrations_status_click()\n  2714\t                    self.refresh_routes_async()\n  2715\t                    messagebox.showinfo(\"Импорт бэкапа\", msg)\n  2716\t                else:\n  2717\t                    messagebox.showerror(\"Ошибка импорта\", msg)\n  2718\t            self.after(0, done)\n  2719\n  2720\t        threading.Thread(target=worker, daemon=True).start()\n  2721\n  2722\t    def load_backup_config_data(self):\n  2723\t        \"\"\"Перезагружает параметры бэкапа из settings.json в переменные UI.\"\"\"\n  2724\t        b_cfg = backup_manager.get_backup_config()\n  2725\t        self._suppress_backup_trace = True\n  2726\t        try:\n  2727\t            self.backup_dir_var.set(b_cfg.get(\"backup_dir\", str(backup_manager.DEFAULT_BACKUP_DIR)))\n  2728\t            self.backup_interval_var.set(b_cfg.get(\"backup_interval_hours\", 12))\n  2729\t            self.auto_backup_enabled_var.set(b_cfg.get(\"auto_backup_enabled\", False))\n  2730\t            self.backup_password_var.set(backup_manager.load_backup_password())\n  2731\t        finally:\n  2732\t            self._suppress_backup_trace = False\n  2733\n  2734\t    def on_restore_specific_backup(self, filepath: str):\n  2735\t        pw = self.backup_password_var.get().strip()\n  2736\t        if not pw:\n  2737\t            messagebox.showwarning(\"Внимание\", \"Сначала введите пароль для расшифровки бэкапа!\")\n  2738\t            return\n  2739\n  2740\t        fn = Path(filepath).name\n  2741\t        if not messagebox.askyesno(\n  2742\t            \"Подтверждение импорта\",\n  2743\t            f\"Восстановить систему из файла:\\n{fn}?\\n\\nТекущие данные будут заменены содержимым бэкапа.\"\n  2744\t        ):\n  2745\t            return\n  2746\n  2747\t        def worker():\n  2748\t            ok, msg, _ = backup_manager.restore_encrypted_backup(filepath, pw)\n  2749\t            def done():\n  2750\t                if ok:\n  2751\t                    self.load_backup_config_data()\n  2752\t                    self.load_proxies_data()\n  2753\t                    self.load_gemini_profiles_data()\n  2754\t                    self.render_backup_page()\n  2755\t                    if hasattr(self, \"_load_initial_console_logs\"):\n  2756\t                        self._load_initial_console_logs()\n  2757\t                    if hasattr(self, \"on_integrations_status_click\"):\n  2758\t                        self.on_integrations_status_click()\n  2759\t                    self.refresh_routes_async()\n  2760\t                    messagebox.showinfo(\"Импорт бэкапа\", msg)\n  2761\t                else:\n  2762\t                    messagebox.showerror(\"Ошибка импорта\", msg)\n  2763\t            self.after(0, done)\n  2764\n  2765\t        threading.Thread(target=worker, daemon=True).start()\n  2766\n  2767\t    # =========================================================================\n  2768\t    # СТРАНИЦА: ИНТЕГРАЦИИ (AionUi, OmniRoute, Claude Code, Gemini Farm)\n  2769\t    # =========================================================================\n  2770\t    def _build_page_integrations(self, parent: tk.Frame):\n  2771\t        \"\"\"Построение вкладки Интеграции.\"\"\"\n  2772\t        p_top = tk.Frame(parent, bg=C[\"bg\"])\n  2773\t        p_top.pack(fill=\"x\", pady=(0, 10))\n  2774\n  2775\t        tk.Label(\n  2776\t            p_top, text=t(\"integrations_title\"), font=FONT_TITLE,\n  2777\t            fg=C[\"accent_blue\"], bg=C[\"bg\"]\n  2778\t        ).pack(anchor=\"w\")\n  2779\n  2780\t        tk.Label(\n  2781\t            p_top, text=t(\"integrations_subtitle\"), font=FONT_SUB,\n  2782\t            fg=C[\"subtext\"], bg=C[\"bg\"]\n  2783\t        ).pack(anchor=\"w\")\n  2784\n  2785\t        # ── Карточка 1: Окно AionUi & Быстрый статус ────────────────────────\n  2786\t        card_aion = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  2787\t        card_aion.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2788\t        card_aion.pack(fill=\"x\", pady=(0, 10))\n  2789\n  2790\t        pad_aion = tk.Frame(card_aion, bg=C[\"card\"])\n  2791\t        pad_aion.pack(fill=\"both\", expand=True, padx=16, pady=12)\n  2792\n  2793\t        # Заголовок карточки\n  2794\t        head_box = tk.Frame(pad_aion, bg=C[\"card\"])\n  2795\t        head_box.pack(fill=\"x\", pady=(0, 6))\n  2796\n  2797\t        tk.Label(\n  2798\t            head_box, text=t(\"card_aionui_title\"), font=FONT_BOLD,\n  2799\t            fg=C[\"fg\"], bg=C[\"card\"]\n  2800\t        ).pack(side=\"left\")\n  2801\n  2802\t        self.lbl_integ_overall = tk.Label(\n  2803\t            head_box, text=\"READY\", font=FONT_SUB,\n  2804\t            fg=\"#11111b\", bg=C[\"green\"], padx=6, pady=1\n  2805\t        )\n  2806\t        self.lbl_integ_overall.pack(side=\"right\")\n  2807\n  2808\t        tk.Label(\n  2809\t            pad_aion, text=t(\"card_aionui_desc\"), font=FONT_SUB,\n  2810\t            fg=C[\"subtext\"], bg=C[\"card\"]\n  2811\t        ).pack(anchor=\"w\", pady=(0, 10))\n  2812\n  2813\t        # Блок статусов компонентов (4 плашки в одну линию)\n  2814\t        st_frame = tk.Frame(pad_aion, bg=C[\"card\"])\n  2815\t        st_frame.pack(fill=\"x\", pady=(0, 12))\n  2816\n  2817\t        # 1. AionUi :25808\n  2818\t        self.badge_aionui = tk.Label(\n  2819\t            st_frame, text=\"AionUi (:25808): ● ...\", font=FONT_SUB,\n  2820\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], padx=8, pady=4, bd=1, relief=\"solid\"\n  2821\t        )\n  2822\t        self.badge_aionui.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2823\t        self.badge_aionui.pack(side=\"left\", padx=(0, 6), expand=True, fill=\"x\")\n  2824\n  2825\t        # 2. OmniRoute :20128\n  2826\t        self.badge_omniroute = tk.Label(\n  2827\t            st_frame, text=\"OmniRoute (:20128): ● ...\", font=FONT_SUB,\n  2828\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], padx=8, pady=4, bd=1, relief=\"solid\"\n  2829\t        )\n  2830\t        self.badge_omniroute.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2831\t        self.badge_omniroute.pack(side=\"left\", padx=6, expand=True, fill=\"x\")\n  2832\n  2833\t        # 3. Claude Code :1015\n  2834\t        self.badge_claude = tk.Label(\n  2835\t            st_frame, text=\"Claude (:1015): ● ...\", font=FONT_SUB,\n  2836\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], padx=8, pady=4, bd=1, relief=\"solid\"\n  2837\t        )\n  2838\t        self.badge_claude.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2839\t        self.badge_claude.pack(side=\"left\", padx=6, expand=True, fill=\"x\")\n  2840\n  2841\t        # 4. Gemini Farm :1081+\n  2842\t        self.badge_gemini = tk.Label(\n  2843\t            st_frame, text=\"Gemini Farm: ● ...\", font=FONT_SUB,\n  2844\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], padx=8, pady=4, bd=1, relief=\"solid\"\n  2845\t        )\n  2846\t        self.badge_gemini.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2847\t        self.badge_gemini.pack(side=\"left\", padx=(6, 0), expand=True, fill=\"x\")\n  2848\n  2849\t        # Панель кнопок действий\n  2850\t        btn_bar = tk.Frame(pad_aion, bg=C[\"card\"])\n  2851\t        btn_bar.pack(fill=\"x\")\n  2852\n  2853\t        self.btn_integ_status = tk.Button(\n  2854\t            btn_bar, text=t(\"btn_aionui_status\"), font=FONT_BOLD,\n  2855\t            bg=C[\"accent_blue\"], fg=\"#11111b\", activebackground=\"#b4befe\",\n  2856\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2857\t            command=self.on_integrations_status_click\n  2858\t        )\n  2859\t        self.btn_integ_status.pack(side=\"left\", padx=(0, 6))\n  2860\n  2861\t        self.btn_integ_sync_claude = tk.Button(\n  2862\t            btn_bar, text=t(\"btn_sync_claude\"), font=FONT_BOLD,\n  2863\t            bg=C[\"card_inner\"], fg=C[\"accent_peach\"], activebackground=C[\"border\"],\n  2864\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2865\t            command=self.on_integrations_sync_claude_click\n  2866\t        )\n  2867\t        self.btn_integ_sync_claude.pack(side=\"left\", padx=6)\n  2868\n  2869\t        self.btn_integ_sync_gemini = tk.Button(\n  2870\t            btn_bar, text=t(\"btn_sync_gemini\"), font=FONT_BOLD,\n  2871\t            bg=C[\"card_inner\"], fg=C[\"accent_mauve\"], activebackground=C[\"border\"],\n  2872\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2873\t            command=self.on_integrations_sync_gemini_click\n  2874\t        )\n  2875\t        self.btn_integ_sync_gemini.pack(side=\"left\", padx=6)\n  2876\n  2877\t        self.btn_integ_history = tk.Button(\n  2878\t            btn_bar, text=t(\"btn_view_logs\"), font=FONT_BOLD,\n  2879\t            bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  2880\t            bd=0, padx=12, pady=6, cursor=\"hand2\",\n  2881\t            command=self.show_log_history_dialog\n  2882\t        )\n  2883\t        self.btn_integ_history.pack(side=\"right\", padx=(6, 0))\n  2884\n  2885\t        self.btn_integ_clear_console = tk.Button(\n  2886\t            btn_bar, text=t(\"btn_clear_console\"), font=FONT_MAIN,\n  2887\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], activebackground=C[\"border\"],\n  2888\t            bd=0, padx=10, pady=6, cursor=\"hand2\",\n  2889\t            command=self.clear_integrations_console\n  2890\t        )\n  2891\t        self.btn_integ_clear_console.pack(side=\"right\", padx=6)\n  2892\n  2893\t        # ── Карточка 2: Консоль хода выполнения (Логи) ──────────────────────\n  2894\t        con_card = tk.Frame(parent, bg=C[\"card\"], bd=1, relief=\"solid\")\n  2895\t        con_card.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2896\t        con_card.pack(fill=\"both\", expand=True)\n  2897\n  2898\t        con_pad = tk.Frame(con_card, bg=C[\"card\"])\n  2899\t        con_pad.pack(fill=\"both\", expand=True, padx=16, pady=12)\n  2900\n  2901\t        con_head = tk.Frame(con_pad, bg=C[\"card\"])\n  2902\t        con_head.pack(fill=\"x\", pady=(0, 8))\n  2903\n  2904\t        tk.Label(\n  2905\t            con_head, text=t(\"lbl_console_title\"), font=FONT_BOLD,\n  2906\t            fg=C[\"fg\"], bg=C[\"card\"]\n  2907\t        ).pack(side=\"left\")\n  2908\n  2909\t        self.lbl_log_stats = tk.Label(\n  2910\t            con_head,\n  2911\t            text=t(\"lbl_log_stats\", file=\"integrations.log\", size=integrations_manager.logger.get_file_size_str()),\n  2912\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"card\"]\n  2913\t        )\n  2914\t        self.lbl_log_stats.pack(side=\"right\")\n  2915\n  2916\t        # Окно консоли с прокруткой\n  2917\t        con_wrap = tk.Frame(con_pad, bg=\"#11111b\", bd=1, relief=\"solid\")\n  2918\t        con_wrap.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  2919\t        con_wrap.pack(fill=\"both\", expand=True)\n  2920\n  2921\t        self.integ_console = tk.Text(\n  2922\t            con_wrap, bg=\"#11111b\", fg=C[\"fg\"], insertbackground=C[\"fg\"],\n  2923\t            selectbackground=C[\"border\"], font=FONT_MONO, wrap=\"word\",\n  2924\t            relief=\"flat\", bd=0, padx=10, pady=10, state=\"disabled\"\n  2925\t        )\n  2926\t        sc_con = ttk.Scrollbar(con_wrap, orient=\"vertical\", command=self.integ_console.yview)\n  2927\t        self.integ_console.configure(yscrollcommand=sc_con.set)\n  2928\n  2929\t        self.integ_console.pack(side=\"left\", fill=\"both\", expand=True)\n  2930\t        sc_con.pack(side=\"right\", fill=\"y\")\n  2931\n  2932\t        # Теги для подсветки синтаксиса логов\n  2933\t        self.integ_console.tag_config(\"TIMESTAMP\", foreground=\"#6c7086\")\n  2934\t        self.integ_console.tag_config(\"INFO\", foreground=\"#cdd6f4\")\n  2935\t        self.integ_console.tag_config(\"SUCCESS\", foreground=C[\"green\"])\n  2936\t        self.integ_console.tag_config(\"WARN\", foreground=C[\"yellow\"])\n  2937\t        self.integ_console.tag_config(\"ERROR\", foreground=C[\"red\"])\n  2938\t        self.integ_console.tag_config(\"STEP\", foreground=C[\"accent_blue\"], font=FONT_MONO_BOLD)\n  2939\t        self.integ_console.tag_config(\"SYSTEM\", foreground=C[\"accent_mauve\"])\n  2940\n  2941\t        self._load_initial_console_logs()\n  2942\n  2943\t    def _load_initial_console_logs(self):\n  2944\t        \"\"\"Загрузка недавних логов при старте интерфейса.\"\"\"\n  2945\t        if not hasattr(self, \"integ_console\") or not self.integ_console.winfo_exists():\n  2946\t            return\n  2947\t        hist = integrations_manager.logger.read_history()\n  2948\t        lines = hist.strip().splitlines()\n  2949\t        last_lines = lines[-40:] if len(lines) > 40 else lines\n  2950\t        self.integ_console.config(state=\"normal\")\n  2951\t        self.integ_console.delete(\"1.0\", \"end\")\n  2952\t        for line in last_lines:\n  2953\t            lvl = \"INFO\"\n  2954\t            if \"[SUCCESS]\" in line:\n  2955\t                lvl = \"SUCCESS\"\n  2956\t            elif \"[WARN]\" in line:\n  2957\t                lvl = \"WARN\"\n  2958\t            elif \"[ERROR]\" in line:\n  2959\t                lvl = \"ERROR\"\n  2960\t            elif \"[STEP]\" in line:\n  2961\t                lvl = \"STEP\"\n  2962\t            elif \"[SYSTEM]\" in line:\n  2963\t                lvl = \"SYSTEM\"\n  2964\t            self.integ_console.insert(\"end\", line + \"\\n\", lvl)\n  2965\t        self.integ_console.see(\"end\")\n  2966\t        self.integ_console.config(state=\"disabled\")\n  2967\t        self._update_log_stats_label()\n  2968\n  2969\t    def _on_integration_log(self, ts: str, level: str, message: str):\n  2970\t        \"\"\"Слушатель логов для динамического добавления в консоль.\"\"\"\n  2971\t        def _ui_update():\n  2972\t            if not hasattr(self, \"integ_console\") or not self.integ_console.winfo_exists():\n  2973\t                return\n  2974\t            self.integ_console.config(state=\"normal\")\n  2975\t            self.integ_console.insert(\"end\", f\"[{ts}] \", \"TIMESTAMP\")\n  2976\t            self.integ_console.insert(\"end\", f\"[{level}] \", level)\n  2977\t            self.integ_console.insert(\"end\", f\"{message}\\n\", level)\n  2978\t            self.integ_console.see(\"end\")\n  2979\t            self.integ_console.config(state=\"disabled\")\n  2980\t            self._update_log_stats_label()\n  2981\t        self.after(0, _ui_update)\n  2982\n  2983\t    def _update_log_stats_label(self):\n  2984\t        \"\"\"Обновление плашки размера файла логов.\"\"\"\n  2985\t        if hasattr(self, \"lbl_log_stats\") and self.lbl_log_stats.winfo_exists():\n  2986\t            sz = integrations_manager.logger.get_file_size_str()\n  2987\t            self.lbl_log_stats.config(text=t(\"lbl_log_stats\", file=\"integrations.log\", size=sz))\n  2988\n  2989\t    def clear_integrations_console(self):\n  2990\t        \"\"\"Очищает экранную консоль GUI.\"\"\"\n  2991\t        if hasattr(self, \"integ_console\") and self.integ_console.winfo_exists():\n  2992\t            self.integ_console.config(state=\"normal\")\n  2993\t            self.integ_console.delete(\"1.0\", \"end\")\n  2994\t            self.integ_console.config(state=\"disabled\")\n  2995\t            integrations_manager.logger.log(\"Экранная консоль очищена (полный журнал сохранен в integrations.log)\", \"SYSTEM\")\n  2996\n  2997\t    def render_integrations_page(self):\n  2998\t        \"\"\"Обновление страницы интеграций при переключении на неё.\"\"\"\n  2999\t        self._update_log_stats_label()\n  3000\t        if not getattr(self, \"_has_checked_integ_once\", False):\n  3001\t            self._has_checked_integ_once = True\n  3002\t            self.on_integrations_status_click()\n  3003\n  3004\t    def on_integrations_status_click(self):\n  3005\t        \"\"\"Запуск комплексной проверки статуса AionUi, OmniRoute, Claude и Gemini.\"\"\"\n  3006\t        if getattr(self, \"_integ_task_running\", False):\n  3007\t            return\n  3008\t        self._integ_task_running = True\n  3009\t        self.btn_integ_status.config(state=\"disabled\", text=\"⏳ Проверка...\")\n  3010\t        self.lbl_integ_overall.config(text=\"CHECKING...\", bg=C[\"yellow\"], fg=\"#11111b\")\n  3011\n  3012\t        def worker():\n  3013\t            try:\n  3014\t                res = integrations_manager.check_aionui_status()\n  3015\t            except Exception as e:\n  3016\t                integrations_manager.logger.log(f\"Ошибка проверки статуса: {e}\", \"ERROR\")\n  3017\t                res = {}\n  3018\t            def done():\n  3019\t                self._integ_task_running = False\n  3020\t                self.btn_integ_status.config(state=\"normal\", text=t(\"btn_aionui_status\"))\n  3021\t                self._apply_integrations_status(res)\n  3022\t            try:\n  3023\t                if not getattr(self, \"_closing\", False):\n  3024\t                    self.after(0, done)\n  3025\t            except Exception:\n  3026\t                pass\n  3027\n  3028\t        threading.Thread(target=worker, daemon=True).start()\n  3029\n  3030\t    def _apply_integrations_status(self, res: dict):\n  3031\t        \"\"\"Обновление плашек статуса на основе диагностики.\"\"\"\n  3032\t        if not hasattr(self, \"badge_aionui\") or not self.badge_aionui.winfo_exists():\n  3033\t            return\n  3034\t        # 1. AionUi\n  3035\t        aion = res.get(\"aionui\", {})\n  3036\t        if aion.get(\"online\"):\n  3037\t            self.badge_aionui.config(text=\"AionUi (:25808): ● ONLINE\", fg=C[\"green\"])\n  3038\t        else:\n  3039\t            self.badge_aionui.config(text=\"AionUi (:25808): ● OFFLINE\", fg=C[\"red\"])\n  3040\n  3041\t        # 2. OmniRoute\n  3042\t        omni = res.get(\"omniroute\", {})\n  3043\t        if omni.get(\"online\"):\n  3044\t            self.badge_omniroute.config(text=\"OmniRoute (:20128): ● ONLINE\", fg=C[\"green\"])\n  3045\t        else:\n  3046\t            self.badge_omniroute.config(text=\"OmniRoute (:20128): ● OFFLINE\", fg=C[\"red\"])\n  3047\n  3048\t        # 3. Claude\n  3049\t        claude = res.get(\"claude\", {})\n  3050\t        c_socks = claude.get(\"socks5_1015\", False)\n  3051\t        c_auth = claude.get(\"oauth\", {}).get(\"authorized\", False)\n  3052\t        if c_socks and c_auth:\n  3053\t            sub = claude.get(\"oauth\", {}).get(\"subscription_type\", \"Pro\").upper()\n  3054\t            self.badge_claude.config(text=f\"Claude (:1015): ● {sub} OK\", fg=C[\"green\"])\n  3055\t        elif c_socks:\n  3056\t            self.badge_claude.config(text=\"Claude (:1015): ● NO AUTH\", fg=C[\"yellow\"])\n  3057\t        else:\n  3058\t            self.badge_claude.config(text=\"Claude (:1015): ● OFFLINE\", fg=C[\"red\"])\n  3059\n  3060\t        # 4. Gemini\n  3061\t        gemini = res.get(\"gemini\", {})\n  3062\t        act_ports = gemini.get(\"active_ports\", [])\n  3063\t        tot_prof = gemini.get(\"total_profiles\", 0)\n  3064\t        if act_ports:\n  3065\t            self.badge_gemini.config(text=f\"Gemini Farm: ● {len(act_ports)}/{tot_prof} Online\", fg=C[\"green\"])\n  3066\t        elif tot_prof > 0:\n  3067\t            self.badge_gemini.config(text=f\"Gemini Farm: ● 0/{tot_prof} Offline\", fg=C[\"yellow\"])\n  3068\t        else:\n  3069\t            self.badge_gemini.config(text=\"Gemini Farm: ● 0 Profiles\", fg=C[\"subtext\"])\n  3070\n  3071\t        # Overall badge\n  3072\t        all_ok = aion.get(\"online\") and omni.get(\"online\") and c_socks and bool(act_ports)\n  3073\t        if all_ok:\n  3074\t            self.lbl_integ_overall.config(text=\"ACTIVE\", bg=C[\"green\"], fg=\"#11111b\")\n  3075\t        else:\n  3076\t            self.lbl_integ_overall.config(text=\"PARTIAL\", bg=C[\"yellow\"], fg=\"#11111b\")\n  3077\n  3078\t    def on_integrations_sync_claude_click(self):\n  3079\t        \"\"\"Синхронизация Claude Code.\"\"\"\n  3080\t        if getattr(self, \"_integ_task_running\", False):\n  3081\t            return\n  3082\t        self._integ_task_running = True\n  3083\t        self.btn_integ_sync_claude.config(state=\"disabled\", text=\"⏳ Синхронизация...\")\n  3084\t        self.lbl_integ_overall.config(text=\"SYNCING CLAUDE...\", bg=C[\"accent_peach\"], fg=\"#11111b\")\n  3085\n  3086\t        def worker():\n  3087\t            try:\n  3088\t                res = integrations_manager.sync_claude()\n  3089\t            except Exception as e:\n  3090\t                integrations_manager.logger.log(f\"Критическая ошибка синхронизации Claude: {e}\", \"ERROR\")\n  3091\t                res = {\"success\": False, \"error\": str(e)}\n  3092\n  3093\t            def done():\n  3094\t                self._integ_task_running = False\n  3095\t                self.btn_integ_sync_claude.config(state=\"normal\", text=t(\"btn_sync_claude\"))\n  3096\t                self.on_integrations_status_click()\n  3097\t            try:\n  3098\t                if not getattr(self, \"_closing\", False):\n  3099\t                    self.after(0, done)\n  3100\t            except Exception:\n  3101\t                pass\n  3102\n  3103\t        threading.Thread(target=worker, daemon=True).start()\n  3104\n  3105\t    def on_integrations_sync_gemini_click(self):\n  3106\t        \"\"\"Синхронизация Gemini Farm.\"\"\"\n  3107\t        if getattr(self, \"_integ_task_running\", False):\n  3108\t            return\n  3109\t        self._integ_task_running = True\n  3110\t        self.btn_integ_sync_gemini.config(state=\"disabled\", text=\"⏳ Синхронизация...\")\n  3111\t        self.lbl_integ_overall.config(text=\"SYNCING GEMINI...\", bg=C[\"accent_mauve\"], fg=\"#11111b\")\n  3112\n  3113\t        def worker():\n  3114\t            try:\n  3115\t                res = integrations_manager.sync_gemini()\n  3116\t            except Exception as e:\n  3117\t                integrations_manager.logger.log(f\"Критическая ошибка синхронизации Gemini: {e}\", \"ERROR\")\n  3118\t                res = {\"success\": False, \"error\": str(e)}\n  3119\n  3120\t            def done():\n  3121\t                self._integ_task_running = False\n  3122\t                self.btn_integ_sync_gemini.config(state=\"normal\", text=t(\"btn_sync_gemini\"))\n  3123\t                self.on_integrations_status_click()\n  3124\t            try:\n  3125\t                if not getattr(self, \"_closing\", False):\n  3126\t                    self.after(0, done)\n  3127\t            except Exception:\n  3128\t                pass\n  3129\n  3130\t        threading.Thread(target=worker, daemon=True).start()\n  3131\n  3132\t    def show_log_history_dialog(self):\n  3133\t        \"\"\"Окно просмотра истории логов с синхронизацией из файла.\"\"\"\n  3134\t        dlg = tk.Toplevel(self)\n  3135\t        dlg.title(t(\"dlg_log_history_title\"))\n  3136\t        dlg.geometry(\"860x580\")\n  3137\t        dlg.minsize(740, 480)\n  3138\t        dlg.configure(bg=C[\"bg\"])\n  3139\n  3140\t        top_f = tk.Frame(dlg, bg=C[\"bg\"])\n  3141\t        top_f.pack(fill=\"x\", padx=16, pady=(14, 8))\n  3142\n  3143\t        tk.Label(\n  3144\t            top_f, text=t(\"dlg_log_history_title\"), font=FONT_TITLE,\n  3145\t            fg=C[\"accent_blue\"], bg=C[\"bg\"]\n  3146\t        ).pack(side=\"left\")\n  3147\n  3148\t        dlg_stats_lbl = tk.Label(\n  3149\t            top_f,\n  3150\t            text=t(\"lbl_log_stats\", file=\"integrations.log\", size=integrations_manager.logger.get_file_size_str()),\n  3151\t            font=FONT_SUB, fg=C[\"subtext\"], bg=C[\"bg\"]\n  3152\t        )\n  3153\t        dlg_stats_lbl.pack(side=\"right\")\n  3154\n  3155\t        # Панель кнопок управления логами\n  3156\t        bar = tk.Frame(dlg, bg=C[\"bg\"])\n  3157\t        bar.pack(fill=\"x\", padx=16, pady=(0, 8))\n  3158\n  3159\t        card_wrap = tk.Frame(dlg, bg=C[\"card\"], bd=1, relief=\"solid\")\n  3160\t        card_wrap.configure(highlightbackground=C[\"border\"], highlightthickness=1)\n  3161\t        card_wrap.pack(fill=\"both\", expand=True, padx=16, pady=(0, 14))\n  3162\n  3163\t        txt = tk.Text(\n  3164\t            card_wrap, bg=\"#11111b\", fg=C[\"fg\"], insertbackground=C[\"fg\"],\n  3165\t            selectbackground=C[\"border\"], font=FONT_MONO, wrap=\"word\",\n  3166\t            relief=\"flat\", bd=0, padx=10, pady=10\n  3167\t        )\n  3168\t        sc = ttk.Scrollbar(card_wrap, orient=\"vertical\", command=txt.yview)\n  3169\t        txt.configure(yscrollcommand=sc.set)\n  3170\t        txt.pack(side=\"left\", fill=\"both\", expand=True)\n  3171\t        sc.pack(side=\"right\", fill=\"y\")\n  3172\n  3173\t        txt.tag_config(\"TIMESTAMP\", foreground=\"#6c7086\")\n  3174\t        txt.tag_config(\"INFO\", foreground=\"#cdd6f4\")\n  3175\t        txt.tag_config(\"SUCCESS\", foreground=C[\"green\"])\n  3176\t        txt.tag_config(\"WARN\", foreground=C[\"yellow\"])\n  3177\t        txt.tag_config(\"ERROR\", foreground=C[\"red\"])\n  3178\t        txt.tag_config(\"STEP\", foreground=C[\"accent_blue\"], font=FONT_MONO_BOLD)\n  3179\t        txt.tag_config(\"SYSTEM\", foreground=C[\"accent_mauve\"])\n  3180\n  3181\t        def load_content():\n  3182\t            content = integrations_manager.logger.read_history()\n  3183\t            txt.config(state=\"normal\")\n  3184\t            txt.delete(\"1.0\", \"end\")\n  3185\t            for line in content.splitlines():\n  3186\t                lvl = \"INFO\"\n  3187\t                if \"[SUCCESS]\" in line:\n  3188\t                    lvl = \"SUCCESS\"\n  3189\t                elif \"[WARN]\" in line:\n  3190\t                    lvl = \"WARN\"\n  3191\t                elif \"[ERROR]\" in line:\n  3192\t                    lvl = \"ERROR\"\n  3193\t                elif \"[STEP]\" in line:\n  3194\t                    lvl = \"STEP\"\n  3195\t                elif \"[SYSTEM]\" in line:\n  3196\t                    lvl = \"SYSTEM\"\n  3197\t                txt.insert(\"end\", line + \"\\n\", lvl)\n  3198\t            txt.see(\"end\")\n  3199\t            txt.config(state=\"disabled\")\n  3200\t            sz = integrations_manager.logger.get_file_size_str()\n  3201\t            dlg_stats_lbl.config(text=t(\"lbl_log_stats\", file=\"integrations.log\", size=sz))\n  3202\n  3203\t        def copy_all():\n  3204\t            content = integrations_manager.logger.read_history()\n  3205\t            self.clipboard_clear()\n  3206\t            self.clipboard_append(content)\n  3207\t            messagebox.showinfo(t(\"app_name\"), t(\"msg_copied_clipboard\"), parent=dlg)\n  3208\n  3209\t        def clear_file():\n  3210\t            if messagebox.askyesno(t(\"app_name\"), t(\"msg_confirm_clear_log\"), parent=dlg):\n  3211\t                integrations_manager.logger.clear_history()\n  3212\t                load_content()\n  3213\t                self._update_log_stats_label()\n  3214\t                messagebox.showinfo(t(\"app_name\"), t(\"msg_log_cleared\"), parent=dlg)\n  3215\n  3216\t        btn_reload = tk.Button(\n  3217\t            bar, text=t(\"btn_reload_log\"), font=FONT_BOLD,\n  3218\t            bg=C[\"accent_blue\"], fg=\"#11111b\", activebackground=\"#b4befe\",\n  3219\t            bd=0, padx=12, pady=5, cursor=\"hand2\", command=load_content\n  3220\t        )\n  3221\t        btn_reload.pack(side=\"left\", padx=(0, 6))\n  3222\n  3223\t        btn_copy = tk.Button(\n  3224\t            bar, text=t(\"btn_copy_all\"), font=FONT_MAIN,\n  3225\t            bg=C[\"card_inner\"], fg=C[\"fg\"], activebackground=C[\"border\"],\n  3226\t            bd=0, padx=12, pady=5, cursor=\"hand2\", command=copy_all\n  3227\t        )\n  3228\t        btn_copy.pack(side=\"left\", padx=6)\n  3229\n  3230\t        btn_clear = tk.Button(\n  3231\t            bar, text=t(\"btn_clear_log_file\"), font=FONT_MAIN,\n  3232\t            bg=C[\"card_inner\"], fg=C[\"red\"], activebackground=C[\"border\"],\n  3233\t            bd=0, padx=12, pady=5, cursor=\"hand2\", command=clear_file\n  3234\t        )\n  3235\t        btn_clear.pack(side=\"left\", padx=6)\n  3236\n  3237\t        btn_close = tk.Button(\n  3238\t            bar, text=t(\"btn_close_dialog\"), font=FONT_MAIN,\n  3239\t            bg=C[\"card_inner\"], fg=C[\"subtext\"], activebackground=C[\"border\"],\n  3240\t            bd=0, padx=12, pady=5, cursor=\"hand2\", command=dlg.destroy\n  3241\t        )\n  3242\t        btn_close.pack(side=\"right\")\n  3243\n  3244\t        load_content()\n  3245\n  3246\t    # =========================================================================\n  3247\t    # ОБЩАЯ ЛОГИКА И СТАТУС\n  3248\t    # =========================================================================\n  3249\t    def on_global_refresh(self):\n  3250\t        \"\"\"Кнопка ''Проверить всё''.\"\"\"\n  3251\t        self.refresh_routes_async()\n  3252\t        if self.active_tab == \"proxy\":\n  3253\t            self.check_current_proxy_page_async()\n  3254\t        elif self.active_tab == \"gemini\":\n  3255\t            self.refresh_gemini_profiles_async()\n  3256\t        elif self.active_tab == \"strategy\":\n  3257\t            self.render_strategy_page()\n  3258\t        elif self.active_tab == \"backup\":\n  3259\t            self.render_backup_page()\n  3260\t        elif self.active_tab == \"integrations\":\n  3261\t            self.on_integrations_status_click()\n  3262\n  3263\t    def refresh_routes_async(self):\n  3264\t        \"\"\"Запуск фоновой проверки маршрутов.\"\"\"\n  3265\t        if self.is_checking_routes:\n  3266\t            return\n  3267\n  3268\t        self.is_checking_routes = True\n  3269\t        self.refresh_btn.config(state=\"disabled\", text=\"⏳ Проверка...\")\n  3270\t        self.quick_status.config(text=\"● Опрос WSL2 и маршрутов...\", fg=C[\"yellow\"])\n  3271\n  3272\t        def worker():\n  3273\t            try:\n  3274\t                res = sync_manager.check_all_routes()\n  3275\t                if not getattr(self, \"_closing\", False):\n  3276\t                    self.after(0, self._apply_route_results, res)\n  3277\t            except Exception as e:\n  3278\t                def _handle_err():\n  3279\t                    self.is_checking_routes = False\n  3280\t                    self.refresh_btn.config(state=\"normal\", text=t(\"btn_check_all\"))\n  3281\t                    self.quick_status.config(text=f\"✕ Ошибка проверки: {e}\", fg=C[\"red\"])\n  3282\t                try:\n  3283\t                    if not getattr(self, \"_closing\", False):\n  3284\t                        self.after(0, _handle_err)\n  3285\t                except Exception:\n  3286\t                    pass\n  3287\n  3288\t        threading.Thread(target=worker, daemon=True).start()\n  3289\n  3290\t    def _apply_route_results(self, res: dict):\n  3291\t        self.is_checking_routes = False\n  3292\t        self.refresh_btn.config(state=\"normal\", text=t(\"btn_check_all\"))\n  3293\t        self.last_check_lbl.config(text=t(\"lbl_last_check\", time=res.get(\"timestamp\", \"--:--:--\")))\n  3294\n  3295\t        gemini = res.get(\"gemini\", {})\n  3296\t        claude = res.get(\"claude\", {})\n  3297\t        herdr = res.get(\"herdr_wsl\", {})\n  3298\n  3299\t        # 1. Herdr в WSL2\n  3300\t        if herdr.get(\"server_running\"):\n  3301\t            self.herdr_badge.config(\n  3302\t                text=f\"{t(''herdr_badge_active'')} ({herdr.get(''pane_count'', 0)})\",\n  3303\t                bg=C[\"green\"], fg=\"#11111b\"\n  3304\t            )\n  3305\t            agents = herdr.get(\"agents\", [])\n  3306\t            lines = []\n  3307\t            for a in agents:\n  3308\t                agent_name = a.get(\"agent\", \"unknown\")\n  3309\t                status = a.get(\"status\", \"running\")\n  3310\t                pane_id = a.get(\"pane_id\", \"\")\n  3311\t                if agent_name == \"agy\":\n  3312\t                    icon = \"🔮\"\n  3313\t                    desc = \"AGY CLI (Gemini) • SOCKS5\"\n  3314\t                elif agent_name == \"claude\":\n  3315\t                    icon = \"🧡\"\n  3316\t                    desc = \"Claude Code • Direct IP\"\n  3317\t                else:\n  3318\t                    icon = \"💻\"\n  3319\t                    desc = f\"{t(''pane_terminal'')} ({agent_name})\"\n  3320\t                lines.append(f\"{icon} {t(''pane_panel'')} {pane_id}: {desc} | {t(''pane_status'')}: [{status}]\")\n  3321\n  3322\t            if lines:\n  3323\t                self.herdr_panes_lbl.config(text=\"\\n\".join(lines), fg=C[\"fg\"])\n  3324\t            else:\n  3325\t                self.herdr_panes_lbl.config(text=t(\"herdr_no_panes\"), fg=C[\"subtext\"])\n  3326\t        else:\n  3327\t            self.herdr_badge.config(text=t(\"herdr_not_running\"), bg=C[\"red\"], fg=\"#11111b\")\n  3328\t            self.herdr_panes_lbl.config(\n  3329\t                text=t(\"herdr_wsl_stopped\"),\n  3330\t                fg=C[\"red\"]\n  3331\t            )\n  3332\n  3333\t        # 2. Gemini\n  3334\t        active_port = gemini.get(\"port\", gemini_manager.BASE_SOCKS5_PORT)\n  3335\t        active_route = gemini.get(\"route\", f\"socks5h://127.0.0.1:{active_port}\")\n  3336\t        self.gemini_route_lbl.config(text=f\"{active_route} ({t(''pill_socks5'')})\")\n  3337\n  3338\t        if gemini.get(\"failback_occurred\"):\n  3339\t            fb_msg = gemini.get(\"failback_msg\", \"Auto-failback to bound proxy\")\n  3340\t            lat = gemini.get(\"latency_ms\")\n  3341\t            lat_str = f\" ({lat} ms)\" if lat else \"\"\n  3342\t            self.gemini_status_lbl.config(\n  3343\t                text=f\"✓ {fb_msg}\",\n  3344\t                fg=C[\"green\"]\n  3345\t            )\n  3346\t            self.gemini_ping_lbl.config(\n  3347\t                text=f\"SOCKS5 :{active_port}{lat_str}\",\n  3348\t                fg=C[\"green\"]\n  3349\t            )\n  3350\t            self.load_gemini_profiles_data()\n  3351\t            self.load_proxies_data()\n  3352\t            if self.active_tab == \"gemini\":\n  3353\t                self.render_gemini_page()\n  3354\t            elif self.active_tab == \"proxy\":\n  3355\t                self.render_proxy_table()\n  3356\t        elif gemini.get(\"failover_occurred\"):\n  3357\t            fo_msg = gemini.get(\"failover_msg\", \"Auto-failover triggered\")\n  3358\t            lat = gemini.get(\"latency_ms\")\n  3359\t            lat_str = f\" ({lat} ms)\" if lat else \"\"\n  3360\t            self.gemini_status_lbl.config(\n  3361\t                text=f\"🔄 {fo_msg}\",\n  3362\t                fg=C[\"accent_peach\"]\n  3363\t            )\n  3364\t            self.gemini_ping_lbl.config(\n  3365\t                text=f\"SOCKS5 :{active_port}{lat_str}\",\n  3366\t                fg=C[\"green\"] if gemini.get(\"online\") else C[\"red\"]\n  3367\t            )\n  3368\t            # Обновляем профили и прокси в интерфейсе, чтобы отразить новый порт\n  3369\t            self.load_gemini_profiles_data()\n  3370\t            self.load_proxies_data()\n  3371\t            if self.active_tab == \"gemini\":\n  3372\t                self.render_gemini_page()\n  3373\t            elif self.active_tab == \"proxy\":\n  3374\t                self.render_proxy_table()\n  3375\t        elif gemini.get(\"in_failover\"):\n  3376\t            target_port = gemini.get(\"bound_port\", gemini_manager.BASE_SOCKS5_PORT)\n  3377\t            rem_s = gemini.get(\"next_failback_sec\", 0)\n  3378\t            lat = gemini.get(\"latency_ms\")\n  3379\t            lat_str = f\" ({lat} ms)\" if lat else \"\"\n  3380\t            self.gemini_status_lbl.config(\n  3381\t                text=f\"🔄 Failover :{active_port} ➔ Стремится к :{target_port} (возврат через {rem_s}с)\",\n  3382\t                fg=C[\"accent_peach\"]\n  3383\t            )\n  3384\t            self.gemini_ping_lbl.config(\n  3385\t                text=f\"SOCKS5 :{active_port}{lat_str}\",\n  3386\t                fg=C[\"green\"] if gemini.get(\"online\") else C[\"red\"]\n  3387\t            )\n  3388\t        elif gemini.get(\"online\"):\n  3389\t            self.gemini_status_lbl.config(\n  3390\t                text=t(\"route_gemini_active\", port=active_port),\n  3391\t                fg=C[\"green\"]\n  3392\t            )\n  3393\t            lat = gemini.get(\"latency_ms\")\n  3394\t            self.gemini_ping_lbl.config(\n  3395\t                text=t(\"route_gemini_ping\", port=active_port, lat=lat),\n  3396\t                fg=C[\"green\"]\n  3397\t            )\n  3398\t        else:\n  3399\t            self.gemini_status_lbl.config(\n  3400\t                text=f\"✕ {gemini.get(''status_text'')}\",\n  3401\t                fg=C[\"red\"]\n  3402\t            )\n  3403\t            self.gemini_ping_lbl.config(\n  3404\t                text=t(\"route_gemini_offline\", port=active_port),\n  3405\t                fg=C[\"red\"]\n  3406\t            )\n  3407\n  3408\t        # 3. Claude\n  3409\t        self._last_claude_accessible = claude.get(\"online\", False)\n  3410\t        self._apply_claude_route_ui(claude)\n  3411\n  3412\t        # 4. Общий статус\n  3413\t        if herdr.get(\"server_running\") and gemini.get(\"online\") and claude.get(\"online\"):\n  3414\t            self.quick_status.config(text=t(\"status_herdr_active\"), fg=C[\"green\"])\n  3415\t        else:\n  3416\t            self.quick_status.config(text=t(\"status_monitoring_ok\"), fg=C[\"yellow\"])\n  3417\n  3418\t    def _apply_claude_route_ui(self, claude: dict):\n  3419\t        \"\"\"Обновляет элементы интерфейса маршрута Claude Code.\"\"\"\n  3420\t        c_host = claude.get(\"host\", settings_manager.get_claude_proxy_host())\n  3421\t        c_port = claude.get(\"port\", settings_manager.get_claude_proxy_port())\n  3422\t        c_http_port = claude.get(\"http_port\", 10000 + c_port)\n  3423\t        ks_engaged = claude.get(\"killswitch_engaged\", False)\n  3424\t        ks_enabled = claude.get(\"killswitch_enabled\", True)\n  3425\n  3426\t        if hasattr(self, \"claude_host_var\") and c_host:\n  3427\t            self.claude_host_var.set(str(c_host))\n  3428\t        if hasattr(self, \"claude_port_var\") and c_port:\n  3429\t            self.claude_port_var.set(str(c_port))\n  3430\t        self._update_claude_proxy_combo()\n  3431\n  3432\t        if hasattr(self, \"claude_ks_cb\"):\n  3433\t            self.claude_ks_cb.config(fg=C[\"red\"] if ks_enabled else C[\"subtext\"])\n  3434\n  3435\t        if claude.get(\"online\"):\n  3436\t            if hasattr(self, \"claude_pill\"):\n  3437\t                self.claude_pill.config(text=t(\"pill_claude_proxy\"), bg=C[\"green\"], fg=\"#11111b\")\n  3438\t            self.claude_status_lbl.config(\n  3439\t                text=claude.get(\"status_text\", t(\"route_claude_active\", host=c_host, port=c_port)),\n  3440\t                fg=C[\"green\"]\n  3441\t            )\n  3442\t            ip_str = claude.get(\"ip\", \"-\")\n  3443\t            co_str = claude.get(\"country\", \"\")\n  3444\t            lbl_ip = f\"{ip_str} ({co_str})\" if co_str and co_str != \"undefined\" else ip_str\n  3445\t            self.claude_ip_lbl.config(text=t(\"route_claude_ip\", ip=lbl_ip), fg=C[\"accent_peach\"])\n  3446\t            if hasattr(self, \"claude_route_lbl\"):\n  3447\t                self.claude_route_lbl.config(text=f\"http://{c_host}:{c_http_port} (SOCKS5 :{c_port})\")\n  3448\t            lat = claude.get(\"latency_ms\")\n  3449\t            self.claude_ping_lbl.config(\n  3450\t                text=t(\"route_claude_ping\", lat=lat),\n  3451\t                fg=C[\"green\"]\n  3452\t            )\n  3453\t        elif ks_engaged:\n  3454\t            if hasattr(self, \"claude_pill\"):\n  3455\t                self.claude_pill.config(text=t(\"pill_killswitch_engaged\"), bg=C[\"red\"], fg=\"#ffffff\")\n  3456\t            self.claude_status_lbl.config(\n  3457\t                text=claude.get(\"status_text\", t(\"route_claude_killswitch_active\", host=c_host, port=c_port)),\n  3458\t                fg=C[\"red\"]\n  3459\t            )\n  3460\t            self.claude_ip_lbl.config(text=\"🛡️ Прямой трафик заблокирован Killswitch\", fg=C[\"red\"])\n  3461\t            if hasattr(self, \"claude_route_lbl\"):\n  3462\t                self.claude_route_lbl.config(text=f\"http://{c_host}:{c_http_port} [KILLSWITCH BLOCK]\")\n  3463\t            self.claude_ping_lbl.config(text=\"Ожидание восстановления прокси...\", fg=C[\"red\"])\n  3464\t        else:\n  3465\t            if hasattr(self, \"claude_pill\"):\n  3466\t                self.claude_pill.config(text=\"✕ ОФЛАЙН\", bg=C[\"subtext\"], fg=\"#ffffff\")\n  3467\t            self.claude_status_lbl.config(\n  3468\t                text=claude.get(\"status_text\", f\"✕ {t(''route_claude_offline'')}\"),\n  3469\t                fg=C[\"red\"]\n  3470\t            )\n  3471\t            self.claude_ip_lbl.config(text=claude.get(\"ip\", \"-\"), fg=C[\"subtext\"])\n  3472\t            if hasattr(self, \"claude_route_lbl\"):\n  3473\t                self.claude_route_lbl.config(text=f\"http://{c_host}:{c_http_port}\")\n  3474\t            self.claude_ping_lbl.config(text=t(\"route_claude_offline\"), fg=C[\"red\"])\n  3475\n  3476\t    def _schedule_fast_port_check(self):\n  3477\t        \"\"\"Регулярный быстрый опрос локальных SOCKS5-портов и мгновенное управление Killswitch.\"\"\"\n  3478\t        if self._closing:\n  3479\t            return\n  3480\n  3481\t        interval_sec = settings_manager.get_port_check_interval()\n  3482\t        interval_ms = int(interval_sec * 1000)\n  3483\n  3484\t        if not self._is_checking_fast_ports:\n  3485\t            self._is_checking_fast_ports = True\n  3486\n  3487\t            def worker():\n  3488\t                claude_res = None\n  3489\t                ports_changed = False\n  3490\t                try:\n  3491\t                    # 1. Быстрый опрос статуса локальных портов из proxies.json\n  3492\t                    ports_changed = proxy_manager.refresh_local_ports_status(self.proxies, timeout=0.15)\n  3493\t                    if ports_changed:\n  3494\t                        proxy_manager.save_proxies(self.proxies)\n  3495\n  3496\t                    # 2. Быстрая проверка целевого порта Claude Code\n  3497\t                    c_host = settings_manager.get_claude_proxy_host()\n  3498\t                    c_port = settings_manager.get_claude_proxy_port()\n  3499\t                    c_ks = settings_manager.get_claude_killswitch()\n  3500\t                    port_ok = claude_manager.check_port_accessible(c_host, c_port, timeout=0.15)\n  3501\n  3502\t                    if self._last_claude_accessible != port_ok:\n  3503\t                        self._last_claude_accessible = port_ok\n  3504\t                        claude_res = claude_manager.probe_claude_route(\n  3505\t                            host=c_host, port=c_port, killswitch=c_ks, fast=True\n  3506\t                        )\n  3507\t                except Exception:\n  3508\t                    pass\n  3509\t                finally:\n  3510\t                    self._is_checking_fast_ports = False\n  3511\n  3512\t                if not self._closing:\n  3513\t                    self.after(0, self._apply_fast_port_results, claude_res, ports_changed)\n  3514\n  3515\t            threading.Thread(target=worker, daemon=True).start()\n  3516\n  3517\t        if not self._closing:\n  3518\t            self.after(interval_ms, self._schedule_fast_port_check)\n  3519\n  3520\t    def _apply_fast_port_results(self, claude_res: dict | None, ports_changed: bool):\n  3521\t        if self._closing:\n  3522\t            return\n  3523\t        if ports_changed and self.active_tab == \"proxy\":\n  3524\t            self.render_proxy_table()\n  3525\t        if claude_res is not None:\n  3526\t            self._apply_claude_route_ui(claude_res)\n  3527\n  3528\t    def _schedule_auto_refresh(self):\n  3529\t        if self.auto_refresh_enabled.get() and not self.is_checking_routes:\n  3530\t            self.refresh_routes_async()\n  3531\n  3532\t        # Фоновая проверка планового автобэкапа\n  3533\t        try:\n  3534\t            threading.Thread(target=backup_manager.check_and_run_auto_backup, daemon=True).start()\n  3535\t        except Exception:\n  3536\t            pass\n  3537\n  3538\t        self.after(15000, self._schedule_auto_refresh)\n  3539\n  3540\t    # ── Системный трей ──────────────────────────────────────────\n  3541\t    def _init_tray(self):\n  3542\t        if not HAS_TRAY:\n  3543\t            return\n  3544\n  3545\t        icon_img = make_tray_icon(\"blue\")\n  3546\t        menu = pystray.Menu(\n  3547\t            pystray.MenuItem(t(\"tray_show\"), self.show_window, default=True),\n  3548\t            pystray.Menu.SEPARATOR,\n  3549\t            pystray.MenuItem(t(\"tray_exit\"), self.quit_app)\n  3550\t        )\n  3551\t        self.tray_icon = pystray.Icon(\"herdr_router\", icon_img, t(\"app_name\"), menu)\n  3552\n  3553\t        try:\n  3554\t            self.tray_icon.run_detached()\n  3555\t        except Exception:\n  3556\t            pass\n  3557\n  3558\t    def on_close_button(self):\n  3559\t        if HAS_TRAY:\n  3560\t            if not self.tray_icon:\n  3561\t                self._init_tray()\n  3562\t            self.withdraw()\n  3563\t            try:\n  3564\t                if self.tray_icon:\n  3565\t                    self.tray_icon.notify(t(\"tray_minimized_msg\"), t(\"app_name\"))\n  3566\t            except Exception:\n  3567\t                pass\n  3568\t        else:\n  3569\t            self.destroy()\n  3570\n  3571\t    def bring_to_front(self):\n  3572\t        try:\n  3573\t            self.deiconify()\n  3574\t            self.state(\"normal\")\n  3575\t            self.lift()\n  3576\t            self.attributes(\"-topmost\", True)\n  3577\t            self.after_idle(self.attributes, \"-topmost\", False)\n  3578\t            self.focus_force()\n  3579\t        except Exception:\n  3580\t            pass\n  3581\n  3582\t    def show_window(self, icon=None, item=None):\n  3583\t        self.after(0, self.bring_to_front)\n  3584\n  3585\t    def quit_app(self, icon=None, item=None):\n  3586\t        self.after(0, self.destroy)\n  3587\n  3588\t    def destroy(self):\n  3589\t        self._closing = True\n  3590\t        if hasattr(self, \"_on_integration_log_cb\"):\n  3591\t            try:\n  3592\t                integrations_manager.logger.remove_listener(self._on_integration_log_cb)\n  3593\t            except Exception:\n  3594\t                pass\n  3595\t        if hasattr(self, \"tray_icon\") and self.tray_icon:\n  3596\t            try:\n  3597\t                self.tray_icon.stop()\n  3598\t            except Exception:\n  3599\t                pass\n  3600\t            self.tray_icon = None\n  3601\t        super().destroy()\n  3602\t_INSTANCE_SOCKET = None\n  3603\n  3604\n  3605\tdef _acquire_instance_lock() -> bool:\n  3606\t    \"\"\"Захватывает сокет единственного экземпляра приложения на порту SINGLE_INSTANCE_PORT (38123).\"\"\"\n  3607\t    global _INSTANCE_SOCKET\n  3608\t    try:\n  3609\t        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n  3610\t        s.bind((\"127.0.0.1\", SINGLE_INSTANCE_PORT))\n  3611\t        s.listen(5)\n  3612\t        _INSTANCE_SOCKET = s\n  3613\t        return True\n  3614\t    except OSError:\n  3615\t        return False\n  3616\n  3617\n  3618\tdef _release_instance_lock() -> None:\n  3619\t    \"\"\"Освобождает сокет приложения.\"\"\"\n  3620\t    global _INSTANCE_SOCKET\n  3621\t    if _INSTANCE_SOCKET is not None:\n  3622\t        try:\n  3623\t            _INSTANCE_SOCKET.close()\n  3624\t        except Exception:\n  3625\t            pass\n  3626\t        _INSTANCE_SOCKET = None\n  3627\n  3628\n  3629\tdef start_instance_server(app: HerdrConfigApp):\n  3630\t    \"\"\"Слушает входящие сигналы SHOW на уже захваченном сокете для передачи фокуса главному окну.\"\"\"\n  3631\t    global _INSTANCE_SOCKET\n  3632\t    if _INSTANCE_SOCKET is None:\n  3633\t        return\n  3634\n  3635\t    def server_loop():\n  3636\t        while _INSTANCE_SOCKET:\n  3637\t            try:\n  3638\t                conn, _ = _INSTANCE_SOCKET.accept()\n  3639\t                with conn:\n  3640\t                    try:\n  3641\t                        data = conn.recv(1024)\n  3642\t                        if b\"SHOW\" in data:\n  3643\t                            app.after(0, app.bring_to_front)\n  3644\t                    except Exception:\n  3645\t                        pass\n  3646\t            except Exception:\n  3647\t                break\n  3648\n  3649\t    t = threading.Thread(target=server_loop, daemon=True)\n  3650\t    t.start()\n  3651\n  3652\n  3653\tdef _show_already_running_notice(duration_ms: int = 1200) -> None:\n  3654\t    \"\"\"Отображает окно уведомления о том, что программа уже запущена, на duration_ms миллисекунд и закрывается.\"\"\"\n  3655\t    try:\n  3656\t        root = tk.Tk()\n  3657\t        root.title(\"Herdr Control Center\")\n  3658\t        root.overrideredirect(True)\n  3659\t        root.attributes(\"-topmost\", True)\n  3660\t        root.configure(bg=\"#1e1e2e\")\n  3661\n  3662\t        frame = tk.Frame(root, bg=\"#1e1e2e\", highlightbackground=\"#89b4fa\", highlightthickness=2, padx=24, pady=16)\n  3663\t        frame.pack(fill=\"both\", expand=True)\n  3664\n  3665\t        tk.Label(\n  3666\t            frame,\n  3667\t            text=\"⚠️  \" + t(\"already_running\"),\n  3668\t            font=(\"Segoe UI\", 11, \"bold\"),\n  3669\t            fg=\"#cdd6f4\",\n  3670\t            bg=\"#1e1e2e\"\n  3671\t        ).pack()\n  3672\n  3673\t        root.update_idletasks()\n  3674\t        w = root.winfo_reqwidth()\n  3675\t        h = root.winfo_reqheight()\n  3676\t        sw = root.winfo_screenwidth()\n  3677\t        sh = root.winfo_screenheight()\n  3678\t        x = (sw - w) // 2\n  3679\t        y = (sh - h) // 2\n  3680\t        root.geometry(f\"{w}x{h}+{x}+{y}\")\n  3681\n  3682\t        root.after(duration_ms, root.destroy)\n  3683\t        root.mainloop()\n  3684\t    except Exception:\n  3685\t        pass\n  3686\n  3687\n  3688\tdef main():\n  3689\t    print(f\"[{time.strftime(''%X'')}] main() start PID={os.getpid()}\", flush=True)\n  3690\t    if not _acquire_instance_lock():\n  3691\t        print(f\"[{time.strftime(''%X'')}] PID={os.getpid()} _acquire_instance_lock failed! Already running.\", flush=True)\n  3692\t        try:\n  3693\t            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n  3694\t                s.settimeout(0.3)\n  3695\t                s.connect((\"127.0.0.1\", SINGLE_INSTANCE_PORT))\n  3696\t                s.sendall(b\"SHOW\\n\")\n  3697\t        except Exception:\n  3698\t            pass\n  3699\t        _show_already_running_notice(1200)\n  3700\t        return 0\n  3701\n  3702\t    print(f\"[{time.strftime(''%X'')}] PID={os.getpid()} lock acquired, initializing HerdrConfigApp\", flush=True)\n  3703\t    try:\n  3704\t        app = HerdrConfigApp()\n  3705\t        print(f\"[{time.strftime(''%X'')}] PID={os.getpid()} HerdrConfigApp initialized, starting server\", flush=True)\n  3706\t        start_instance_server(app)\n  3707\t        print(f\"[{time.strftime(''%X'')}] PID={os.getpid()} entering mainloop\", flush=True)\n  3708\t        app.mainloop()\n  3709\t        print(f\"[{time.strftime(''%X'')}] PID={os.getpid()} mainloop exited cleanly\", flush=True)\n  3710\t    except BaseException:\n  3711\t        print(f\"[{time.strftime(''%X'')}] PID={os.getpid()} EXCEPTION in mainloop:\", flush=True)\n  3712\t        traceback.print_exc()\n  3713\t        with open(BASE_DIR / \"crash.log\", \"w\", encoding=\"utf-8\") as f:\n  3714\t            traceback.print_exc(file=f)\n  3715\t        raise\n  3716\t    finally:\n  3717\t        _release_instance_lock()\n  3718\n  3719\n  3720\tif __name__ == \"__main__\":\n  3721\t    main()"}','left','finish',0,1790228164268,NULL);
INSERT INTO "messages" VALUES('8a7252a9','96eb91fc','8a7252a9','thinking','{"content":"**Adapting Code for Claude**\n\nI''m making excellent progress; I''ve successfully implemented changes. The focus has been on adapting the code to seamlessly integrate with Claude. Modifications are going well, and I''m on track to deliver a smooth transition to the new framework!\n\n\n","status":"done","duration_ms":9}','left','finish',0,1790228171405,NULL);
