INSERT INTO "messages" VALUES('aionrs-call_252004','96eb91fc','aionrs-call_252004','tool_call','{"call_id":"aionrs-call_252004","name":"Read","args":{"file_path":"/mnt/d/My files/herdrControlGui/backup_manager.py","offset":220,"limit":100},"status":"completed","input":{"file_path":"/mnt/d/My files/herdrControlGui/backup_manager.py","offset":220,"limit":100},"output":"   221\t) -> tuple[bool, str, str | None]:\n   222\t    \"\"\"Создает зашифрованный AES-256-GCM архив со всеми файлами и токенами.\n   223\n   224\t    Возвращает (success, message, file_path)\n   225\t    \"\"\"\n   226\t    if not password:\n   227\t        return False, \"Пароль для шифрования не может быть пустым.\", None\n   228\n   229\t    if target_dir is None:\n   230\t        cfg = get_backup_config()\n   231\t        target_dir = Path(cfg.get(\"backup_dir\", DEFAULT_BACKUP_DIR))\n   232\t    else:\n   233\t        target_dir = Path(target_dir)\n   234\n   235\t    try:\n   236\t        target_dir.mkdir(parents=True, exist_ok=True)\n   237\t    except Exception as e:\n   238\t        return False, f\"Не удалось создать папку бэкапа {target_dir}: {e}\", None\n   239\n   240\t    # 1. Формируем ZIP-архив в памяти\n   241\t    zip_buffer = io.BytesIO()\n   242\t    files_packed = 0\n   243\n   244\t    with zipfile.ZipFile(zip_buffer, \"w\", zipfile.ZIP_DEFLATED) as zf:\n   245\t        # 1.1 Файлы Windows Herdr (настройки, прокси, история, лог интеграций)\n   246\t        win_files = [\n   247\t            \"settings.json\",\n   248\t            \"proxies.json\",\n   249\t            \".env\",\n   250\t            \"strategy_history.json\",\n   251\t            \"integrations.log\",\n   252\t        ]\n   253\t        for fn in win_files:\n   254\t            fp = BASE_DIR / fn\n   255\t            if fp.exists():\n   256\t                zf.write(fp, arcname=f\"win/{fn}\")\n   257\t                files_packed += 1\n   258\n   259\t        # 1.2 Файлы Claude Code (Windows)\n   260\t        if WIN_CLAUDE_DIR.exists():\n   261\t            for fn in [\".credentials.json\", \"settings.json\"]:\n   262\t                fp = WIN_CLAUDE_DIR / fn\n   263\t                if fp.exists():\n   264\t                    zf.write(fp, arcname=f\"claude/win/{fn}\")\n   265\t                    files_packed += 1\n   266\t            for bak in WIN_CLAUDE_DIR.glob(\".credentials.json.bak_*\"):\n   267\t                if bak.is_file():\n   268\t                    zf.write(bak, arcname=f\"claude/win/{bak.name}\")\n   269\t                    files_packed += 1\n   270\n   271\t        # 1.3 Файлы Claude Code (WSL2)\n   272\t        if WSL_CLAUDE_DIR.exists():\n   273\t            for fn in [\".credentials.json\", \"settings.json\"]:\n   274\t                fp = WSL_CLAUDE_DIR / fn\n   275\t                if fp.exists():\n   276\t                    zf.write(fp, arcname=f\"claude/wsl/{fn}\")\n   277\t                    files_packed += 1\n   278\t            for bak in WSL_CLAUDE_DIR.glob(\".credentials.json.bak_*\"):\n   279\t                if bak.is_file():\n   280\t                    zf.write(bak, arcname=f\"claude/wsl/{bak.name}\")\n   281\t                    files_packed += 1\n   282\n   283\t            # Профили Claude OAuth (~/.claude/oauth-profiles/<имя>/): только токены и метаданные\n   284\t            oauth_dir = WSL_CLAUDE_DIR / CLAUDE_OAUTH_PROFILES_DIRNAME\n   285\t            if oauth_dir.exists():\n   286\t                for prof_dir in sorted(p for p in oauth_dir.iterdir() if p.is_dir()):\n   287\t                    for fn in CLAUDE_OAUTH_PROFILE_FILES:\n   288\t                        fp = prof_dir / fn\n   289\t                        if fp.is_file():\n   290\t                            zf.write(fp, arcname=f\"claude/wsl/{CLAUDE_OAUTH_PROFILES_DIRNAME}/{prof_dir.name}/{fn}\")\n   291\t                            files_packed += 1\n   292\n   293\t        # 1.4 Файлы AionUi (WSL2: SQLite база данных, настройки расширений, манифест)\n   294\t        if WSL_AIONUI_DIR.exists():\n   295\t            for fn in [\"aionui-backend.db\", \"extension-states.json\", \"extension-user-states.json\"]:\n   296\t                fp = WSL_AIONUI_DIR / fn\n   297\t                if fp.exists():\n   298\t                    try:\n   299\t                        zf.write(fp, arcname=f\"aionui/wsl/{fn}\")\n   300\t                        files_packed += 1\n   301\t                    except Exception:\n   302\t                        pass\n   303\t            fp_man = WSL_AIONUI_DIR / \"resources\" / \"manifest.json\"\n   304\t            if fp_man.exists():\n   305\t                try:\n   306\t                    zf.write(fp_man, arcname=\"aionui/wsl/resources/manifest.json\")\n   307\t                    files_packed += 1\n   308\t                except Exception:\n   309\t                    pass\n   310\n   311\t        # 1.5 Файлы AionUi (Windows)\n   312\t        if WIN_AIONUI_DIR.exists():\n   313\t            for fn in [\"aionui-backend.db\", \"extension-states.json\", \"extension-user-states.json\"]:\n   314\t                fp = WIN_AIONUI_DIR / fn\n   315\t                if fp.exists():\n   316\t                    try:\n   317\t                        zf.write(fp, arcname=f\"aionui/win/{fn}\")\n   318\t                        files_packed += 1\n   319\t                    except Exception:\n   320\t                        pass"}','left','finish',0,1790229855684,NULL);
