INSERT INTO "messages" VALUES('aionrs-call_240014','96eb91fc','aionrs-call_240014','tool_call','{"call_id":"aionrs-call_240014","name":"Read","args":{"offset":0,"file_path":"/mnt/d/My files/herdrControlGui/token_meta_cache.py","limit":100},"status":"completed","input":{"offset":0,"file_path":"/mnt/d/My files/herdrControlGui/token_meta_cache.py","limit":100},"output":"     1\timport json\n     2\timport os\n     3\tfrom pathlib import Path\n     4\timport backup_manager\n     5\n     6\tMETA_FILE = backup_manager.WSL_BASE_DIR / \".herdr_vault_meta.json\"\n     7\n     8\tdef _load():\n     9\t    if META_FILE.exists():\n    10\t        try:\n    11\t            return json.loads(META_FILE.read_text(encoding=\"utf-8\"))\n    12\t        except Exception:\n    13\t            pass\n    14\t    return {\"gemini\": {}, \"claude\": {}}\n    15\n    16\tdef _save(d):\n    17\t    try:\n    18\t        META_FILE.parent.mkdir(parents=True, exist_ok=True)\n    19\t        META_FILE.write_text(json.dumps(d, indent=2, ensure_ascii=False), encoding=\"utf-8\")\n    20\t    except Exception:\n    21\t        pass\n    22\n    23\tdef update_meta(service: str, profile_name: str, info: dict):\n    24\t    safe_info = dict(info)\n    25\t    safe_info.pop(\"id_token\", None)\n    26\t    safe_info.pop(\"access_token\", None)\n    27\t    safe_info.pop(\"refresh_token\", None)\n    28\t    safe_info.pop(\"file_path\", None)\n    29\t    d = _load()\n    30\t    if service not in d:\n    31\t        d[service] = {}\n    32\t    d[service][profile_name] = safe_info\n    33\t    _save(d)\n    34\n    35\tdef get_meta(service: str, profile_name: str) -> dict:\n    36\t    return _load().get(service, {}).get(profile_name, {})"}','left','finish',0,1790229885314,NULL);
