 for enc_p in dec_paths:\n   136\t            enc_p.unlink(missing_ok=True)\n   137\n   138\t        return True, f\"Расшифровано файлов: {success_count}.\"\n   139\n   140\t    except Exception as e:\n   141\t        return False, f\"Ошибка при разблокировке: {e}\"\n   142\n   143\tif __name__ == \"__main__\":\n   144\t    import argparse\n   145\t    parser = argparse.ArgumentParser(description=\"CLI для управления Сейфом Токенов\")\n   146\t    parser.add_argument(\"--lock\", type=str, help=\"Заблокировать токены (пароль)\")\n   147\t    parser.add_argument(\"--unlock\", type=str, help=\"Разблокировать токены (пароль)\")\n   148\n   149\t    args = parser.parse_args()\n   150\t    if args.lock:\n   151\t        ok, msg = lock_tokens(args.lock)\n   152\t        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n   153\t    elif args.unlock:\n   154\t        ok, msg = unlock_tokens(args.unlock)\n   155\t        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n   156\t    else:\n   157\t        print(\"Статус хранилища:\", \"ЗАБЛОКИРОВАНО\" if is_vault_locked() else \"РАЗБЛОКИРОВАНО\")\n   158\n   159\tfrom contextlib import contextmanager\n   160\timport backup_manager\n   161\n   162\t@contextmanager\n   163\tdef auto_unlock_context(password: str = None):\n   164\t    \"\"\"Контекстный менеджер для временной разблокировки токенов при манипуляциях.\"\"\"\n   165\t    if password is None:\n   166\t        password = backup_manager.get_env_password()\n   167\n   168\t    was_locked = is_vault_locked()\n   169\t    if was_locked and password:\n   170\t        unlock_tokens(password)\n   171\n   172\t    try:\n   173\t        yield\n   174\t    finally:\n   175\t        if was_locked and password:\n   176\t            lock_tokens(password)\n   177\n   178\tdef ensure_locked():\n   179\t    \"\"\"Следит за тем, чтобы 99% времени токены оставались зашифрованными. Вызывается фоново.\"\"\"\n   180\t    pw = backup_manager.get_env_password()\n   181\t    if pw and not is_vault_locked():\n   182\t        lock_tokens(pw)"}','left','finish',0,1790230523278,NULL);
INSERT INTO "messages" VALUES('aionrs-call_294793','96eb91fc','aionrs-call_294793','tool_call','{"call_id":"aionrs-call_294793","name":"Edit","args":{"new_string":"    except Exception as e:\n        return False, f\"Ошибка при разблокировке: {e}\"\n\nfrom contextlib import contextmanager\n\n@contextmanager\ndef auto_unlock_context(password: str = None):\n    \"\"\"Контекстный менеджер для временной разблокировки токенов при манипуляциях.\"\"\"\n    if password is None:\n        password = backup_manager.get_env_password()\n\n    was_locked = is_vault_locked()\n    if was_locked and password:\n        unlock_tokens(password)\n\n    try:\n        yield\n    finally:\n        if was_locked and password:\n            lock_tokens(password)\n\ndef ensure_locked():\n    \"\"\"Следит за тем, чтобы 99% времени токены оставались зашифрованными.\"\"\"\n    pw = backup_manager.get_env_password()\n    if pw and not is_vault_locked():\n        lock_tokens(pw)\n\nif __name__ == \"__main__\":\n    import argparse\n    parser = argparse.ArgumentParser(description=\"CLI для управления Сейфом Токенов\")\n    parser.add_argument(\"--lock\", type=str, help=\"Заблокировать токены (пароль)\")\n    parser.add_argument(\"--unlock\", type=str, help=\"Разблокировать токены (пароль)\")\n\n    args = parser.parse_args()\n    if args.lock:\n        ok, msg = lock_tokens(args.lock)\n        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n    elif args.unlock:\n        ok, msg = unlock_tokens(args.unlock)\n        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n    else:\n        print(\"Статус хранилища:\", \"ЗАБЛОКИРОВАНО\" if is_vault_locked() else \"РАЗБЛОКИРОВАНО\")","old_string":"    except Exception as e:\n        return False, f\"Ошибка при разблокировке: {e}\"\n\nif __name__ == \"__main__\":\n    import argparse\n    parser = argparse.ArgumentParser(description=\"CLI для управления Сейфом Токенов\")\n    parser.add_argument(\"--lock\", type=str, help=\"Заблокировать токены (пароль)\")\n    p