INSERT INTO "messages" VALUES('aionrs-call_305274','96eb91fc','aionrs-call_305274','tool_call','{"call_id":"aionrs-call_305274","name":"ExecCommand","args":{"cmd":"cat << ''EOF'' >> \"/mnt/d/My files/herdrControlGui/token_vault_manager.py\"\nfrom contextlib import contextmanager\n\n@contextmanager\ndef auto_unlock_context(password: str = None):\n    \"\"\"Контекстный менеджер для временной разблокировки токенов при манипуляциях.\"\"\"\n    if password is None:\n        password = backup_manager.get_env_password()\n\n    was_locked = is_vault_locked()\n    if was_locked and password:\n        unlock_tokens(password)\n\n    try:\n        yield\n    finally:\n        if was_locked and password:\n            lock_tokens(password)\n\ndef ensure_locked():\n    \"\"\"Следит за тем, чтобы 99% времени токены оставались зашифрованными.\"\"\"\n    pw = backup_manager.get_env_password()\n    if pw and not is_vault_locked():\n        lock_tokens(pw)\n\nif __name__ == \"__main__\":\n    import argparse\n    parser = argparse.ArgumentParser(description=\"CLI для управления Сейфом Токенов\")\n    parser.add_argument(\"--lock\", type=str, help=\"Заблокировать токены (пароль)\")\n    parser.add_argument(\"--unlock\", type=str, help=\"Разблокировать токены (пароль)\")\n\n    args = parser.parse_args()\n    if args.lock:\n        ok, msg = lock_tokens(args.lock)\n        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n    elif args.unlock:\n        ok, msg = unlock_tokens(args.unlock)\n        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n    else:\n        print(\"Статус хранилища:\", \"ЗАБЛОКИРОВАНО\" if is_vault_locked() else \"РАЗБЛОКИРОВАНО\")\nEOF"},"status":"completed","input":{"cmd":"cat << ''EOF'' >> \"/mnt/d/My files/herdrControlGui/token_vault_manager.py\"\nfrom contextlib import contextmanager\n\n@contextmanager\ndef auto_unlock_context(password: str = None):\n    \"\"\"Контекстный менеджер для временной разблокировки токенов при манипуляциях.\"\"\"\n    if password is None:\n        password = backup_manager.get_env_password()\n\n    was_locked = is_vault_locked()\n    if was_locked and password:\n        unlock_tokens(password)\n\n    try:\n        yield\n    finally:\n        if was_locked and password:\n            lock_tokens(password)\n\ndef ensure_locked():\n    \"\"\"Следит за тем, чтобы 99% времени токены оставались зашифрованными.\"\"\"\n    pw = backup_manager.get_env_password()\n    if pw and not is_vault_locked():\n        lock_tokens(pw)\n\nif __name__ == \"__main__\":\n    import argparse\n    parser = argparse.ArgumentParser(description=\"CLI для управления Сейфом Токенов\")\n    parser.add_argument(\"--lock\", type=str, help=\"Заблокировать токены (пароль)\")\n    parser.add_argument(\"--unlock\", type=str, help=\"Разблокировать токены (пароль)\")\n\n    args = parser.parse_args()\n    if args.lock:\n        ok, msg = lock_tokens(args.lock)\n        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n    elif args.unlock:\n        ok, msg = unlock_tokens(args.unlock)\n        print(\"SUCCESS\" if ok else \"ERROR\", msg)\n    else:\n        print(\"Статус хранилища:\", \"ЗАБЛОКИРОВАНО\" if is_vault_locked() else \"РАЗБЛОКИРОВАНО\")\nEOF"},"output":"Exit code: 0\nSTDOUT:\n\nSTDERR:"}','left','finish',0,1790230544409,NULL);
INSERT INTO "messages" VALUES('aionrs-call_284232','96eb91fc','aionrs-call_284232','tool_call','{"call_id":"aionrs-call_284232","name":"ExecCommand","args":{"cmd":"sed -n ''940,980p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"status":"completed","input":{"cmd":"sed -n ''940,980p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"output":"Exit code: 0\nSTDOUT:\n            \"error\": f\"Ошибка соединения через SOCKS5 :{port}: {e}\",\n        }\n\ndef launch_add_account_terminal(profile_name: str | None = None) -> bool:\n    \"\"\"Запускает окно терминала с процедурой добавления нового аккаунта Google.\"\"\"\n    cmd_name = profile_name or f\"account-{len(list_profiles()) + 1}\"\n\n    port = get_profile_port(cmd_name)\n    reserve_new_profile_port(cmd_name, port)\n\n    http_port = 10000 + port\n    env_str = f\"ALL_PROXY=''socks5h://127.0.0.1:{port}'' HTTPS_PROXY=''http://127.0.0.1:{http_port}'' HTTP_PROXY=''http://127.0.0.1:{http_port}''\"\n\n    bash_cmd = (\n        f\"echo ''Проверка IP через SOCKS5 :{port}...'' ; \"\n        f\"env {env_str} curl --max-time 15 -s -4 -x socks5h://127.0.0.1:{port} ifconfig.me ; echo ; echo ; \"\n        f\"env {env_str} gemini-oauth add {cmd_name} ; \"\n        f\"echo; echo ''Готово.''; read -n 1 -s -r\"\n    )\n\n    try:\n        subprocess.Popen(\n            [\"wsl.exe\", \"-d\", WSL_DISTRO, \"-u\", WSL_USER, \"bash\", \"-lc\", bash_cmd],\n            creationflags=subprocess.CREATE_NEW_CONSOLE if hasattr(subprocess, \"CREATE_NEW_CONSOLE\") else 16,\n        )\n        return True\n    except Exception:\n        return False\n\ndef delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    try:\n        is_active = False\n        t_path = target / \"antigravity-oauth-token\"\n        if t_path.exists() and ACTIVE_TOKEN_FILE.exists():\n\nSTDERR:"}','left','finish',0,1790230549804,NULL);
INSERT INTO "messages" VALUES('aionrs-call_242992','96eb91fc','aionrs-call_242992','tool_call','{"call_id":"aionrs-call_242992","name":"Edit","args":{"replace_all":false,"new_string":"import token_vault_manager\n\ndef delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    with token_vault_manager.auto_unlock_context():\n        try:\n            is_active = False\n            t_path = target / \"antigravity-oauth-token\"","old_string":"def delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    try:\n        is_active = False\n        t_path = target / \"antigravity-oauth-token\"","file_path":"/mnt/d/My files/herdrControlGui/gemini_manager.py"},"status":"completed","input":{"replace_all":false,"new_string":"import token_vault_manager\n\ndef delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    with token_vault_manager.auto_unlock_context():\n        try:\n            is_active = False\n            t_path = target / \"antigravity-oauth-token\"","old_string":"def delete_profile(profile_name: str) -> tuple[bool, str]:\n    \"\"\"Удаляет сохраненный профиль.\"\"\"\n    target = PROFILES_DIR / profile_name\n    if not target.exists():\n        return False, \"Профиль не найден\"\n\n    try:\n        is_active = False\n        t_path = target / \"antigravity-oauth-token\"","file_path":"/mnt/d/My files/herdrControlGui/gemini_manager.py"},"output":"Edited /mnt/d/My files/herdrControlGui/gemini_manager.py: replaced 1 occurrence(s)"}','left','finish',0,1790230556525,NULL);
INSERT INTO "messages" VALUES('aionrs-call_208411','96eb91fc','aionrs-call_208411','tool_call','{"call_id":"aionrs-call_208411","name":"ExecCommand","args":{"cmd":"sed -n ''980,1010p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"status":"completed","input":{"cmd":"sed -n ''980,1010p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"output":"Exit code: 0\nSTDOUT:\n        try:\n            is_active = False\n            t_path = target / \"antigravity-oauth-token\"\n        if t_path.exists() and ACTIVE_TOKEN_FILE.exists():\n            active_info = get_token_info(ACTIVE_TOKEN_FILE)\n            target_info = get_token_info(t_path)\n            if active_info.get(\"email\") and active_info.get(\"email\") == target_info.get(\"email\"):\n                is_active = True\n\n        shutil.rmtree(target)\n        try:\n            settings_manager.clear_account_proxy_binding(profile_name)\n        except Exception:\n            pass\n\n        if is_active and ACTIVE_TOKEN_FILE.exists():\n            ACTIVE_TOKEN_FILE.unlink(missing_ok=True)\n        # Оставшиеся профили сдвигаются вверх по номерам и получают порты своих новых номеров\n        remaining = list_profiles()\n        if is_active:\n            remaining_with_token = [p for p in remaining if p.get(\"token_exists\")]\n            if remaining_with_token:\n                switch_profile(remaining_with_token[0][\"profile_name\"])\n\n        return True, f\"Профиль {profile_name} успешно удален\"\n    except Exception as e:\n        return False, f\"Ошибка удаления: {e}\"\n\ndef rename_profile(old_name: str, new_name: str) -> tuple[bool, str]:\n    \"\"\"Переименовывает существующий профиль, обновляя пути, конфигурации, привязки и метки.\"\"\"\n\nSTDERR:"}','left','finish',0,1790230561236,NULL);
