INSERT INTO "messages" VALUES('aionrs-call_238455','96eb91fc','aionrs-call_238455','tool_call','{"call_id":"aionrs-call_238455","name":"ExecCommand","args":{"cmd":"sed -n ''1010,1055p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"status":"completed","input":{"cmd":"sed -n ''1010,1055p'' \"/mnt/d/My files/herdrControlGui/gemini_manager.py\""},"output":"Exit code: 0\nSTDOUT:\n            return False, f\"Ошибка удаления: {e}\"\n\ndef rename_profile(old_name: str, new_name: str) -> tuple[bool, str]:\n    \"\"\"Переименовывает существующий профиль, обновляя пути, конфигурации, привязки и метки.\"\"\"\n    old_clean = (old_name or \"\").strip()\n    new_clean = (new_name or \"\").strip()\n\n    if not new_clean:\n        return False, \"Имя профиля не может быть пустым\"\n\n    if any(c in r''\\/:*?\"<>|'' for c in new_clean):\n        return False, \"Имя содержит недопустимые символы: \\\\ / : * ? \\\" < > |\"\n\n    if old_clean == new_clean:\n        return True, \"Имя не изменилось\"\n\n    old_dir = PROFILES_DIR / old_clean\n    if not old_dir.exists():\n        return False, f\"Профиль ''{old_clean}'' не найден\"\n\n    new_dir = PROFILES_DIR / new_clean\n    if new_dir.exists():\n        return False, f\"Профиль с именем ''{new_clean}'' уже существует\"\n\n    order = get_profile_order()\n    try:\n        # 1. Переименовываем каталог профиля\n        shutil.move(str(old_dir), str(new_dir))\n        save_profile_order([new_clean if n == old_clean else n for n in order])\n\n        # 2. Обновляем profile_config.json\n        cfg_file = new_dir / \"profile_config.json\"\n        cfg_data: dict[str, Any] = {\"profile_name\": new_clean}\n        if cfg_file.exists():\n            try:\n                with open(cfg_file, \"r\", encoding=\"utf-8\") as f:\n                    cfg_data = json.load(f)\n            except Exception:\n                pass\n        cfg_data[\"profile_name\"] = new_clean\n        try:\n            with open(cfg_file, \"w\", encoding=\"utf-8\") as f:\n                json.dump(cfg_data, f, indent=2)\n        except Exception:\n            pass\n\nSTDERR:"}','left','finish',0,1790230577141,NULL);
