INSERT INTO "messages" VALUES('aionrs-call_223836','96eb91fc','aionrs-call_223836','tool_call','{"call_id":"aionrs-call_223836","name":"Read","args":{"limit":200,"offset":100,"file_path":"/mnt/d/My files/herdrControlGui/config_app.py"},"status":"completed","input":{"limit":200,"offset":100,"file_path":"/mnt/d/My files/herdrControlGui/config_app.py"},"output":"   101\tFONT_TITLE = (\"Segoe UI\", 11, \"bold\")\n   102\tFONT_BOLD = (\"Segoe UI\", 9, \"bold\")\n   103\tFONT_MAIN = (\"Segoe UI\", 9)\n   104\tFONT_SUB = (\"Segoe UI\", 8)\n   105\tFONT_MONO = (\"Consolas\", 9)\n   106\tFONT_MONO_BOLD = (\"Consolas\", 9, \"bold\")\n   107\n   108\tSINGLE_INSTANCE_PORT = 38123\n   109\n   110\n   111\tdef make_tray_icon(color: str = \"blue\"):\n   112\t    \"\"\"Генерация яркой, контрастной иконки ''H'' для системного трея.\"\"\"\n   113\t    size = 64\n   114\t    img = Image.new(\"RGBA\", (size, size), (0, 0, 0, 0))\n   115\t    d = ImageDraw.Draw(img)\n   116\t    colors = {\n   117\t        \"blue\":   (\"#89b4fa\", \"#1e1e2e\"),\n   118\t        \"green\":  (\"#a6e3a1\", \"#1e1e2e\"),\n   119\t        \"red\":    (\"#f38ba8\", \"#1e1e2e\"),\n   120\t        \"yellow\": (\"#f9e2af\", \"#1e1e2e\"),\n   121\t    }\n   122\t    bg_col, fg_col = colors.get(color, colors[\"blue\"])\n   123\n   124\t    margin = 3\n   125\t    d.rounded_rectangle([margin, margin, size - margin, size - margin], radius=16, fill=bg_col, outline=\"#ffffff\", width=2)\n   126\n   127\t    x1, x2 = 18, 26\n   128\t    x3, x4 = 38, 46\n   129\t    y_t, y_b = 16, 48\n   130\t    ym_t, ym_b = 28, 36\n   131\t    d.rounded_rectangle([x1, y_t, x2, y_b], radius=3, fill=fg_col)\n   132\t    d.rounded_rectangle([x3, y_t, x4, y_b], radius=3, fill=fg_col)\n   133\t    d.rectangle([x2, ym_t, x3, ym_b], fill=fg_col)\n   134\t    return img\n   135\n   136\n   137\tclass HerdrConfigApp(tk.Tk):\n   138\t    def __init__(self):\n   139\t        super().__init__()\n   140\t        i18n.init_language()\n   141\t        self.title(t(\"app_title\"))\n   142\t        self.geometry(\"920x720\")\n   143\t        self.minsize(860, 640)\n   144\t        self.configure(bg=C[\"bg\"])\n   145\n   146\t        icon_path = BASE_DIR / \"app_icon.ico\"\n   147\t        if not icon_path.exists() and getattr(sys, \"_MEIPASS\", None):\n   148\t            icon_path = Path(sys._MEIPASS) / \"app_icon.ico\"\n   149\t        if icon_path.exists():\n   150\t            try:\n   151\t                self.iconbitmap(str(icon_path))\n   152\t            except Exception:\n   153\t                pass\n   154\n   155\t        self.tray_icon = None\n   156\t        self.protocol(\"WM_DELETE_WINDOW\", self.on_close_button)\n   157\n   158\t        # Состояние роутера и сохраняемые настройки\n   159\t        self.is_checking_routes = False\n   160\t        self.auto_refresh_enabled = tk.BooleanVar(value=settings_manager.get_setting(\"auto_refresh_routes\", True))\n   161\t        self.auto_refresh_enabled.trace_add(\n   162\t            \"write\", lambda *_: settings_manager.set_setting(\"auto_refresh_routes\", self.auto_refresh_enabled.get())\n   163\t        )\n   164\n   165\t        self.auto_proxy_failover_enabled = tk.BooleanVar(value=settings_manager.get_setting(\"auto_proxy_failover\", True))\n   166\t        self.auto_proxy_failover_enabled.trace_add(\n   167\t            \"write\", lambda *_: settings_manager.set_setting(\"auto_proxy_failover\", self.auto_proxy_failover_enabled.get())\n   168\t        )\n   169\n   170\t        # Язык интерфейса\n   171\t        self.current_lang_var = tk.StringVar(value=i18n.get_lang())\n   172\n   173\t        # Состояние Backup\n   174\t        b_cfg = backup_manager.get_backup_config()\n   175\t        self._suppress_backup_trace = False\n   176\t        self.backup_password_var = tk.StringVar(value=backup_manager.load_backup_password())\n   177\t        self.backup_dir_var = tk.StringVar(value=b_cfg.get(\"backup_dir\", str(backup_manager.DEFAULT_BACKUP_DIR)