INSERT INTO "skills" VALUES('skill_01a0d0f4-99e8-7a91-859b-c26c2a4a9b0e',NULL,'x-recruiter','用于在 X (x.com) 发布招聘帖子。包含文案规范、图片生成提示和自动化发布脚本。发布 AI 相关岗位或设计类岗位时优先使用。','/home/f/.aionui-web/builtin-skills/x-recruiter','builtin',1,NULL,1790212086248,1790248654910);
